DELETE FROM talent_prerequisites;
DELETE FROM talent_attributes;
DELETE FROM talents;

INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('against-all-odds', 'Against All Odds', 'Absolute Focus', 'Common', 'For each combat tag you have on your character, increase your damage by 2% (max of 14%).', '["Works in PvE combat, with each mob counting as an individual combat tag."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('emergency-reserves', 'Emergency Reserves', 'Absolute Focus', 'Common', 'When you get hit below 20% health, gain 20% tempo immediately.', '["3 minute cooldown.","Being hit can repeatedly proc Emergency Reserves as long as it is off cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unswayed', 'Unswayed', 'Absolute Focus', 'Common', 'The effects of Taunt and Encore no longer work on you. (+20 Sanity)', '["The Taunt Mantra, and the \"Cornered Fool\" Talent can no longer inflict \"Taunt\" on the user.","The Sing Mantra can no longer use the Talent \"Encore\" on the user, nullifying the stun effect.","Sing can still apply Charm/Overcharm to the user."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('kick-off', 'Kick Off', 'Acrobat', 'Common', 'You easily brush off shorter falls, taking no damage. Your first wall jump will always send you higher than normal. Gain a speed boost after wall jumping over a wall. (+6 Passive Agility)', '["Causes all falls to be considered \"shorter\" by 10 studs, also reducing larger falls.","Increases climb distance by ~15% when off cooldown.","Slide jumping now also slightly increases climb distance.","Has a cooldown of 3 seconds.","The Bounty Hunter''s Garb, Delver''s Duster, Sandrunner Wraps, and Abyss Wanderer''s Plate equipment items have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('steady-footing', 'Steady Footing', 'Acrobat', 'Common', 'You''re much more resistant to being pushed around. (+5 Carry Load, +2 Passive Agility)', '["Reduces knockback to the user by 20%. (stacks with \"Knockback Resistance\" equipment pip)","This effect allows opponents to easier combo off of attacks that knock the user back, causing it to be not recommended outside PvE.","Removes ice''s bonus slide distance, but does not affect the lowered friction when moving on ice.","This is a considerable downside to Frostdraw users, as there is no upside to this effect, it is not recommended.","The Fur Parka equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('time-to-go', 'Time To Go', 'Acrobat', 'Common', 'Taking a life grants a speed boost for 10 seconds. Taking a player''s life doubles the speed boost and the duration. (+1 Passive Agility)', '["Provides a 25% speed boost, doubling to 50% when killing a player.","Procs all speed boost related talents. (ex. Speed Demon)","Duration is visually represented by a red glow by the user''s eyes.","Can stack, allowing the user to build tremendous speed by executing multiple targets at once."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('an-ironsingers-instinct', 'An Ironsinger''s Instinct', 'Adaptive Arsenal', 'Rare', 'Successfully dodging an attack coats you in metal and reduces the damage of the next attack taken.', '["After dodging gain the Ironsinger''s Instinct status effect for 2 seconds, reducing the damage of the next hit by 60%.","The user visually gains a grey metallic shine upon for the duration, clearing on hit.","Has a cooldown of 18 seconds, starting immediately upon dodge."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('exposed-durability', 'Exposed Durability', 'Adaptive Arsenal', 'Common', 'Deal 10% more damage to opponents with no armor durability left.', '["Also affect players with no outfit (Stranded Outfit)","Always procs on your Basic Attacks if you have Berserk active, and with any attack against Berserk users."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('phantom-edge', 'Phantom Edge', 'Adaptive Arsenal', 'Rare', 'Your weapon Basic Attacks have +0.25 range.', '["It is greatly not recommended to spend a talent hand on this, as the effect of this talent is objectively unnoticeably minuscule.","Stacks with Duelist''s Lunge for more range."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('everchanging-aegis', 'Everchanging Aegis', 'Adept Caster', 'Rare', 'You take 20% less from attacks the same element as the last element you were hit with, but 10% more damage from attacks from different element.', '["Getting hit by another element immediately changes your resistance to that element. i.e Getting hit by Shadowcast Mantras while having Galebreathe resistance will immediately change your resistance type to Shadowcast and vice versa.","This means that multi-hitting Mantras are much less potent, even if your Everchanging Aegis type was not attuned to that Mantra.","Your Aegis type can swap on block, dodge, and parry. You do not need to actually be hit by the attack for the swap to occur, largely mitigating the downside.","Burn and self damage do not proc Everchanging Aegis.","The damage type you become resistant to is indicated by a colored shield, continuous damage of the same element will give a colored outline of the damage type.","Flamecharm: Orange / Frostdraw: Blue / Thundercall: Yellow / Galebreathe: Green / Shadowcast: Purple / Ironsing: Grey / Bloodrend: Red","Does not affect attacks that do not deal elemental damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('neural-overload', 'Neural Overload', 'Adept Caster', 'Advanced', 'You can input up to 4 copies of each Mantra ingredient instead of being limited to 3.', '["The Mantra Modifiers limit is increased from 3 -> 4, for copies of modifiers. (ex. max of 3 crystal lens -> max of 4 crystal lens)","Removing this talent after modifying mantras will not alter their pre-existing modifiers, keeping the benefit.","This will not change the maximum 12 mantra modification hard limit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('overflowing-dam', 'Overflowing Dam', 'Adept Caster', 'Rare', 'Having full Ether for 2 seconds or more grants an aura to your attacks that grant them 10% more damage.', '["For every point of Intelligence below 40, Overflowing Dam''s damage bonus will be reduced by 0.125%, having a minimum damage buff of 6.875% at 15 Intelligence.","For Warlock''s Mantle, you will gain a 5.625% damage buff at 5 Intelligence; for Khan with this equipment, you will gain a 5.25% damage buff at 2 Intelligence or a 5% damage buff at 0 Intelligence.","The damage buff applies the moment you reach 100% Ether, despite what the Talent description says.","The Warlock''s Mantle equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('perfect-flash', 'Perfect Flash', 'Adept Caster', 'Rare', 'Having over 95% health causes your mantras to do +25% damage. This damage bonus will scale down to 10% if your enemies are far away.', '["Poser''s ring won''t count towards the health threshold until sheathed, maintaining the bonus even after being \"damaged\"."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('wyverns-claw', 'Wyvern''s Claw', 'Aerial Dancer', 'Rare', 'You deal 10% more damage while airborne. Mantras receive a 5% damage increase instead.', '["Activates after not being in contact with a grounded surface for ~0.75 seconds.","Synergizes very well with uppercuts."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('aerogliding', 'Aerogliding', 'Aeromancer', 'Rare', 'When falling from a high place, hold spacebar to generate wind currents until you hit the floor. (+2 Passive Agility)', '["Has a windup of 1 second.","When active, create an aura that reduces fall speed and stopping fall damage.","Does not prevent existing fall damage, if user was already falling, Aerogliding may still damage the user upon activation.","Automatically ends after 5 seconds, although it can be reactivated midair up to 3 times, however the windup will cause the user to take fall damage.","By air stalling you can continually reactivate Aerogliding and prevent fall damage.","When active, also lightly pushes user forwards, giving the user control.","Greatly reduces height loss with glider, allowing for much longer distances to be traveled. (Stacks with Feathered Glider)","Was merged with the \"The Old Wind\" Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('aeronade', 'Aeronade', 'Aeromancer', 'Common', 'Your Galetrap automatically detonates on contact with an object. (+2 Passive Agility)', '["Galetrap normally waits for contact with a target to begin its tornado, Galetrap now detonates once the trap stops moving."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gale-trap', 'Gale Trap', 'Aeromancer', 'Common', 'Knocking a player places a wind trap, causing anyone to pick up that body to get sent flying. Gain a speed boost picking up the body yourself. Killing PvE opponents gives you Gale Reflection instead.', '["Marks players knocked by you for 6s with \"Gale Trap\".","If the user picks up a target they''ve marked, they will gain a 35% speed boost for 20 seconds.","If anyone other than the user attempts to pick up the marked target, they will be ragdolled and flung upwards. This includes the user''s allies.","Gale Reflection procs upon getting hit by an enemy, granting damage reduction to the attack and placing a Gale Trap on them. The damage of the Gale Trap scales with the strength of the enemy you killed."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('suffocating-impact', 'Suffocating Impact', 'Aeromancer', 'Common', 'Flourishing enemies into walls applies Winded and Suffocating for a short duration. (+2 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stifled-jump', 'Stifled Jump', 'Aeromancer', 'Rare', 'Suffocating now applies Dazed if enemies jump. Suffocated PvE enemies now also get Sluggish when they are suffocated. (+2 Passive Agility)', '["The Daze effect lasts for 1 second.","The Sluggish status effect applies a -15% damage debuff to affected targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('vacuum-punch', 'Vacuum Punch', 'Aeromancer', 'Common', 'Your Gale Punch pulls enemies in before you hit them.', '["Gale punch mantra will now pull players towards the user during the windup of the mantra. (Cannot be feinted)","Increases the windup of Gale Punch by 0.1s, totalling to 0.65s."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('apothecary', 'Apothecary', 'Alchemist', 'Common', 'Potions you prepare will have amplified positive effects when consumed, and amplified negative effects when thrown.', '["Additively increases potion Potency by 125%. (More info on the potions page.)","The bonus acts similar to a potion ingredient, therefore Apothecary does nothing else after brewing.","Was merged with the old Exterminator Talent. (Strapped Hat however still has the Talent)","Skeptic Pioneer, Alchemist''s Hat, and the Big Alchemist''s Hat all have this talent, it is encouraged to simply utilize these when brewing instead of taking this as a Talent card."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chain-reaction', 'Chain Reaction', 'Alchemist', 'Common', 'When applying a potion effect to someone who already has one, the new effect is amplified. You have a 25% chance not to deplete potions when drinking them.', '["Procs when a thrown potion replaces a different potion''s effect. (Does not work on drank potions)","This effect increases the effectiveness of your potion by 40% and is applied multiplicatively to potency.","Was merged with the old Taste Test Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chemists-bag', 'Chemist''s Bag', 'Alchemist', 'Common', 'You no longer drop Potions on death.', '["Saltchemist salts innately provide this feature to your potions, however are not manually droppable."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('placebo-effect', 'Placebo Effect', 'Alchemist', 'Rare', 'Drinking potions near allies will share the potion''s effect with them.', '["Also procs potion sickness, causing allies to throw up upon usage if they''ve ingested a potion recently.","Its effective range is exactly 30 studs."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('potion-quaffer', 'Potion Quaffer', 'Alchemist', 'Rare', 'You''re accustomed to drinking toxic fluids quickly. You''ll get along famously with the other patrons at the tavern. Drinking potions slows less and grants superior regenerative effects to you.', '["Drink potions 30% faster. Potions take 1.645s to drink rather than the base 2.35s. When in combat, potions with Health Restoration (instant or regen) whether positive or negative now take 2.85s to drink rather than the base 3.55s.","The increased potion effectiveness is applied multiplicatively after Potency.","Increases the effectiveness of Health Regeneration potions by 15%. This only applies if the potion is drank.","Increases the effectiveness of Sanity Restoration and Ether Regeneration potions by 30%. This only applies if the potion is drank.","Removes the innate -25% effectiveness that Instant Health potions have, also increases their in-combat effectiveness from -75% to -50%. This only applies if the potion is drank.","This Talent was merged with the old Subsistence Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('wild-alchemy', 'Wild Alchemy', 'Alchemist', 'Common', 'You have a chance to brew 2 potions instead of 1.', '["25% chance to gives a duplicate of the brewed potion."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('endurance-runner', 'Endurance Runner', 'Alley Cat', 'Common', 'Even when things look dire, you still have it in you to keep your legs moving. (+2 Passive Agility)', '["Halve the speed penalty tied to lost health.","Currently does not work.","The Mercenary''s Boots equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scaredy-cat', 'Scaredy Cat', 'Alley Cat', 'Common', 'When enemies initiate a fight first, gain a speed boost. (+2 Passive Agility)', '["Gives you a 42.5% speed boost for 5s.","The enemy must not be in combat to trigger this effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('conditioned-runner', 'Conditioned Runner', 'Alley Cat', 'Advanced', 'You regenerate health faster than normal when sprinting below 75% HP. The health amount scales with your agility stat. (+1 Passive Agility)', '["After 3 seconds of sprinting without taking damage, gain increased health regeneration.","The health regen is reduced in PvP combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('approaching-singularity', 'Approaching Singularity', 'All-Knowing', 'Common', 'You now gain +1% Mantra PEN for every 10 point of Intelligence.', '["Gives 0.1% Mantra PEN per point in Intelligence.","Provides +8% PEN at the requirement, and +10% PEN at 100 Intelligence."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flame-within', 'Flame Within', 'Amoran Seeker', 'Common', 'An application of Pleeksty''s concept of the inner flame, also known as the soul of man. Set yourself ablaze to gain more move speed and 10% extra damage.', '["Unlike normal burn, Flame Within''s burn is not cleared by rolling/sliding. Flame Within will not stop until 30 seconds have passed or until Flame Within is reused.","Generally dangerous to use without multiple sources of burn damage reduction, most notably, Immolation.","8 second cooldown that starts when Flame Within is activated. Meaning if you let it burn for long enough, the cooldown will effectively be nullified outside of burn immunity. The Talent tool does not showcase this properly.","Flame Within grants a mobility buff, NOT a speed boost (it will not proc Talents such as Speed Demon).","Because Flame Within''s mobility buff is a flat 12.5% increase instead of a multiplier to your movement speed, it allows you to move when you otherwise wouldn''t be able to. Like during NPC dialogue, when mining, or when casting certain mantras like Arc Suit or Iron Skin.","It is a general damage buff, and as such it''ll affect all sources of damage that can be modified.","Flame Within can be enabled while knocked. This is meant to synergize with Phoenix Flames. Doing so will halve the strength of Phoenix Flames.","Deals self-damage on cast, separate from the burn damage. This self damage can be resisted with the Deepscorn Casque, elemental resistance (it deals Flamecharm damage), and many other sources of damage reduction.","Grotesque Resilience reduces the damage taken from Flame Within''s burn DoT by 25%.","Deepfire Ring will lower Flame Within''s duration down to 25s without affecting the burn damage taken. This is a direct downgrade for Flame within.","The old Last Laugh Talent was merged into Flame Within."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('proficient-baiting', 'Proficient Baiting', 'Angler', 'Quest', 'Casting your line excites ocean life, reducing the chances of fishing up trash.', '["Reduces the likelihood of fishing up trash items such as Seaweed or Leather Boots."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hook-line-and-sinker', 'Hook, Line, and Sinker', 'Angler', 'Quest', 'Once something''s caught your line, it''s much harder to get loose.', '["Slightly increases margin of failure before losing a fish."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fishers-lure', 'Fisher''s Lure', 'Angler', 'Quest', 'Fish are drawn to your line more quickly.', '["Slightly increases the chance of hooking something while fishing."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('collapsed-lung', 'Collapsed Lung', 'Annihilator', 'Advanced', 'Block breaking an opponent closes off their ability to Vent for 8s, with this duration scaling with Strength. PvE enemies instead get Collapsed.', '["Duration scales with investment up to its requirement, this effect lasts 8 seconds at 100 Strength and loses 0.04s for every investment point below 100 Strength.","Collapsed Lung will have a 7 second duration at 75 Strength.","Collapsed decreases the posture damage affected targets do to you by 40%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('carnivore', 'Carnivore', 'Apex Predator', 'Rare', 'In return for losing the ability to eat vegetation, satiate your hunger by gripping monsters and people alike.', '["Gain hunger and thirst upon executing an monster, NPC or player. (Scales off the strength of the target)","Does not work on certain mobs, such as \"Enmity Enforcers\", or \"Lightning Clones\".","Works on Ferryman''s lightning clones.","Mutual Exclusives: Vegetarian (Flaw)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grand-feast', 'Grand Feast', 'Apex Predator', 'Common', 'Regain tempo, ether, blood and health when gaining hunger from killing. (+1 Passive Agility)', '["Healing is negated in PVP combat.","40% tempo gain, 55% ether gain, 3% blood gain, 5% health gain.","Does not work on certain mobs, such as \"Enmity Enforcers\", or \"Lightning Clones\".","Works on Ferryman''s lightning clones."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sunken-predator', 'Sunken Predator', 'Apex Predator', 'Common', 'Enemies you hit in the water or the depths have their speed buffs nullified and are slowed. (+1 Passive Agility)', '["Monsters are greatly slowed for a few seconds and can be frozen in place with enough hits.","Players are only slowed a little bit for less time instead."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-dash', 'Arc Module: Dash', 'Arcwarder', 'Oath', 'In Arc Suit Your dashes become Jet Dashes, allowing you to attack while dashing.', '["Jet dashes go much further than regular dashes.","Also allows the user to M1 while performing a dash, ending their dash early."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-eject', 'Arc Module: Eject', 'Arcwarder', 'Oath', 'In Arc Suit When blockbroken, eject from your suit.', '["If your posture would reach 100% while in the Arc Suit, you instantly eject from it instead of being guard broken, launching yourself backwards and preventing stun.","Upon ejecting from the Arc Suit, your posture will be set to 50%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-enhance', 'Arc Module: Enhance', 'Arcwarder', 'Oath', 'In Arc Suit Your Arcwarder Mantras deal increased damage.', '["Increases Arc Wave''s base damage by 25%.","Increases Arc Beam''s base damage by 50%.","Because Enhance increases your Mantra''s base damage, it bypasses the damage modifier cap and increases the efficiency of your more conventional modifiers by giving them a higher base damage to work off of."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-guard', 'Arc Module: Guard', 'Arcwarder', 'Oath', 'In Arc Suit You can block attacks from any direction and cannot be backstabbed.', '["While in Arc Suit, you can block attacks that are coming from any direction.","Talents that proc on backstab (e.g. Spine Cutter) cannot proc on you while you''re in Arc Suit.","Does not prevent assassinations or nullify damage from attacks that hit your back."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-leap', 'Arc Module: Leap', 'Arcwarder', 'Oath', 'In Arc Suit Holding Spacebar after double jumping propels you up for a short duration.', '["Allows you to double jump while in Arc Suit.","This has a 10 second cooldown. This cooldown is increased to 15 seconds if used while in combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('arc-module-null', 'Arc Module: Null', 'Arcwarder', 'Oath', 'In Arc Suit Outgoing and incoming enchant effects are nullified. Can be toggled with input=N.', '["Toggling Null on/off has a 5 second cooldown.","Has a sound effect on toggle.","Toggle hotkey can be changed in settings."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-craftsman', 'Master Craftsman', 'Artisan', 'Common', 'Your skills alone substitute the need for a Craft Station. (+5 Health)', '["When crafting, the user no longer requires a Craft Station in their recipes. (Ex. Glider)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('deep-wound', 'Deep Wound', 'Assassin', 'Common', 'Assassinating a target applies anti-heal for 20s and gives you a speed boost for 6s. Assassination damage now scales with level against mobs.', '["The damage increase granted from this Talent is significantly high in PVE, allowing you to one shot some very tanky enemies like Authority Commander despite their 5000 HP.","Leaves red cloud particles similar to the Talent \"All the Dead Gods\" on targets hit.","This anti-heal won''t stack with any other anti-heal, the higher potency effect will take priority.","The Assassin''s Hood equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lights-out', 'Lights Out', 'Assassin', 'Common', 'Assassinations now give you 30% PEN and blind the target for 5s. Those you carry are now blindfolded. (+1 Passive Agility)', '["Targets being carried will have the \"Blinded\" Talent''s visual effect, however they can still see names of players, their general surroundings, and their map if they open it."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lowstride', 'Lowstride', 'Assassin', 'Common', 'When crouching, your stealth and roll distance are increased. The speed penalty you receive from crouching is much smaller. You now draw and sheathe your weapon silently. (+1 Passive Agility)', '["Doubles the Stealth gain bonuses from crouching.","Crouching normally increases your Stealth by 50% and adds a flat 50 Stealth afterwards, but having Lowstride makes crouching increase your Stealth by 100% and add a flat 100 Stealth instead.","Stealth × 1.5 + 50 -> Stealth × 2 + 100.","Removes the SFX from sheathing and unsheathing your weapon.","Speeds up crouching to be fast as walking.","Increases roll distance by 15% when crouching.","Very strong synergy with \"Murmur: Tacet\", as it requires the user to crouch.","The following Outfits and equipment items have this Talent: Authority Peacekeeper Armor, Diver Journeyman Robes, Hive Adjudicator, Hive Drone, Pathfinder Sorcerer, Pathfinder Thaumaturge, Shadow Hunter, Steel Plate, Assassin''s Cloak (all variants), and Hive Scourge Cuirass."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unseen-threat', 'Unseen Threat', 'Assassin', 'Common', 'You can assassinate those with weapons out provided you''re not in combat yourself. Those you assassinate are slowed and unable to jump for 3s.', '["Being in combat and having your weapon selected normally gives immunity to assassinations. This Talent bypasses this immunity.","Merged with the old Low Blow Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('authority-intimidation', 'Authority Intimidation', 'Authority Interrogator', 'Common', 'Lightning moves slow your opponent more.', '["Works with Surge Path."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('resolve-crusher', 'Resolve Crusher', 'Authority Interrogator', 'Common', 'Lightning moves now apply stacks of "Resolve Crusher". At 4 stacks, you apply "Electrified" to your opponent. Attacks from Electrified opponents are converted into lightning damage, but will deal 10% less damage to you.', '["Electrified targets have their damage on weapon attacks changed to Thundercall damage.","Electrified only reduces damage from weapon attacks.","Resolve Crusher''s \"Electrified\" effect is only applied after the 5th stack (not the 4th stated by the Talent)","Only Thundercall Mantras build up stacks for this. Thunder damage from any other source will not build up stacks.","Each stack lasts for 5 seconds. If another stack is not applied within that timeframe, the stack is reset, and you''ll need 5 more stacks to activate this Talent.","Electrified, when procced, lasts for 4 seconds.","The visual effect for this Talent is currently bugged."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('first-interrogation', 'First Interrogation', 'Authority Interrogator', 'Common', 'Attacks from opponents who are Electrified will give you ether proportional to their initial damage.', '["Only procs on weapon attacks from Electrified opponents.","Ether given is equal to half of the attack''s unmodified damage.","Still gives ether even if you block, parry, or dodge their attack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('second-interrogation', 'Second Interrogation', 'Authority Interrogator', 'Common', 'Electrified attacks do 50% less damage and posture damage to you.', '["Does not stack with Resolve Crusher''s damage reduction, instead it replaces it with this, more potent, effect.","This also only applies to weapon attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('horn-of-the-authority', 'Horn of the Authority', 'Authority Ensign', 'Origin', 'Mark escaping prisoners.', '["Grants a Talent tool that blows a horn, highlighting escaping prisoners and targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('authority-ensign', 'Authority Ensign', 'Authority Soldier', 'Origin', 'You are a member of the Authority deployed to the Eastern Luminant. You may find trouble with the local factions and must become stronger through advancing the Authority''s position.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('battle-tendency', 'Battle Tendency', 'Bastion', 'Common', 'You can breathe more easily with +20% faster posture regen. (+2 Posture, +10 Sanity)', '["In combat, by not running/blocking regenerate posture passively, Battle Tendency increases this regen by +20%.","The Etrean Siege Cuirass equipment has this talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('braced-collapse', 'Braced Collapse', 'Bastion', 'Common', 'After being block broken, the next attack to hit you deals reduced damage.', '["After being block broken, reduce the next instance of damage by 20%. This has no cooldown.","The Abyss Wanderer''s Plate, Delver''s Duster, and Providence Coat equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('moving-fortress', 'Moving Fortress', 'Bastion', 'Common', 'Blocking no longer slows you down as much. (+1 Posture)', '["Increases your movement speed while blocking by 6.6%, from -25% movement speed to -18.4%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('perseverance', 'Perseverance', 'Bastion', 'Common', 'Reduces the duration you''re Ragdolled and Unconscious for by 25%. (+5 Sanity)', '["This can stack with other Talents to reduce knock time even further. (Ex. Defiance)","The Ignition Trailblazer Outfit has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reinforced-armor', 'Reinforced Armor', 'Bastion', 'Advanced', 'Incoming PEN is reduced by 30%.', '["The effects of Reinforced Armor are lessened if you do not meet the Talent''s requirements, losing 0.8% PEN resistance per point below 90 Fortitude, capping at 10% PEN resistance at 65 Fortitude.","Alternatively, this can be stated as 10 + 0.8 * (Fortitude - 65) = RA effectiveness, though this cannot go below 10%.","PEN calculation: incoming PEN * (1 - 0.Reinforced Armor effectiveness) = reduced incoming PEN.","For example, 50% PEN vs 30% Reinforced Armor and 50% physical armor:","Base: 50% PEN vs 50% physical armor; 50 * (1 - 0.5) = 25% resistance after PEN.","Reinforced Armor: 50% PEN vs 30% RA; 50 * (1 - 0.3) = 35% PEN. 35% PEN vs 50% physical armor = 50 * (1 - 0.35) = 32.5% resistance after PEN."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('armored-plating', 'Armored Plating', 'Battle Readiness', 'Faction', 'Put on extra plating on your armor, giving you 50 temp health whenever you are put in combat. Due to the weight of this additional plating, you have reduced speed at all times.', '["Gain 50 Temporary Health whenever combat starts at the cost of having a passive movement speed debuff even outside of combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('crossguard', 'Crossguard', 'Battle Readiness', 'Faction', 'If you are using a sword, you gain 10% chip against other opponents wielding swords.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('riot-shield', 'Riot Shield', 'Battle Readiness', 'Faction', 'While you are fighting two or more opponents and are using a shield, reduce the total amount of chip damage you take by 40%.', '["Grants 40% damage reduction to chip damage, does not reduce your opponent''s chip % by 40."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('oppressive-force', 'Oppressive Force', 'Battle Readiness', 'Faction', 'When using a weapon found in the Merit Armory, gain a unique two-hit flourish that does not knock back opponents and dazes them.', '["The first hit deals your regular M1 damage and posture damage, the second hit deals 80% of your weapon''s scaled damage with 7 posture damage.","The damage and posture damage of the second hit cannot be buffed.","The second hit will only happen if the first one lands. This means it does not follow through on block.","The second hit does not count as a weapon hit, meaning it ignores your weapon''s Chip stat, it cannot proc enchants, and it cannot proc any \"on flourish\" Talents.","The second hit does not proc on non-humanoid targets.","These weapons are: Central Dirk, Halberd, Inquisitor''s Greatsword, Inquisitor''s Thorn, Markor''s Inheritor, Officer Saber, Rifle Spear, Sovereign''s Punishment, and Warden Ceremonial Sword.","The Alloyed variants of all of the above weapons proc this effect as well.","Despite being found in the armory, the Adretian Axe, Battleaxe, Cavalry Saber, Stiletto, Sword, and Worshipper Longsword do not proc this effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('steel-tread', 'Steel Tread', 'Battle Readiness', 'Faction', 'Gain a bit of knockback resistance as well as damage resistance against attacks that ragdoll you.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('all-seeing-eye', 'All-Seeing Eye', 'Blindseer', 'Oath', 'The mystic eye through which you now see the world can perceive the imperceptible. Invisible foes are highlighted.', '["Invisible players and monsters are revealed by a Blindseer Eye icon showcasing their current position.","Specifically reveals players under the effects of Ghost, Static Flash Clone, Cheap Trick, Illusory Servant''s casting animation, Beast Burrow, Portals, and other invisibility effects.","With this Talent, the Tacet is completely nullified, allowing you to see cloaked players normally.","This works on anyone who is invisible, yourself and monsters included."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('berserk', 'Berserk', 'Berserker', 'Common', 'One with nothing to lose has everything to gain. Succumb to burning rage within and enter Berserk State.', '["While in the Berserk State, your M1s will nullify your opponent''s armor, bypassing it entirely, and your criticals will gain 10% PEN. However, your own armor bars, including Natural Armor, will be drained fully for the duration of the Berserk State.","Lasts 20 seconds, halved to 10 seconds if you do not meet the Talent''s Strength requirement.","Berserk can be deactivated after 10 seconds by using the Talent tool again.","When activated:","Your eyes and hair turn red with your eyes gaining a red trail.","Your armor, including Natural Armor, is immediately removed. These bars will be restored back to their previous values when Berserk ends.","Padded Armor, Steel Scales, and Lightweight are activated. However, your Basic Attacks activate your opponent''s Padded Armor and Steel Scales.","You benefit from Exposed Durability''s 10% damage buff. However, your opponent will also benefit from Exposed Durability if they have the Talent.","The color of the eyes and hair is dyable."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('float-like-a-butterfly', 'Float Like a Butterfly', 'Bladeharper', 'Oath', 'While having True Strength active, cancel your air dash to enter a frenzy of slashes.', '["It has a cooldown of 5 seconds.","Only accessible when True Strength is active."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lithe-step', 'Lithe Step', 'Bladeharper', 'Oath', 'When Sprinting, roll-cancel and instantly vanish and surge with unmatched speed', '["Makes the player briefly invisible, similar to Jetstriker''s Rush of Ancients.","Lithe Step will not provide immunity frames to your dodge, but grants a noticeable speed boost during it.","Lithe Step has a 3 second cooldown. This cooldown is reduced to 1 second while in True Strength."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reveal', 'Reveal', 'Bladeharper', 'Oath', 'Pour your heart out, and reveal your true strength.', '["Grants a Talent tool. On cast, you stab yourself with your weapon, toggling on True Strength. Use the tool again to toggle True Strength back off.","While Reveal''s True Strength state, you passively build up Wither on yourself.","If you go below 10% HP, Reveal will automatically turn itself off.","Oddly enough, Reveal procs things that require you to take damage like Prediction despite Reveal not actually dealing damage. Your current HP does not need to get replaced with Wither for this to take affect, and other sources of Wither application/True Strength do not do this."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('soaring-storm', 'Soaring Storm', 'Bladeharper', 'Oath', 'Empower your uppercuts with the way of the blade, after Lithe Stepping, flourishing, or landing an Oath ability.', '["Proc condition is removed and damage is increased if in True Strength.","Applies to all forms of uppercuts, including Mantras such as Rising Flame, Round Spark Skyshatter Kick, or certain weapon criticals such as the Wraithclaw."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('untouchable', 'Untouchable', 'Bladeharper', 'Oath', 'By landing consecutive hits on your opponent without taking any damage, reveal your True Strength for a short duration.', '["Upon proccing Untouchable, enter the True Strength state for 15 seconds.","Untouchable requires 10 ''Untouchable Stacks''. Being hit by any non-self damage source will reset all Untouchable Stacks.","Landing weapon attacks will build up 2 stacks each.","Landing non weapon attacks (like Burn, Mantras, Eruptions, etc.) build up 1 stack each. Bleed does not build up stacks however."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('anchor-shock', 'Anchor Shock', 'Blightsurger', 'Oath', 'Your Blightshock prevents targets from using mobility mantras.', '["This puts your opponent''s mobility slot Mantras on a 3 second cooldown whenever Blightshock is applied from a Blightsurger Mantra.","This does not proc on the Blightshock from the Sovereign Bangle weapon."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blight-pierce', 'Blight Pierce', 'Blightsurger', 'Oath', 'Your Blightshock attacks pierce through your enemies hyperarmor and gain more penetration.', '["Blightshock now works similar to regular Shock, canceling hyperarmor.","Sovereign Bangle, the Blightsurger exclusive weapon, and Blightsurge Mantras gain +?% more PEN.","This Talent is bugged and currently does not work."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blighted-touch', 'Blighted Touch', 'Blightsurger', 'Oath', 'Landing Basic Attacks during Sovereign State now applies Blightshock.', '["This allows your Sovereign Bangle to apply Wither on hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blightlash', 'Blightlash', 'Blightsurger', 'Oath', 'Your swing range is enhanced during Sovereign State.', '["Increases the range of the Sovereign Bangle from 6 to 7."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sovereign-state', 'Sovereign State', 'Blightsurger', 'Oath', 'Landing physical hits builds your Blight Meter. At full gauge, enter a Blight State that changes your critical and empowers Blightsurge abilities.', '["Blight Meter gain has no cooldown. Landing Blightsurger Mantras grants 15% Blight Meter. Landing Basic Attacks grants 10% Blight Meter. Landing weapon criticals, Thundercall Mantras, or Galebreathe Mantras grants 5% Blight Meter per hit.","At full Blight Meter, Sovereign State lasts 12.5 seconds.","Sovereign State has a 10 second activation cooldown once the duration runs out.","You can press input=X while having at least 30% Blight Meter to activate Sovereign State. While in Sovereign State, your Blight Meter will passively decay, and it cannot be deactivated.","This keybind can be changed in settings.","While in Sovereign State, your weapon will be replaced with the Sovereign Bangle.","Skycrash will be automatically used twice in quick succession while in this state.","Increases the Wither damage that Sovereign Drive and Warp Kick deal."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bloodwardens-sense', 'Bloodwarden''s Sense', 'Bloodhound', 'Common', 'Enemies you attack with a mantra above 60% Blood Poisoning are highlighted red briefly. Enemies who are highlighted red take 20% more blood poisoning.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('smell-of-blood', 'Smell of Blood', 'Bloodhound', 'Rare', 'When people touch a blood pool, briefly see their blood (or blood hemorrhage amount for PvE) and blood poison. This effect also occurs whenever you blockbreak your opponent.', '["Your opponent''s blood percentage is shown as a red number. This is replaced with the blood hemorrhage percentage in PvE.","Your opponent''s blood poisoning percentage is shown as a pink number."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bloodrend-unbounded', 'Bloodrend Unbounded', 'Bloodrend Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Bloodrend to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bloodrender', 'Bloodrender', 'Bloodrender', 'Mantra Level', 'Grants you the ability to command Blood as a Bloodrender. Your Bloodrend mantras replenish your blood, steal blood and apply ''Blood Poisoning''.', '["Obtained at 1 Bloodrend"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-bloodrender', 'Adept Bloodrender', 'Bloodrender', 'Mantra Level', 'You can now obtain 1-star Bloodrender mantras.', '["Obtained at 20 Bloodrend"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-bloodrender', 'Expert Bloodrender', 'Bloodrender', 'Mantra Level', 'You can now obtain 2-star Bloodrender mantras.', '["Obtained at 30 Bloodrend"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-bloodrender', 'Master Bloodrender', 'Bloodrender', 'Mantra Level', 'You can now obtain 3-star Bloodrender mantras. Your maximum blood capacity is 25% more than a normal individual. You regen blood at a quicker pace. (+5 Health)', '["Obtained at 50 Bloodrend."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('crimson-fountain', 'Crimson Fountain', 'Bloodrender', 'Common', 'Blockbreaking or flourishing an enemy now spills a pool of blood below them.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('first-blood', 'First Blood', 'Bloodrender', 'Common', 'Your first blood mantra you use in combat has no blood cost.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hemorrhaging-blow', 'Hemorrhaging Blow', 'Bloodrender', 'Rare', 'Block breaking your opponent with a blood mantra turns your opponent''s combat healing into damage for 8 seconds', '["55 second cooldown, with the cooldown starting on guard break.","The damage to healing conversion is 1:1, meaning 20 healing = 20 damage.","It works on all (non passive) healing, meaning you can block break them and then use something that would heal them them for additional damage. This however wouldn''t work on things like Health Regen Potions or Conditioned Runner as that they are forms of passive healing.","This works on healing outside of combat.","Works with Mindsoothe, Blood Scourge bell, Grand Support, Fadetrimmer''s healing spray and etc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rush-hour', 'Rush Hour', 'Bloodrender', 'Rare', 'Stab yourself to become stronger, faster, and deal increased blood bar damage.', '["Gives you the Rush Hour tool. Can be deactivated at any time by using the tool again.","Drains 4.5 HP per second and 2% Blood per second.","Deepscorn Casque and the Enhanced Flow Talent are the only two effects in the game that can reduce the self damage taken by Rush Hour.","Grants a 15% damage buff, affected by the damage modifier cap.","Increases blood bar damage by +35% (additive).","Grants a 30% active speed boost. This counts for Talents such as Speed Demon and Cheap Shot.","Recover 5% Blood when dealing damage (0.35s cooldown). Burn damage cannot proc this effect.","If you have the Enhanced Flow Talent, landing basic attacks during Rush Hour will grant Temporary Health, equal to 30% of your weapon''s scaled damage.","Having Rush Hour active doubles the duration of the Torture Mastery status effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sanguine-siphon', 'Sanguine Siphon', 'Bloodrender', 'Common', 'Landing a critical attack while in a blood pool will consume that pool and empower your next blood mantra.', '["Buffs the next mantra’s damage by 25% upon proccing, signified by flowing blood out of your hands.","Effect lasts 15s before disappearing."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sheltering-grasp', 'Sheltering Grasp', 'Bloodrender', 'Common', 'Blood mantras cast within blood pools have a reduced blood cost.', '["Halves the blood cost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blood-and-iron', 'Blood and Iron', 'Bloodsong', 'Common', 'Pulling rods out of your opponent now replenishes an equivalent amount of blood.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brain-death', 'Brain Death', 'Bloodsong', 'Common', 'Enemies that are already suffocated will have their suffocation duration extended when hit by a bloodrend mantra.', '["Applies a new stack of suffocation for 2.5s on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cold-blooded', 'Cold Blooded', 'Bloodsong', 'Common', 'Chilled enemies passively build up blood poison, alternatively when crystals explode it''ll apply blood poison. (DOES NOT STACK)', '["Has a 0.5s cooldown.","Applies 12.5% blood poisoning over the duration of the chill.","Applies 25% blood poisoning on crystal explosion.","This Talent does not proc on Crystal explosions caused via guardbreaking the target or Temperature Shock. Instead, all crystal explosions must be procced through applying enough crystals or Golden Age in order for this Talent to proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('electrolyte', 'Electrolyte', 'Bloodsong', 'Common', 'Hitting Bloodrend mantras while having temporary health applies Shocked while removing a portion of temporary health.', '["Applies a Surge Rod instead if you have Surge Path: Unstable Capacitor.","Takes 4 temporary health per proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('malevolent-sapper', 'Malevolent Sapper', 'Bloodsong', 'Common', 'The more blood poisoning your opponent has, the more ether your shadow mantras steal from your opponent.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scorchblood', 'Scorchblood', 'Bloodsong', 'Common', 'Guardbreaking your opponent using a bloodrend mantra causes a blood explosion, setting your opponent on fire and poisoning their blood.', '["Deals 16.5 damage in an AoE on proc.","Applies burn before Scorched Peak does a check to see if your opponent is burning, meaning Scorched Peak will be instantly procced if you guardbreak with a Bloodrend Mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bruisers-mixup', 'Bruiser''s Mixup', 'Brawler', 'Common', 'Switching your Fist Style mid-fight makes your basic Fist attacks inflict bleed temporarily.', '["Lasts for 4 seconds.","Procs by pressing input=Y (Works even if you only have one Fist Style)","8 Second cooldown between style change.","This Talent does not work with Jus Karita."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('impairing-blow', 'Impairing Blow', 'Bruiser', 'Common', 'Greataxes Basic Attacks will slightly slow your enemy for 2 seconds. Running attacks will slow your enemy for 3 seconds. Gain +20% posture damage against enemies with speed boosts.', '["Does not proc on uppercut.","Reduces the opponents speed by a flat value of 5."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brazen-blow', 'Brazen Blow', 'Bruiser', 'Common', 'Greataxes Attacking an enemy slowed by your Greataxe grants you temporary hyperarmor.', '["The hyperarmor lasts 1 second. 20 second cooldown.","Only procs on weapon attacks.","Does not proc on uppercut."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heavy-fatigue', 'Heavy Fatigue', 'Bruiser', 'Rare', 'Greataxes Hitting an enemy slowed by your Greataxe temporarily reduces how far they can roll and applies Sluggish to PvE enemies for a few seconds.', '["Reduces opponents roll distance by 25% for 2.5s.","The Sluggish status effect applies a -15% damage debuff to affected targets.","Does not proc on uppercut."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rending-impact', 'Rending Impact', 'Bruiser', 'Rare', 'Greataxes Block breaking an enemy applies knockdown.', '["Only procs on guardbreaks from weapon attacks.","Applies knockdown for 1.2 seconds.","The default guardbreak stun is 1.05s, so this effectively increases the time someone is stunned after being guardbroken by 0.15s.","30 second proc cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('defensive-reprisal', 'Defensive Reprisal', 'Bulwark', 'Common', 'Being flourished grants you 10% posture resistance for 20s.', '["Defensive Reprisal''s duration will be reduced by 0.177s for every point in Fortitude below its requirements, having a minimum duration of 15.55s duration with 40 Fortitude."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dancing-guard', 'Dancing Guard', 'Bulwark', 'Common', 'Parrying an opponent and then parrying another enemy in quick succession applies slow for 7s.', '["Dancing Guard''s duration will be reduced by 0.086s for every point in Fortitude below its requirements, having a minimum duration of 4.86s at 30 Fortitude."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('down-to-your-level', 'Down to your Level', 'Bulwark', 'Common', 'While you have a speed debuff, your Basic Attacks slow your enemies for 5s.', '["Down to your Level''s duration will be reduced by 0.05s for every point in Fortitude below 60, capping at a minimum of 3.75s with 35 Fortitude.","The slow only procs on M1s and criticals with the M1 tag.","Procs from Entaglement, Daze, Chill and most other things that slow you down.","Does not proc from Grand Fisher Plate or Wormwarder Lantern despite them reducing your movement speed."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('knuckle-guard', 'Knuckle Guard', 'Bulwark', 'Common', 'Hitting Dazed enemies grants you 10% posture resistance for 15s.', '["Knuckle Guard''s duration will be reduced by 0.1s for every point of Fortitude and Strength below its requirements, having a minimum possible duration of 10.4 seconds with 30 Fortitude and 4 Strength, though this isn''t very realistic."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('swift-rebound', 'Swift Rebound', 'Butterfly', 'Common', 'Move faster after successfully dodging an attack. (+1 Passive Agility)', '["Provides a 30% speed boost for 2s."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('evasive-expert', 'Evasive Expert', 'Butterfly', 'Rare', 'Your speed boost granted from dodging is increased. (+1 Passive Agility)', '["Increases your Swift Rebound speed boost from 30% to 50%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('risky-moves', 'Risky Moves', 'Butterfly', 'Rare', 'When you successfully dodge, you''ll automatically dodge the next attack. (+1 Passive Agility)', '["User is covered in a blue highlight when the effect is active.","Visual effect might not line up with duration.","Attacking will cancel the effect early.","Takes priority over block, allowing for you to \"auto-dodge\" while simultaneously blocking.","20 second cooldown.","Mutual Exclusives: Observation, Safety Dance"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ghost', 'Ghost', 'Butterfly', 'Advanced', 'Dodging a move will briefly make you invisible, ending early if you attack. (+5 Passive Agility)', '["Provides I-frames for the duration of the invisibility.","The invisibility and I-frame duration is 1.2 seconds if you have 40 or higher Agility.","Ghost''s duration will be reduced by 0.0133 seconds per point in Agility under 40, capping at 0.866 seconds at 15 Agility.","Will also proc from dodging bleed, occurs when dodging a m1 late in high ping.","Has a 20 second cooldown.","You cannot parry attacks during the invisibility."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('perpetual-wrath', 'Perpetual Wrath', 'Chainwarden', 'Oath', 'Unleash the true power of Restrain. Each successive hit will increase its damage. stacking up to the base damage.', '["Enchaining targets and hitting Chained targets with with Restrain will add 1 stack of Perpetual Wrath.","Each stack of Perpetual Wrath increases Restrain''s (Mantra) damage by 8, capping out at 4 stacks for +32 damage. At max stacks, Restrain additionally gains a new visual and sound effect.","All stacks of Perpetual Wrath will be cleared if the chain is broken."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chainlash', 'Chainlash', 'Chainwarden', 'Oath', 'On flourish, gain the ability to summon a chain on an enemy for 5 seconds by right clicking. This lets you whip your chain to seize and yank enemies towards you, setting them up for a crushing kick.', '["Right clicking after landing a flourish will apply Enchained to your opponent, pulling them to you. M1ing after the pull will perform a Crushing Kick, dealing high damage.","The pull will bring the targets back to the location you flourished and prevent movement for a duration.","Chainlash will only work on Chained targets, if a target breaks the chain quick enough, Chainlash will cancel.","Works with Dazing Finisher and Bulldozer.","The kick ragdolls and flings targets in the direction you are looking, but cannot wallbang.","This does not proc on non-humanoid targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('champions-regalia', 'Champion''s Regalia', 'Champion', 'Rare', 'Flourishing an opponent grants you +50% posture damage on Basic Attacks for 10 seconds.', '["Indicated by a gold shaded outline on your character.","Does not work on non-humanoid NPCs.","Works only if you successfully hit someone with flourish. Doesn''t work on parry, block, dodge hits."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('defiance', 'Defiance', 'Champion', 'Rare', 'Negative status effects are half as effective when you are below 35% HP.', '["The Effectiveness of Defiance will be lessened if you do not meet its Willpower requirement.","Currently, the only things Defiance cuts in half are:","Flamecharm''s Burn damage","Frostdraw''s Chill duration","Galebreathe''s Winded duration","Galebreathe''s Suffocation duration","Frostdraw''s Crystal stacks","Thundercall''s Surge stacks","Shadowcast''s Sightless Still duration","Blood Poisoning","Wither gain","Ring of Pestilence duration","The potency of potions","Time Unconscious (cut by 50% multiplicatively after other modifiers)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('underdog', 'Underdog', 'Champion', 'Common', 'You deal 2.5% more damage to those with higher HP than you, scaling up to 4% at 60 WLL. Additionally, you deal +10% more damage to physically larger foes.', '["Underdog''s damage to enemies with higher HP than you scales with your Willpower investment.","Underdog grants a 2.5% damage buff at 20 Willpower, this is increased by 0.0375% damage per Willpower above 20, capping at 4% with 60 Willpower.","Underdog will grant a 2.875% damage bonus at requirements.","\"Higher HP\" refers to current HP.","\"Larger foes\" refers to NPCs who are actually large-sized. (e.g., works on Megalodaunts, does not work on Threshers)","Large enemies cannot be grabbed by grab mantras","This was merged with the old Giantslayer Talent.","The Dark Owl Chapeau equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('charismatic-cast', 'Charismatic Cast', 'Charm Caster', 'Common', 'Landing a hit with a mantra on an enemy applies Charmed. Allies recover from being knocked twice as quickly when Charmed by you.', '["This charm lasts 10s (5s against Disbelief Talent).","Targets you''ve Charmed will deal 10% less damage to you.","When applying Charm to an already Charmed target, if the new Charm''s total duration is longer than the current Charm''s remaining duration, the original Charm will be replaced. If not, nothing will happen. It is highly recommended that you have Lasting Charisma if you wish to get use out of Charismatic Cast during ganks and other team fights."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chaotic-charm', 'Chaotic Charm', 'Charm Caster', 'Common', 'Charm enemies nearby when attacked at low health. Enemies affected by this charm have their damage increased to anyone but you, and deal reduced damage towards you.', '["Applies a unique status effect for 15 seconds that is separate to charm as a whole. This status effect is what grants the additional damage reduction and increased damage to people who are not you. This status effect cannot have its duration reduced by Disbelief.","The additional damage reduction from Chaotic Charm scales on your Charisma investment, gaining 0.15% damage reduction per point in Charisma.","This damage reduction is combined multiplicatively with Charm due to them being separate status effects.","Automatically procs narcissist","Deals 0.1 typeless damage whenever it procs.","Can be blocked, preventing damage and Charm proc.","Damage and Charm is applied in a very small AoE around you on top of affecting the person who hit you directly.","Will apply combat tag against opponents.","Has 0.25s cooldown.","Typeless self damage will not proc Chaotic Charm, but something like Flame Within will."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lasting-charisma', 'Lasting Charisma', 'Charm Caster', 'Common', 'Enemies charmed by your mantras are charmed longer.', '["Lasting Charisma increases the duration of Charismatic Cast''s Charm from 10s to 20s (from 5s to 10s against Disbelief Talent).","If you do not meet Lasting Charisma''s investment requirement, the additional Charm duration will be reduced, losing 0.166s for every point of Charisma you have under 55, capping at a minimum of 15.83 seconds of Charm with 30 Charisma."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tough-love', 'Tough Love', 'Charm Caster', 'Common', 'Deal 10% more damage to enemies Charmed by you. Mantras deal +5% instead. Being hit by someone the same Aspect or Oath as you applies Charmed briefly.', '["Charms for 2 seconds with a 1 second cooldown.","If attacked while on cooldown, the cooldown timer resets and you have to wait another second again to be able to proc Tough Love''s Charm.","The damage increase affects all forms of Charm, not exclusively Tough Love''s.","Procs its charm through block, parry, and dodge.","This damage buff is only applied if your Charm is applied to the target. Due to how Charm works, it is highly recommended that you have a high Charm duration from Lasting Charisma if you wish for this Talent to function in large-scale ganks.","Instead of your charm debuffing affected players and making them take more damage, it actually applies an on-hit buff when attacking someone affected by your charm, granting a damage buff to that attack. This means Tough Love is affected by the damage modifier cap.","Mutual Exclusives: Narcissist"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dazing-finisher', 'Dazing Finisher', 'Charm Caster', 'Advanced', 'Flourishing enemies that are charmed by you cause them to not be knocked back and dazed instead.', '["Daze duration from Dazing Finisher scales on your Charisma investment, capping at ?s with 55 Charisma.","Prevents you from knocking back charmed players with flourishes, instead, dazing them.","Mutual Exclusives: Bulldozer"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('christmas-miracle', 'Christmas Miracle', 'Christmas Miracle', 'Common', 'Christmas Mod Shop reward. Regens hunger and thirst. "Thank you so much K1!" Heh, no problem guys. All in a day''s work.', '["Grants access to the Christmas Miracle tool"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('freezing-wight', 'Freezing Wight', 'Cold Phantom', 'Common', 'Your Haunted Gale now procs Chilled.', '["Also works with Specter Path''s Apparitions.","Applies 7 seconds of chill or 1 Crystal.","Adds 5 Frostdraw scaling to your Haunted Gale Ghost/Specter Apparitions, significantly increasing their damage.","The formula for Apparition/Ghost damage with this Talent is: 7 × (1 + ((5/10 + 5/10) × (Galebreathe invest/100 + Frostdraw invest/100)))","Changes the damage type of Haunted Gale Ghosts/Specter Apparitions from pure Galebreathe to Galebreathe & Frostdraw, making them easier to resist and allowing them to proc things that require the Frostdraw damage type (e.g. Flashboil)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('destructive-recovery', 'Destructive Recovery', 'Colossus', 'Rare', 'Greatsword Enemies recover 20% less Posture when parrying. (+1 Posture)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heavy-hitter', 'Heavy Hitter', 'Colossus', 'Common', 'Heavy Weapons Your posture damage is increased by 10%.', '["Despite its description, your posture damage is increased by only 5%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unstoppable-force', 'Unstoppable Force', 'Colossus', 'Rare', 'Greathammer You take 15% less posture damage when parried. (+1 Posture)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lords-tithe', 'Lord''s Tithe', 'Comrade', 'Rare', 'Everyone you Reinforce is drained of their Ether while Reinforced. Drain scales with your Shadowcast. Drain health from PvE opponents as well.', '["While the effect is active, victims can hold block to stop ether drain.","Lord''s Tithe cancels on victims once they drop beneath 5% Ether.","Getting hit will cancel the effect entirely.","Getting your block hit counts as being hit.","(Note that Reinforce requires 50 fortitude despite the requirement for the Talent being 40)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grand-support', 'Grand Support', 'Comrade', 'Rare', 'Everyone you buff with Reinforce is healed lightly. You''re healed slightly if you heal others.', '["Heals others by 3% of their maximum health.","Heals the user by 3% of their maximum health + an additional 1% for every person healed.","Only procs on allies.","(Note that Reinforce requires 50 fortitude despite the requirement for the Talent being 40)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hidden-tendril', 'Hidden Tendril', 'Contractor', 'Oath', 'Landing any physical mantra places a Hidden Tendril on the opponent. (+10 Ether)', '["Physical critical attacks, uppercuts, flourishes, and most attunement-less Mantras will apply a Hidden Tendril."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('string-trick', 'String Trick', 'Contractor', 'Oath', 'Pulls together any two opponents you''ve attached Hidden Tendril to.', '["Does not proc on non-humanoids. Deals a small amount of damage on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pressure-detonation', 'Pressure Detonation', 'Cosmic Wind', 'Common', 'Block breaking an opponent with a Shadow mantra generates a small vacuum that suffocates those hit and steals their Tempo.', '["If the user has the Apparitions Talent, this can proc apparitions by inflicting suffocation."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('finishing-touch', 'Finishing Touch', 'Critical Specialist', 'Common', 'Daggers Instantly execute enemies finished with the critical attack of your dagger.', '["Your critical must knock the opponent for this Talent to proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('knifes-journey', 'Knife''s Journey', 'Critical Specialist', 'Rare', 'Daggers Cancelling an enemy''s Mantra windup with your Basic Attacks now deals 15% more damage', '["Displays a red particle on the target enemy after proccing.","Though not mentioned in the Talent description, Daggers gain a 15% chance to critically hit on basic attacks in PVE, dealing 5x damage.","This does not work on non-Dagger weapons via Switchblade. Additionally, Moppet''s critical attack cannot critically hit.","Critical hits do not proc \"on critical attack\" Talents."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('decisive-blow', 'Decisive Blow', 'Critical Specialist', 'Common', 'Hitting an enemy with your Critical Attack immediately after they dodge (or any time against mobs) now procs Knife''s Journey. Your Knife''s Journey procs do 2x Armor damage.', '["While the effect is active, gain a red trail on your weapon. The red trail will show up on non-daggers, but will have no effect.","Compatible with Switchblade despite technically not being a Dagger talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('successive-throw', 'Successive Throw', 'Critical Specialist', 'Common', 'Daggers When you successfully flourish an enemy, you throw out a dagger afterwards', '["If your cursor isn''t on an enemy after flourishing them, it will throw it at the enemy closest to your cursor. If your cursor is on a separate player from who you flourished, the dagger will be thrown at them instead.","Will take 1.5 seconds to throw the dagger after flourishing someone.","If the target is too close to you, the thrown dagger projectile will be invisible; otherwise, the thrown dagger projectile will look similar to Ice Daggers'' projectile.","The range for the projectile to go and how far away it can proc is unknown.","Deals 5 damage on proc. (doesn''t scale with weapon or traits)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chilling-flourish', 'Chilling Flourish', 'Cryomancer', 'Common', 'When flourishing an enemy, they leave behind a trail of ice in the direction you send them.', '["Leaves 3-4 ice patches on the ground."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('spike-traps', 'Spike Traps', 'Cryomancer', 'Common', 'Press input=F during the wind up of your Ice Spikes to create traps around you instead of spawning a spike in the normal spot.', '["Activated by holding your block key during the windup of Ice Spikes.","Activates a spike upon being stepped on.","There are small, blue, transparent \"traps\" indicating the hitboxes, placed randomly around the user.","Can stack multiple times, allowing for very high amounts of traps in one spot.","Extends Ice Spike''s cooldown by 5s, to 20s total.","text=Spike Traps is no longer obtainable. For users who already have Spike Traps, activating it will only place 1 trap, no matter how many Cloud/Stratus Stones the Mantra was modified with."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('condensation-drip', 'Condensation Drip', 'Cryomancer', 'Common', 'Passively collect condensation from the air, greatly reducing your thirst.', '["Slows thirst drain by approximately 3 times."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cool-head', 'Cool Head', 'Cryomancer', 'Common', 'If set on fire while on ice, immediately put it out and gain the Cool Head status for 30s. During Cool Head, you cannot be lit on fire. 15s cooldown', '["While the effect is active, the user breathes cold air."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fragile-freeze', 'Fragile Freeze', 'Cryomancer', 'Common', 'Your Light Attacks and Critical will now freeze chilled opponents on guardbreak.', '["Guardbreaking a chilled opponent with a weapon attack will encase them in ice, removing their ability to move, parry, block, or dodge for a short amount of time.","Taking damage by any source (including damage over time effects) will end the freeze early.","You can spam F to get out of Freeze faster."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('preceding-chill', 'Preceding Chill', 'Cryomancer', 'Rare', 'Enemies hit during the last moments of your ice beam are frozen.', '["If the user has Crystallization, this Talent no longer freezes but instead causes crystals to explode."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('golden-age', 'Golden Age', 'Crystalline Gold', 'Common', 'Your Iron Pull now detonates Crystals and overloads Surges.', '["Crystals don''t always detonate on pull."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blood-thirsty', 'Blood Thirsty', 'Cutthroat', 'Common', 'Gain a speed boost after causing an opponent heavy blood loss. (+1 Passive Agility)', '["\"Heavy Bloodloss\" refers to around 1 bar of blood.","\"Very short duration\" (As described by Agamatsu)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('in-a-hurry', 'In a Hurry', 'Cutthroat', 'Common', 'You grip faster with a movement speed boost.', '["Reduce grip time by 0.5 seconds (16.67% faster)","Speed boost from parkouring do not count. It must be an actual speed boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('muffled-screams', 'Muffled Screams', 'Cutthroat', 'Common', 'You quieten the cries of help of those you execute, reducing the distance at which their allies will hear it and come to assist, and reducing the effectiveness of Talents that slow your executions. (+1 Passive Agility)', '["NPCs have a shortened aggro range from gripping allies in proximity.","Defiant Until The End and Last Second Negotiations affect your grip speed less."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blighted-song', 'Blighted Song', 'Darksiphon', 'Common', 'Attaching your Shadow Chains to enemies disables yours and the enemy''s ability to cast mantras. You take reduced damage from enemies while this is applied.', '["Grants 20% damage reduction against attacks coming from entities that are not the caster or the person affected by Blighted Song."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-god', 'Dark God', 'Darksiphon', 'Common', 'If a Shadowcast mantra would drain your opponent''s Ether to 0, drain from their Tempo instead and increase your Tempo.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-replenishment', 'Dark Replenishment', 'Darksiphon', 'Common', 'Knocking out an enemy in combat restores a portion of your ether.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-synergy', 'Dark Synergy', 'Darksiphon', 'Common', 'Engulf your enemy in shadows when flourishing them.', '["Deals 5 Shadowcast damage on proc.","Does not proc any shadow Talents except Shadow Overflow.","Does not steal or halt any Ether regen."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-waltz', 'Dark Waltz', 'Darksiphon', 'Common', 'Anytime you guardbreak your opponent with a light attack or critical, steal half of your opponent''s current tempo. Also apply Ether Sunder to PvE enemies.', '["The Ether Sunder status effect grants you 30% damage reduction against affected enemies'' elemental attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-hours', 'Dark Hours', 'Darksiphon', 'Common', 'Your Shadowcast Mantras deal 15% more damage at night and in realms the Sun does not reach.', '["Night cycle is XX:50 to XX:10.","Always active in the depths."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-rift', 'Dark Rift', 'Darksiphon', 'Rare', 'Enter a rifted state when you successfully dodge, where you can''t be damaged until its duration ends. Can be cancelled with feinting or attacking.', '["Blocking, parrying, dodging, or sliding will also cancel the effect.","You cannot use mantras during the effect.","You hover with a dark outline while dark rift is active.","This ability last for 1.8 seconds and goes on a 20 second cooldown when it activates."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('night-terror', 'Night Terror', 'Darksiphon', 'Common', 'Your light attacks now proc Fear the Dark.', '["Despite its description, this talent applies the Fear status for 1 second with no cooldown (they are not required to run away from you).","Night Terror''s Fear the Dark proc completely bypasses Dawnwalker''s Absolute Radiance.","Also procs on weapon criticals."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('overwhelming-drain', 'Overwhelming Drain', 'Darksiphon', 'Common', 'If multiple enemies are hit by your Shadow Eruption, they are dazed.', '["This talent is currently bugged and does not work."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shadow-overflow', 'Shadow Overflow', 'Darksiphon', 'Common', 'Extra ether stolen with mantras are exerted as dark energy, damaging and absorbing ether from those nearby.', '["Has a 4 second cooldown.","Deals 5 Shadowcast damage around you in a small aoe from the target you hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('absolute-radiance', 'Absolute Radiance', 'Dawnwalker', 'Oath', 'Dealing damage with Dawnwalker mantras briefly makes you immune to all elemental effects for a short period.', '["All elemental status effects cannot be applied to you during Absolute Radiance."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('protagonist-syndrome', 'Protagonist Syndrome', 'Dawnwalker', 'Oath', 'The grasp of shadow is meaningless in the face of your blinding light. Your Dawnwalker mantras are empowered after getting hit by Shadowcast.', '["Increases your Dawnwalker Mantra damage by 30% after being hit by Shadowcast damage.","Shade Devour''s self damage is typeless, so it will not proc this effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('luminous-flash', 'Luminous Flash', 'Dawnwalker', 'Oath', 'After dealing a certain amount of damage in Absolute Radiance, gain a chance to empower your strikes with pure light.', '["During Absolute Radiance, your M1 attacks have a chance to proc Luminous Flash, increasing their damage by 75% (the damage modifier hardcap). In PvP combat, this is lowered to 50% instead (the damage modifier hardcap)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blackhole', 'Blackhole', 'Death Speaker', 'Common', 'Your singularity pulls everyone nearby in.', '["Pulls anyone nearby in a medium sized aoe to the closest opponent you hit with a shadow mantra. (AoE range can be seen here: https://medal.tv/pl/games/roblox/clips/kaEeJDfoPtIlVOVBF)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('energy-siphon', 'Energy Siphon', 'Death Speaker', 'Common', 'Your singularity now pulls ether from extra players affected by Blackhole.', '["Takes around 15 Ether from the affected opponent on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('call-of-the-deep', 'Call of the Deep', 'Deepbound Contract', 'Origin', 'Sink beneath the waves and return to the Depths.', '["Grants a Talent tool.","When used in the Overworld, play an animation and sink into the First Layer. This does not count as a drown.","When used in the First Layer, teleport to Castle Light with a 20 minute cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('deepbound-contract', 'Deepbound Contract', 'Deepbound Contract', 'Origin', 'You progress much faster in the Depths, and slower on the overworld. You can regain sanity at Castle Light, but will always face the strongest foes in your Trial.', '["You can always enter Castle Light, even if you''ve drowned, or are a Contractor, However the turret infront of Castle Light WILL attack you.","Your Depths Trial will always be an Enforcer or harder.","You gain passive sanity regeneration at Castle Light.","Gain increased experience gain while in either layer of the Depths, but your experience gain is reduced elsewhere."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('spell-shout', 'Spell Shout', 'Deepwoken', 'Quest', 'You will now shout your mantra name upon cast.', '["The player will say the name of the mantra they cast in a chat bubble. E.G casting Fire Blade will make the player say \"Fire Blade!\"","Renamed mantras will use the new name. Casting Adrenaline Surge renamed to Speed Boost will say \"Speed Boost!\".","Mantra names are auto formatted so that caps are forced at the start of every word and cannot be elsewhere. Numbers also cannot be used. Casting a mantra named \"64 palms\" will say \"Palms!\".","If a mantra name gets moderated by the chat (####), the shout will default to the original name of the mantra.","You can toggle spell shout visibility by typing ''/e shout'' into chat. This setting is per-slot. If you have spell shout visibility disabled, you won''t see anyone''s spell shouts","IMPORTANT: Make sure to not use offensive names or slurs for your mantras. This can result in moderation action taken against you.","Offensive includes mentions to Race, Gender, Sexual Preference and Religion."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frozen-web', 'Frozen Web', 'Doomsday Engine', 'Common', 'Landing a critical with a Static Link on your opponent applies Chilled.', '["Applies Chill for 7 seconds and Bottom Freeze.","Applies fragile freeze if the critical guardbreaks.","When using Crystallization Path, it''ll spawn the VFX and play the sound effects for creating crystals, but won''t actually inflict any.","3 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('buster-call', 'Buster Call', 'Dread Imperium', 'Faction', 'Radio in the Authority''s navy for a buster call, sending out a barrage of bombardment wherever you see fit.', '["1 day cooldown (24 IRL hours).","Grants a Talent tool that lights a flare and highlights a large AoE on the ground. After a considerable delay, that location will be bombed several times, dealing very high damage.","Applies burn on hit.","Cannot knock players."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('officers-slash', 'Officer''s Slash', 'Dread Imperium', 'Faction', 'You now gain an additional critical attack with Authority armory weaponry while your regular critical attack is on cooldown.', '["20 second cooldown.","This critical has the M1 tag.","Deals 35 flat damage with no scaling, though this can be buffed with damage modifiers.","This works with the following weapons: Adretian Axe, Central Dirk, Halberd, Inquisitor''s Greatsword, Inquisitor''s Thorn, Markor''s Inheritor, Officer Saber, Rifle Spear, Sovereign''s Punishment, and Warden Ceremonial Sword.","The Alloyed variants of all of the above weapons proc this effect as well."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('officers-training', 'Officer''s Training', 'Dread Imperium', 'Faction', 'While using a Sword or Rapier, take 30% less posture damage from criticals.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('target-focus', 'Target Focus', 'Dread Imperium', 'Faction', 'Enemies you charm take more damage from your squadmates in your party.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ethirons-gaze', 'Ethiron''s Gaze', 'Drowned Secret', 'Quest', 'Your eyes have been opened to the wasteland. You can see through the harsh fog of the storm of the Eternal Gale more clearly now.', '["Obtainment: While within the Second Layer, complete the quest given to you by Erosius Amaltus Urivortus Alistus Casius Walistoshus."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('concussion', 'Concussion', 'Duelist', 'Rare', 'Enemies you flourish into walls have their vision altered for a short duration and are dazed longer than usual. Flourished PvE enemies get Stagger for a few seconds.', '["The Stagger status effect makes your opponent take 33% more posture damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('concussive-force', 'Concussive Force', 'Duelist', 'Common', 'Enemies you knocked remain downed longer than usual.', '["Enemies remain knocked for 15 seconds instead of 10.","The Blackleaf Helm and Gladiator Helm equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('precise-swing', 'Precise Swing', 'Duelist', 'Common', 'After landing a critical your next basic attack will gain 25% chip past your opponent''s block. (+1 Passive Agility)', '["If your critical lands, is parried, or is blocked, gain the Precise Swing status effect for 30 seconds.","The Precise Swing status effect will be consumed if you hit someone''s block with an M1, you land an M1, or your M1 gets parried.","If your M1 is whiffed or dodged, the status effect will not be consumed.","Because this status effect is applied to yourself and not your opponent, you can land your critical on person A and then hit person B''s block and still apply the chip damage.","Precise Swing is additive with weapon chip, and having above 100% chip causes you to deal more damage.","The Phalanx Helmet equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('spine-cutter', 'Spine Cutter', 'Duelist', 'Rare', 'Hitting an enemy in the back after a roll cancel will initiate a second slash that deals your weapon''s raw damage. (+2 Passive Agility)', '["5 second cooldown per enemy. The cooldown indicator may suggest the cooldown is per enemy type, but it isn''t.","The second slash has no PEN.","Can proc from some physical Mantras and criticals with the M1 tag."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('steady-nerves', 'Steady Nerves', 'Duelist', 'Common', 'You dance from toe to toe - successful dodges restore posture. (+2 Passive Agility)', '["Restore 2 flat posture on a successful dodge."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('strong-hold', 'Strong Hold', 'Duelist', 'Common', 'Medium Weapons When above 33% health and two-handing, posture damage taken is reduced by 5%. (+1 Passive Agility)', '["The Authority Helm and Bulwark Helm equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('strong-stern', 'Strong Stern', 'Duelist', 'Rare', 'The duration you are Dazed from wall bangs is cut in half. Slightly reduce your guardbreak stun time from PvE enemies as well. (+5 Carry Load)', '["The Ignition Trailblazer Outfit has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tap-dancer', 'Tap Dancer', 'Duelist', 'Rare', 'Dodging immediately after a roll-cancel no longer puts your Dodge on a longer cooldown. (+1 Passive Agility)', '["Negate the extra half a second cooldown added to the roll following a roll-cancel."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('concussive-flash', 'Concussive Flash', 'Duelist Flame', 'Common', 'Your blinding light now concusses foes.', '["People blinded by Flame Blind are Dazed for 2 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('charged-return', 'Charged Return', 'Elemental Rebound', 'Common', 'Being under an elemental status effect causes your Basic Attacks and Criticals to do 10% more damage.', '["Procs on Burn, Chill, Shock, Fear (from the Fear the Dark Talent), Winded, and Suffocation.","Also procs if the aforementioned status effects are self-applied, like using Flame Within or Agitating Spark to self apply burn."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('nullifying-clarity', 'Nullifying Clarity', 'Elemental Rebound', 'Common', 'Deal 10% more damage to enemies with elemental status effects, but remove the status on hit.', '["Procs if you land an M1 on a target who is affected by any of the following status effects: Burn, Chill, Shock, Winded, Suffocation, and Fear (from Fear the Dark and Night Terror).","Does not work with Critical Attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cornered-fool', 'Cornered Fool', 'Empath', 'Common', 'Blockbreaking a Charmed opponent procs Taunt for 5s, making them take and deal more damage.', '["15 second cooldown.","Despite what the description states, this applies Taunt for 6 seconds.","Every point of Charisma below 85 will reduce the duration of this Taunt by 0.035 seconds, capping at a minimum of 5.12 seconds with 60 Charisma.","The Taunt damage buff is also applied to the attack that guard broke.","This Talent will still function as normal if you no longer have the Taunt Mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('give-and-take', 'Give and Take', 'Empath', 'Common', 'Deal less damage to comrades and receive less damage from comrades.', '["Take 20% less damage from allies and deal 20% less damage to allies. This does not apply to self damage.","The Canor Aspect''s innate Talent has a similar effect and they can stack, totaling to 48% damage reduction.","Guildmates, your Roblox friends, people who are in a Vow of Mastery, or people who are in a Vow of Allegiance with you take less damage from you and deal less damage to you.","The Investigator''s Hat and Tophat equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('off-your-game', 'Off Your Game', 'Empath', 'Common', 'You now slow Taunted enemies when you hit them.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('robber-baron', 'Robber Baron', 'Escape Artist', 'Common', 'You hold onto more items when defeated.', '["Item loss on death is reduced from 50% to 25%.","You no longer lose notes from dying.","The Pathfinder''s Backpack and Grand Pathfinder''s Backpack equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ether-absorption', 'Ether Absorption', 'Ether Conduit', 'Common', 'Receive Ether back when inflicted with damage from Mantras.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('eureka', 'Eureka', 'Ether Conduit', 'Rare', 'Gain a stack of Inspiration every time you land or parry a Mantra. Whiffing a Mantra removes a stack of Inspiration.', '["At 3 stacks, gain the Inspired buff for 30 seconds or until you cast a Mantra. Inspired increases the damage of your next Mantra cast by 10%.","If you gain Inspired by parrying Mantras, you gain the Inspired status effect for 30 seconds.","If you gain Inspired by landing Mantras, the Inspired status will be instantly consumed to increase the damage of the Mantra used to gain the status.","You do not gain additional stacks from multi-hits or autoparry frames.","Inspiration Stacks do not decay, even if you whiff Mantras entirely.","This Talent was merged with the old Ether Conduit Talent.","The Ministry Operative Cloak equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mantra-permanence', 'Mantra Permanence', 'Ether Conduit', 'Common', 'Knocking an enemy with a mantra refunds the cost of the mantra.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('keen-recovery', 'Keen Recovery', 'Ether Endeavors', 'Common', 'Landing a basic attack after feinting a mantra will restore the feinted mantra''s ether cost.', '["If you have 55 or more Intelligence, this will recover double the feinted Mantra''s Ether cost instead.","Does not proc if your basic attack is blocked, parried, or dodged."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('behind-you', 'Behind You', 'Ether Endeavors', 'Common', 'Landing a basic attack behind your enemy after feinting a mantra will apply an ether slash, dealing extra damage based on how much ether you have left.', '["This deals a separate instance of physical damage, scaling on your weapon''s damage and your current Ether%.","Unlike Spine Cutter, this has no cooldown.","You can proc Behind you and Spine Cutter at the same time, but the proc window is very tight."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unwavering-focus', 'Unwavering Focus', 'Ether Endeavors', 'Common', 'When your mantras are parried, receive less posture (scales with intelligence).', '["Grants 0.3% posture resistance per point in Intelligence, capping at +21% at 70 Intelligence."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reverse-leech', 'Reverse Leech', 'Evil Endeavors', 'Common', 'Anytime you proc Behind You, steal ether from your opponent too.', '["Behind You is procced by landing a basic attack behind your enemy after feinting a Mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('barbers-skillset', 'Barber''s Skillset', 'Fadetrimmer', 'Oath', 'What type of look are we going for today?', '["Gives a Talent tool that opens an outdated version of the Barber UI. Because this uses the outdated variant of this UI, it only has 4 hair slots.","When selecting others: Changes what haircut your Fadetrimmer Mantras apply on hit.","When selecting yourself: Changes your own hair.","Do not use hair IDs that can be seen as offensive. This is bannable. You are the one responsible for what hairs you give."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hair-products', 'Hair Products', 'Fadetrimmer', 'Oath', 'What''s in these things?', '["Gives a Talent tool that shows a popup menu and allows you to select either Flammable, Charming, or Revitalizing Hair Sprays. Your Hair Spray will change to the chosen effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hair-spray', 'Hair Spray', 'Fadetrimmer', 'Oath', 'Apply your Hair Products.', '["Gives the Hair Spray Talent tool that applies the spray that was selected in the Hair Products'' popup menu.","Flammable:","Ignites your opponent or causes an Eruption on hit. 10s CD.","Does not directly deal damage, deals no posture damage and restores no posture if parried.","Parryable and blockable, but it applies the burn on the first tick, meaning if you don''t frame perfect parry it, your parry won''t do anything.","Charming:","Charms your opponent for 15 seconds on hit (halved to 7.5s against Disbelief). 10s CD.","Does not deal damage, deals no posture damage and restores no posture if parried.","Parryable and blockable, but it applies the Charm on the first tick, meaning if you don''t frame perfect parry it, your parry won''t do anything.","Can be used as a substitute for the Lasting Charisma Talent in low/no Charisma builds.","Revitalizing:","Heals a flat 10% health to any targets hit. 10s CD.","Can heal non-allies or even mobs.","Unparryable and unblockable.","Can become a damaging tool with the Bloodrend Talent, Hemorrhaging Blow."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('meteor-impact', 'Meteor Impact', 'Falling Star Guard', 'Common', 'Aerial moves you land will follow up into a devastating slam. This is also possible when you yourself gets hit by an aerial move.', '["Deals 10 flat Flamecharm damage on top of your weapon''s scaled damage.","Meteor Impact''s damage can be buffed via damage modifiers, but does not scale on your Flamecharm investment.","Meteor impact is used by light attacking after using some mantras that end with both user and victim suspended in air, including: Rising Flame, Flame Leap, Rising Frost, Rising Wind, Lightning Impact, Flashfire Sweep and Saintsworn''s Galebreathe Blade of Saints. There may be more that do, but simply aren''t documented yet.","Rising Thunder can also activate it, but only if the initial grab guard breaks, which is very unlikely. Additionally, Wind Blade can activate it as well, but only if you use the Tempest Wind Talent''s variant of the mantra.","Some mantras, despite leaving both players in the air, can''t activate Meteor Impact, such as Celestial Assault, or Skyshatter Kick (Round Spark).","Rising Flame, Rising Frost, Rising Thunder, Rising Wind, or Rising Shadow"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('phoenix-impact', 'Phoenix Impact', 'Falling Star Guard', 'Common', 'If you Meteor Slam an opponent whilst on fire, restore some HP and Ether.', '["Heals 4% max HP and restores 20 ether."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fishman', 'Fishman', 'Fish', 'Rare', 'When your Blood is over 50%, you won''t drown when Unconscious in water. Gain additional healing from kncking others Unconscious in water. (+5 Health)', '["The old Scuba Drowner Talent was merged into this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('landshark', 'Landshark', 'Fish', 'Quest', 'Killing a megalodaunt will grant lifesteal on your attacks for 30 seconds.', '["The lifesteal does not work in PvP."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fang-and-coil', 'Fang and Coil', 'Fang and Coil', 'Common', 'Adopt the path of the serpent.', '["Allows you to use the Fang and Coil fist style."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dancing-steps', 'Dancing Steps', 'Flame Dancer', 'Common', 'Fire mantras now move you in the direction you''re facing.', '["Casting a Flamecharm Mantra will give you a moderate boost of horizontal movement in the direction your character is facing. This will still proc even if the Mantra is feinted.","Very useful for closing distance and getting into close quarters combat.","Despite what Graceful Step''s Talent description implies, this Talent does not grant a speed boost.","This has a 5 second cooldown. This cooldown can be reduced to 1 second by wearing the Cindergarb Outfit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('graceful-steps', 'Graceful Steps', 'Flame Dancer', 'Rare', 'Your dancing steps now gives a faster speed boost.', '["If you lack the ether to cast a Mantra, the speed boost will trigger regardless. Also triggers if the Mantra is feinted.","The speed boost has a very short duration; having a fast swingspeed weapon is recommended to capitalize off this Talent''s effect.","This has a 5 second cooldown. This cooldown can be reduced to 1 second by wearing the Cindergarb Outfit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('the-final-act', 'The Final Act', 'Flame Dancer', 'Rare', 'Landing a fire mantra immediately after flourishing an opponent will cause them to explode.', '["Does not have a cooldown.","Deals 5 Flamecharm damage.","Will not proc on knocked NPCs/players and mobs.","Can proc with Mecha Gatling.","Mutual Exclusive: Eruption Path: Lava Serpent"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cauterized-wounds', 'Cauterized Wounds', 'Flame Warden', 'Common', 'Blood loss from all sources is lowered. (+1 Passive Agility)', '["Despite what the description states, this Talent only affects blood loss from directly taking damage. Blood drain effects (e.g. casting or being hit by Bloodrend Mantras, blood loss Potions, the blood loss Corrupt Resonance downside) are entirely unaffected by this Talent.","Effectiveness of this Talent is reduced if you are using the Curse of the No Life King enchantment.","Stacks with Alloyblood.","The Bloodforged Crown equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('warding-radiance', 'Warding Radiance', 'Flame Warden', 'Rare', 'Every fire mantra builds up one halo stack. At 3 stacks a halo appears that allows you to slide further. Hell''s Partisan is also triggered passively while this is active. (+1 Passive Agility)', '["Allows you to proc Hell''s Partisan on Flamecharm Mantras that aren''t Fire Forge while you have the halo active.","This can be easily procced by landing a multi-hit fire mantra.","Doesn''t have a cooldown, lasts for 60s, cannot be refreshed."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flamewalker', 'Flamewalker', 'Flame Warden', 'Common', 'When Warding Radiance is active you leave trails of flame when you slide. (+1 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hells-partisan', 'Hell''s Partisan', 'Flame Warden', 'Common', 'After landing a flame dagger on an opponent, your next hit against them will impale with a divine spear from above. (+4 Sanity)', '["Deals 5 Flamecharm damage.","Has a 5 second cooldown.","This is parryable, but is not blockable nor dodgeable due to hitstun."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flamecharm-unbounded', 'Flamecharm Unbounded', 'Flamecharm Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Flamecharm to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flamecharmer', 'Flamecharmer', 'Flamecharmer', 'Mantra Level', 'Grants you the ability to command Fire as a Flamecharmer.', '["Obtained at 1 Flamecharm"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-flamecharmer', 'Adept Flamecharmer', 'Flamecharmer', 'Mantra Level', 'You can now obtain 1-Star Leveled Flamecharmer Mantras.', '["Obtained at 20 Flamecharm"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-flamecharmer', 'Expert Flamecharmer', 'Flamecharmer', 'Mantra Level', 'You can now obtain 2-Star Leveled Flamecharmer Mantras.', '["Obtained at 30 Flamecharm"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-flamecharmer', 'Master Flamecharmer', 'Flamecharmer', 'Mantra Level', 'You can now obtain 3-Star Leveled Flamecharmer Mantras. (+5 Health)', '["Obtained at 50 Flamecharm"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('azure-flames', 'Azure Flames', 'Flamecharmer', 'Common', 'Many of your flames turn blue, signifying their increased intensity.', '["Increases burn damage by 12.5%.","Increases the radius and posture damage of your Eruptions.","Increases the uptime of your Flame of Denial by 25%, from 25 seconds to 31.25."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unyielding-inferno', 'Unyielding Inferno', 'Flamecharmer', 'Common', 'Your flames burn just as strong even in the fiercest of storms.', '["Negates the innate 10% damage debuff Flamecharm Mantras, First Light''s critical, and Twisted Puppets'' Puppets receive during the rain.","Prevents your burn from going out in rain."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('temperature-shock', 'Temperature Shock', 'Flashfreeze', 'Common', 'Your fire mantras now detonate any stacked crystals.', '["This has a 4 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('exoskeleton', 'Exoskeleton', 'Freak Of Nature', 'Rare', 'You have a layer of fortified Natural Armor that replenishes when you rest. Your Natural Armor will resist 10% Physical Damage when active. (+5 Health)', '["Exoskeleton''s resistance will be less effective if you do not meet its Fortitude requirement, losing 0.125% resistance for every point under 40 Fortitude, capping at 6.875% resistance with 15 Fortitude.","Exoskeleton has 315 durability at power 1, scaling up to 600 durability at power 20.","Vesperian''s Chitin damage reduction stacks multiplicatively with Exoskeleton.","Having both Exoskeleton and Chitin will cause Exoskeleton''s durability to take priority, with +200 flat durability added on top, leading to 800 total durability at power 20.","Natural Armor regenerates while resting at a campfire at a rate of 2.2% per 0.2s, aka 11% per second.","Natural Armors are affected by PEN, but its effectiveness is reduced by 75%. (i.e. if someone has 100% PEN, your Natural Armor will resist 7.5% of their damage instead of nothing.)","Natural Armor will lose durability if you get hit by any attack, even if it doesn''t resist it.","Natural Armor loss is based on scaled damage received and cannot normally be increased nor decreased by anything, with the exception being damage reductions, like Reinforce, which will reduce the Natural Armor loss."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('to-the-finish', 'To the Finish', 'Freak Of Nature', 'Rare', 'You take 10% less damage when below 30% health. (+5 Health)', '["For every point of Fortitude below 50, To the Finish loses 0.166% damage reduction, having a minimum value of 5.833% damage reduction at 25 Fortitude."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('glacial-mobility', 'Glacial Mobility', 'Frost Forger', 'Common', 'Cast while slide-jumping to perform a running attack with your ice sabers.', '["The Talent activates after you''ve slide jumped, and not during the slide jump, contrary to the Talent description."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frostdraw-unbounded', 'Frostdraw Unbounded', 'Frostdraw Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Frostdraw to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frostdrawer', 'Frostdrawer', 'Frostdrawer', 'Mantra Level', 'Grants you the ability to command Ice as a Frostdrawer.', '["Obtained at 1 Frostdraw"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-frostdrawer', 'Adept Frostdrawer', 'Frostdrawer', 'Mantra Level', 'You can now obtain 1-Star Leveled Frostdrawer Mantras.', '["Obtained at 20 Frostdraw"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-frostdrawer', 'Expert Frostdrawer', 'Frostdrawer', 'Mantra Level', 'You can now obtain 2-Star Leveled Frostdraw Mantras.', '["Obtained at 30 Frostdraw"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-frostdrawer', 'Master Frostdrawer', 'Frostdrawer', 'Mantra Level', 'You can now obtain 3-Star Leveled Frostdraw Mantras. (+5 Health)', '["Obtained at 50 Frostdraw"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cold-front', 'Cold Front', 'Frostdrawer', 'Common', 'Your vent is imbued with glacial frost.', '["Venting creates an ice patch on the floor and applies Chill to any enemy hit by it.","Increases your Vent damage by 40% and changes its damage type to Frostdraw.","This also applies to the Imperator''s Fury''s Talent despite its damage being otherwise unmodifiable."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fulgurite-formation', 'Fulgurite Formation', 'Frozen Lightning', 'Common', 'When your Crystals explode, lightning strikes. When your Surge charges Overload on an enemy, your Crystals apply twice on them for 8s.', '["The lightning strikes deal 5 typeless damage with no PvE scaling & don''t apply Surge stacks.","The lightning strikes have a cooldown of 4 seconds.","The double Crystal application buff does not stack with successive Fulgurite Formation procs.","The lightning strikes proc Grounding Bolt."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('orbital-ice', 'Orbital Ice', 'Frostthorn', 'Common', 'When landing a parry while standing on ice, automatically forms a gravitational ring of ice that absorbs 15% of the physical damage you take. The ring breaks after sustaining a certain amount of damage. (Scales with Frostdraw)', '["Durability of Orbital Ice is equal to \"Frostdraw investment +10\".","Cooldown of 90 seconds. The cooldown starts the moment you proc orbital ice, not when its broken.","Lasts 50 seconds if it is not broken","If you have the Refreeze Talent from Icebringer''s Vestments, landing any ability that procs bottom freeze will reduce Orbital Ice''s cooldown by 8 seconds. This procs regardless of Bottom Freeze''s cooldown.","Mutual Exclusive: Fists of Fortitude","If you have the Icebringer''s Vestments Outfit, you can bypass mutual exclusives and stack this with Fists of Fortitude."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('glacial-coasting', 'Glacial Coasting', 'Frostthorn', 'Common', 'Sliding while Orbital Ice is active leaves trails of ice. (+1 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frozen-legs', 'Frozen Legs', 'Frozen Warrior', 'Rare', 'Your slow effect prevents your opponents from rolling.', '["Does not work with Crystallization.","Lasts the first 0.75 seconds after chill/freeze procs.","Only procs off mantras."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('imperium-kata', 'Imperium Kata', 'Gale Kata', 'Quest', 'Wield an advanced form of the Legion''s martial arts. (+1 Passive Agility)', '["Allows you to use Imperium Kata, a fist style."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('legion-kata', 'Legion Kata', 'Gale Kata', 'Quest', 'Gain the ability to use the Legion''s martial arts.', '["Allows you to use Legion Kata, a fist style."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('galebreathe-unbounded', 'Galebreathe Unbounded', 'Galebreathe Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Galebreathe to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('galebreather', 'Galebreather', 'Galebreather', 'Mantra Level', 'Grants you the ability to command wind as a Galebreather.', '["Obtained at 1 Galebreathe"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-galebreather', 'Adept Galebreather', 'Galebreather', 'Mantra Level', 'You can now obtain 1-Star Leveled Galebreathe mantras.', '["Obtained at 20 Galebreathe"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-galebreather', 'Expert Galebreather', 'Galebreather', 'Mantra Level', 'You can now obtain 2-Star Leveled Galebreathe mantras.', '["Obtained at 30 Galebreathe"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-galebreather', 'Master Galebreather', 'Galebreather', 'Mantra Level', 'You can now obtain 3-Star Leveled Galebreathe mantras. (+5 Health)', '["Obtained at 50 Galebreathe"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('after-cut', 'After Cut', 'Galeforce', 'Common', 'If an attack is physical and wind it will apply an after cut that does 10% of the damage you dealt. If an attack was a mantra, it does 5% damage instead.', '["The only Galebreathe mantras that benefit from the 5% damage increase are: Wind Blade, Air Force, Tornado Kick, Tornado, Galetrap, and Wind Gun.","After Cut is not a damage modifier, it''s a second hit of Galebreathe damage with no hitstun. This means it is unaffected by the damage modifier cap.","After Cut deals damage based on your final damage dealt, after resistances and multipliers.","For example, if you deal 100 M1 damage, you''ll deal 10 After Cut damage, but if your opponent has 50% physical damage reduction, meaning your M1 now deals 50 damage, this''ll also lower your After Cut damage to 5 (10% of 50). On the other hand, if you deal 100 M1 damage and have +50% damage from damage modifiers, After Cut will deal damage based on your modified damage, dealing 15 damage (10% of 150).","After Cut deals Galebreathe damage, and thus it can be resisted by Galebreathe resistance and Everchanging Aegis."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('breathing-impact', 'Breathing Impact', 'Galeforce', 'Common', 'When knocked into objects by wind mantras enemies take additional blunt damage based off of how hard they are hit.', '["The following Galebreathe Mantras have knockback and can benefit from this Talent: Air Force, Champion''s Whirlthrow, Tornado Kick, Gale Punch, Rising Wind, and Wind Gun.","The increased damage dealt is based on the attack''s initial damage and your opponent''s acceleration.","Due to the increased damage being based on acceleration, it is heavily affected by server performance and ping."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('inhale', 'Inhale', 'Galeforce', 'Common', 'Feinting a Wind spell stores its power in your lungs for 5 seconds, empowering the next wind spell cast in that time. All relevant modifications and upgrades from the inhaled wind mantras are applied to the empowered mantra.', '["Inhaling a Galebreathe Mantra adds (Mantra level multiplied by 2)% damage to the next Galebreathe Mantra. For example, a level 5 inhale will give your next Gale mantra a 10% damage buff.","Inhaling grants a speed boost for 3 seconds.","Inhaling grants the Maestro''s Blade status effect. This effect allows your basic attacks to proc After Cut.","The duration of Maestro''s Blade is the inhaled Mantra''s Ether cost (before Blue Gem) divided by 5. For example, a 50 Ether cost Mantra will apply Maestro''s Blade for 10 seconds.","Can be procced through shadow mantras while using the Eyes of Ethiron weapon."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('neuroplasticity', 'Neuroplasticity', 'Genius Intellect', 'Rare', 'Your mind is a pliable, flexible substance. The Ether cost of additional modifications to your Mantras is now reduced by 10%. (+1 Wildcard Mantra Slot)', '["The increased Ether Cost from Modified Mantras is reduced by 10% (ether cost increase for tier 1 modifications is reduced from 10 Ether to 9, for tier 2 - from 20 Ether to 18).","Does not apply retroactively to previously modified mantras until you rejoin."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('glass-path-crystallization', 'Glass Path: Crystallization', 'Glassdancer', 'Common', 'Your ice abilities no longer grant a slow effect or the ability to freeze and instead cause ice crystals to grow on your opponent.', '["Applying chill or freeze applies red ice crystals on the enemy instead of slowing opponent. Stacking 5 ice crystals or guard breaking an opponent who has crystals makes them explode.","3 base Frostdraw damage per crystal explosion with 5 Frostdraw scaling. Formula to calculate crystal DMG is ((3+frostdraw investment*0.015)*crystal amount)","Has 4.45x PVE scale (18.75 DMG PVP, 83.53 DMG PVE), affected by Chain of Perfection.","1s cooldown on explosion proc.","Allows you to obtain Crystal Impale, Crystal Knee, and Ice Lasers.","Increases the damage of Crystal Impale and Crystal Knee (they will do reduced damage if you remove this Talent).","Chilling now applies 1 crystal on hit.","Changes color of your Frostdraw Mantras, Gran Sudaruska, Kyrswynter, and Chilling Enchant to become a pinkish red color.","Mutual Exclusives: Unyielding Frost, Flashboil"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('crystal-shrapnel', 'Crystal Shrapnel', 'Glassdancer', 'Common', 'Your crystal explosions now have an AoE that applies crystals to all hit.', '["Does not hit allies or the target procced on.","Has a range of 10 studs from the target procced on.","Scales off Frostdraw investment and amount of crystals present."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reclaimed-glass', 'Reclaimed Glass', 'Glassdancer', 'Common', 'Your Crystal Shrapnel explosions now grant you and any allies caught in them 10% Elemental Resistance for 10 seconds.', '["Targets with Reclaimed Glass will have a pink triangle VFX that stacks.","Despite the VFX stacking the elemental resistance will not stack.","Relanding this will refresh the duration."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fortitude-unbounded', 'Fortitude Unbounded', 'Great Wall', 'Mastery', 'You have gained the ability to surpass your limits and train your fortitude to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bodkin-arrow', 'Bodkin Arrow', 'Greatarcher', 'Rare', 'Your charged shots now do extra armor damage to armored enemies and extra damage to unarmored enemies.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hard-stop', 'Hard Stop', 'Greatarcher', 'Rare', 'Landing a charged shot will knock your opponent back.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('precision-crusher', 'Precision Crusher', 'Greatarcher', 'Rare', 'Landing a charged shot will knock your opponent down instead of back.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('armor-piercing', 'Armor Piercing', 'Gunslinger', 'Rare', 'Guns Your gun attacks now ignore 10% of an opponent''s blunt armor. Applied Multiplicatively before PEN is applied.', '["Mathematically speaking, Armor Piercing is effectively a multiplicative 10% increase to your PEN against blunt armor, applied after all other PEN sources, meaning Armor Piercing has heavy diminishing returns based on how much PEN you have.","While at 0% PEN, this effectively grants +10% PEN against blunt armor, but this amount gets reduced by 1% for every 10% PEN you have. The formula is as follows: (1 - ((1 - Current PEN/100) * (1 - 0.1))) * 100 = effective PEN against blunt armor.","For example: having 20% PEN + Armor Piercing is equivalent to having 28% PEN against blunt armor (+8).","Specific rifles benefit less from Armor Piercing than others due to their damage typings.","For Rifle Spear, this will only proc on critical, due to Rifle Spear being a slash based weapon.","For Stormseye and Rosen''s Hellflame, they will only circumstantially benefit from Armor Piercing, because of their elemental damage.","In some circumstances, Armor Piercing may give your opponent higher weighting on their elemental resistances by lowering their blunt resistance, causing them to resist your damage based on their elemental resistance instead. Alternatively, if they have higher elemental resistance than blunt resistance, Armor Piercing will do nothing at all.","The Summer Company Uniform Outfit has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bulletproof', 'Bulletproof', 'Gunslinger', 'Common', 'You take no Armor damage from guns. You take 5% less Armor damage from other sources.', '["This has no effect on your natural armor.","This Talent simply removes/reduces armor damage taken, it has no effect on PEN."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('execution', 'Execution', 'Gunslinger', 'Rare', 'Your offhand gun attacks now count as flourishes and do a flat 20 extra damage when used with no bullets.', '["Works with dual guns, adding 5 flat damage to every second shot.","Does not work with Hardened Enforcer Boots.","Mutual Exclusive: Hip Shooter"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gunpowder-blast', 'Gunpowder Blast', 'Gunslinger', 'Common', 'Pistol shots without bullets deal 2 extra posture. [Dual Gun]', '["Increases the posture damage of your blast shots by 2 if you do not have physical bullets in your inventory."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hip-shooter', 'Hip Shooter', 'Gunslinger', 'Rare', 'When wielded with a Medium/Heavy weapon, your side gun can now fire a bullet projectile.', '["This requires you to have bullets in your inventory.","Currently does not work.","5 second cooldown.","Mutual Exclusive: Execution"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('parting-gift', 'Parting Gift', 'Gunslinger', 'Common', 'After you land a flourish, gain the ability to shoot bullets for 5 seconds. [Dual Gun]', '["On proc, all dual gun M1s within the next 5 seconds have projectiles.","Procs even if your flourish is parried or blocked.","The projectile M1s from this Talent can proc True Ether Bullets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('quickdraw', 'Quickdraw', 'Gunslinger', 'Common', 'Allows you to fire your offhand gun right after swinging. [Not necessary on dual guns]', '["Allows the user to instantly start attacking with their offhand gun after attacking with their main weapon"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('quick-swap', 'Quick Swap', 'Gunslinger', 'Common', 'Massively reduce your bullet swap cooldown. [Dual Gun]', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('taste-the-rainbow', 'Taste The Rainbow', 'Gunslinger', 'Common', 'Every time you shoot, switch your ammo type. [Dual Guns]', '["Every M1 switches your Bullet type."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('true-ether-bullets', 'True Ether Bullets', 'Gunslinger', 'Rare', 'Using Ether Bullets applies elemental damage of your highest investment.', '["Landing 2 shots will make the 3rd shot deal elemental damage.","The 3rd shot apply your attunement''s elemental effect:","Flamecharm: Your bullets apply burn/eruption (Lava Serpent)","Frostdraw: Your bullets apply chill/crystal (Crystallization)","Thundercall: Your bullets apply shock/surge stack (Surge)","Galebreathe: Your bullets after cut and apply winded briefly","Shadowcast: Your bullets drain ether/apply burn (Twisted Puppets)","Ironsing: Your bullets apply metal rods","Bloodrend: Your bullets apply blood poisoning","If the user has multiple attunements at the same level, it will use the first attunement in the priority list: Thundercall > Shadowcast > Flamecharm > Galebreathe > Frostdraw","If the user has no attunement, this Talent has NO EFFECT. It is recommended to put one point into an attunement if using this Talent on an attunement-less build.","This Talent does not make guns scale off your attunement attributes, it just converts your Physical Damage to Elemental Damage.","Despite the fact that you can obtain this from Greatcannons, this Talent does nothing on them."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('prime-ether-bullets', 'Prime Ether Bullets', 'Gunslinger', 'Advanced', 'Your bullets take one less hit to proc elemental effects and now have slight intelligence scaling. [Dual Gun]', '["True Ether Bullets now procs in 2 hits instead of 3.","Adds 1.2 Intelligence scaling to your Pistols. Stacks with the Rosen''s Ring."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brain-rattler', 'Brain Rattler', 'Hammer Rage', 'Common', 'Clubs Guardbreaking an opponent with your Critical rattles their brain in its container, causing increased blood loss, applies Stagger to PvE enemies and blurs their vision.', '["This Talent is bugged and procs on ALL guard breaks, including those from Mantras, non-critical attacks, or entirely different weapons.","The Stagger status effect makes your opponent take 33% more posture damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dispatch', 'Dispatch', 'Hammer Rage', 'Common', 'Clubs Bear Trapped targets deal 20% less posture. Dazed targets deal 20% less posture. This can stack.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hammerfall', 'Hammerfall', 'Hammer Rage', 'Common', 'Clubs Aerial attacks do 25% more posture damage when blocked.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fan-the-flames', 'Fan the Flames', 'Heat Column', 'Common', 'Your stored Wind mantras can now empower your Fire mantras.', '["The effects of inhale (causing mantra modifiers to transfer across gale mantras) and the damage buff that Inhale grants, (Inhaled mantra''s level times 2)%, will now also affect flame mantras."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('all-the-dead-gods', 'All the Dead Gods', 'Heretic', 'Rare', 'Your Basic Attacks now apply anti-heal and 5% Heal Boost against PvE for 8s. (+7 Sanity)', '["Whenever you land an M1 or critical with the M1 tag, apply Anti-Heal for 8 seconds.","All the Dead Gods'' anti-heal effectiveness for sources of active healing scales on your combined Willpower and Intelligence investment. This has a minimum value of 70% at 55 combined points of Intelligence and Willpower, and a maximum value of 100% at 105 combined points.","All the Dead Gods loses 0.6% anti-heal for every combined point of Intelligence and Willpower below 105. For example, 80 combined points will have 85% anti-heal.","All the Dead Gods'' anti-heal effectiveness for sources of passive healing is always 100% regardless of your combined investment. Sources of passive healing include: campfires, Conditioned Runner, Curse of the No Life King, Chorus of Souls, and natural health regeneration.","Wearing a Ring of Pestilence increases All the Dead Gods'' anti-heal duration by 4 seconds; from 8 to 12.","The anti-heal cannot be procced on allies, and it does not affect healthpacks.","The Heal Boost status effect increases all non-passive healing gained from enemies who are currently affected by your anti-heal. This Talent grants +5% Heal Boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('all-above-gods-below', 'All Above, Gods Below', 'Heretic', 'Advanced', 'Any healing your opponent were to receive while All The Dead Gods is active on them is stolen and given to you, increase your PvE Heal Boost to 15% as well. (+20 Sanity)', '["Though not visually displayed, the duration of this effect is separate from your anti-heal.","All Above, Gods Below''s duration scales on your Willpower and Intelligence investment. At 200 combined invest, it will last for the full duration of your All the Dead Gods. For every point below 200, All Above, Gods Below''s duration will be reduced by 1% (relative to All the Dead Gods), down to a minimum of 50% of All the Dead Gods duration at 150 combined invest.","This will not proc if you are the one who applied the healing; you cannot heal yourself by healing your opponent.","This only procs on non-passive healing. For example (non exhaustive list): something like Flame Wisp, spits, or Bloodless Gem will proc this effect, but campfires, Conditioned Runner, or Curse of the No Life King will not.","The Heal Boost status effect increases all non-passive healing gained from enemies who are currently affected by your anti-heal. This Talent grants +15% Heal Boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heretics-sutra', 'Heretic''s Sutra', 'Heretic', 'Quest', 'A chant that steers you into the state of Insanity for 20 seconds.', '["Heretic''s Sutra has a base windup of 0.4s and a base cooldown of 24 seconds at 30 Willpower. For every point in Willpower above 30, the windup is reduced by 0.00429 seconds.","Has a windup of 0.186 seconds at 80 Willpower, a maximum windup of 0.293 seconds at 55 Willpower, and a minimum windup of 0.1 seconds at 100 Willpower.","Heretic''s Sutra has a base cooldown of 24 seconds at 30 Willpower. For every point in Willpower above 30, the cooldown is reduced by 0.085s.","Has a cooldown of 19.71 seconds at 80 Willpower, a maximum cooldown of 21.86 seconds at 55 Willpower, and a minimum cooldown of 18 seconds at 100 Willpower.","Gives a burst of insanity to yourself.","Immediately lose 15% sanity on use.","If above 80% sanity, immediately lose sanity down to 65%.","You start benefitting from Talents that require insanity to use (namely Lose Your Mind)","Talents that need you to be losing sanity to proc are passively activated for 15 seconds.","Namely Shared Misery and Piercing Will.","Note that this passive does NOT work with Lose Your Mind, as it only procs based on your current sanity percentage. And while Heretic''s Sutra can help with sanity loss, it does not passively activate Lose Your Mind."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sin-stacker', 'Sin Stacker', 'Heretic', 'Rare', 'Your All The Dead Gods'' duration is now based on how many stacks of antiheal you already have on your opponent, increase your PvE Heal Boost to 10% instead. (+8 Sanity)', '["By landing additional basic attacks on a target affected by All the Dead Gods'' Anti-Heal, you can increase the duration of subsequently applied Anti-Heal stacks by 1 second per Anti-Heal stacks affected the target.","Starting at 1 Anti-Heal stack lasting 8 seconds, applying another will make the second stack last 9 seconds, and applying another will make the third stack last 10 seconds, etc.","As Anti-Heal stacks decay, the additional duration they apply to future stacks will be nullified. For example, if you apply Stack 1 for 8 seconds and Stack 2 for 9 seconds, then wait until Stack 1 runs out of duration before landing another hit, Anti-Heal from the third M1 will only last 9 seconds.","The Heal Boost status effect increases all non-passive healing gained from enemies who are currently affected by your anti-heal. This Talent grants +10% Heal Boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brick-wall', 'Brick Wall', 'Human Architecture', 'Advanced', 'You refuse. You cannot be knocked off your feet until you are knocked completely Unconscious. Also reduces the duration of Knockdown. (+5 Health, +2 Posture)', '["The Knockdown duration reduction scales on your combined investment into the Willpower and Fortitude attributes, being fully negated if you have 100 points invested into both.","Gain total immunity to ragdoll, only being pushed back instead from moves that would normally ragdoll.","By extension, this makes you more resistant to knockback as a whole as the lack of ragdoll means you retain air friction.","Makes you resistant to the Eternal Gale, causing only momentary stun instead of ragdolling you.","Cap Artist is disabled with this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mythic-stability', 'Mythic Stability', 'Human Architecture', 'Rare', 'Players and regular mobs cannot instantly execute you while you''re on your feet. Protects you from one instance of instant execution when Unconscious. 60s CD.', '["Works on attacks such as The Doom of Caeranthil''s Sudden Ambush and Luminant Beam attacks that would normally insta-grip you. It will NOT, however, protect you against Blood Scourge or it''s corrupted variant."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('not-a-scratch', 'Not a Scratch', 'Human Architecture', 'Advanced', 'You don''t show any signs of damage. (+2 Posture)', '["Your character no longer visually shows any signs of damage no matter how low their HP is. No cuts, no scratches, no low hp anims, no torn clothing, etc.","Spotter (for your opponent''s allies) / Rhythm no longer shows how much health your character has.","If you have less than 100 Willpower, your character has a chance to yell out in agony upon taking damage. This is purely visual.","These include: \"HEEAAAAUUUUURRGHHH!!\", \"HEEAAAARRGH!!\", \"OHHHHH GODS THE AGONY!!\", \"YEAARURUGHH!!\", \"UUUURURGHHH!!\", and \"SWEET MEEEEEERRRRRCCCCCYYYY!!\". Quite dramatic.","The Trickster''s Habit and Jester''s Garb Outfits have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('peripheral-vision', 'Peripheral Vision', 'Hunter', 'Rare', 'Your glare now ignores if your opponent is facing you. (+5 Sanity)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bottom-freeze', 'Bottom Freeze', 'Ice Age', 'Common', 'Hitting chilled enemies with Ice Projectiles while they are on ice freezes them to the ground.', '["Prevents you from rotating your character and moving around overall.","Bottom Freeze will end early if damage is taken from any source."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cryonis', 'Cryonis', 'Ice Age', 'Common', 'All ice spells casted ontop of ice cost less Ether.', '["Ice Mantras cost 20% less ether if casted while standing on ice."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frost-buster', 'Frost Buster', 'Ice Age', 'Common', 'Greatsword Criticals and Greathammer Criticals now leave a place Ice below the path they carve.', '["On critical, create three moderately large ice patches in a linear path in front of yourself. These patches last 1 minute 30 seconds.","Despite what the Talent description states, Greathammers do not proc Frost Buster but Greataxes do. Greatcannons do not proc Frost Buster either.","Frost Buster can only proc once per critical.","Also grants the ability to freeze and damage boats with Greatsword and Greataxe criticals.","Frost Buster procs on any critical when used on a Greatsword or Greataxe including some strange cases such as critical-replacing Enchantments (Curse of the Unbidden, Nemesis, and Stormbreaker) and all fist style criticals on Markor''s Inheritor.","Because Frost Buster has no cooldown and has such a large amount of coverage, it is one of the best ice patch applicators in the game."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frozen-anchor', 'Frozen Anchor', 'Ice Age', 'Common', 'Apply bottom freeze and chill to your opponent whenever you land a flourish, uppercut, or crit. 10s CD.', '["Functions similarly to Meteor Impact, applying on any mantra that would proc it.","Bottom Freeze will be removed if the target takes damage from any source. This makes this Talent extremely ineffective on multihit criticals.","The Chill applied through this Talent has a 12 second duration, making it a strong option for hybrid builds that have limited opportunities to proc Chill.","Deals (0) Frostdraw damage as hitregistry for Chill. This allows you to proc certain Talents like Flashboil without any other source of Frostdraw damage.","Currently bugged and applies through block/parry/dodge."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frostbite', 'Frostbite', 'Ice Age', 'Common', 'Enemies can no longer heal when under the effect of your chill. PvE enemies also net you 5% more Heal Boost when they are chilled.', '["The Heal Boost status effect increases all non-passive healing gained from enemies who are currently affected by your anti-heal. This Talent grants +5% Heal Boost.","Works with Glass Path: Crystallization."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frozen-pin-cushion', 'Frozen Pin-Cushion', 'Ice Age', 'Rare', 'Ice Daggers now freeze opponents.', '["With crystal path, instantly procs Crystallization upon landing on the target, knocking them backwards and deal more damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('saint-jay', 'Saint Jay', 'Ice Age', 'Rare', 'When a Chilled enemy receives a heal, it''s nullified and 60% of the healing is redirected to you. While this is active and they are on ice your rate of healing is increased, raise your PvE Heal Boost to 10% as well.', '["This will not proc if you are the one who applied the healing; you cannot heal yourself by healing your opponent.","This only procs on non-passive healing. For example (non exhaustive list): something like Flame Wisp, spits, or Bloodless Gem will proc this effect, but campfires, Conditioned Runner, or Curse of the No Life King will not.","If using Glass Path: Crystallization then every hit with a Frostdraw mantra will proc Saint Jay for 2 seconds. (Doesn''t stack)","The \"on ice\" effect of Saint Jay is bugged and does not work.","The Heal Boost status effect increases all non-passive healing gained from enemies who are currently affected by your anti-heal. This Talent grants +10% Heal Boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stasis-strike', 'Stasis Strike', 'Ice Age', 'Common', 'Your crystal explosions deal more damage whenever your opponent is also bottom frozen.', '["Your Crystal detonations deal 67% more damage against targets who are bottom frozen."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unyielding-frost', 'Unyielding Frost', 'Ice Age', 'Advanced', 'Your Chill can proc through block, with blocked Chilling proc lasting 80% of the duration.', '["If you have less than 100 Frostdraw, your chilled duration (when applied through block) will be reduced down to 25% of its original duration instead.","Does not proc Frozen Legs.","Mutual Exclusive: Glass Path: Crystallization"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ignition-card', 'Ignition Card', 'Ignition Delver', 'Origin', 'A card representing your membership in the Ignition Union. Entitles you to speedier experience gain from Dungeons and Jobs, though the fees will slightly reduce your experience gain outside of these.', '["Gain increased EXP gain from Jobs and Dungeons, but reduced EXP gain from any other content."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('union-pager', 'Union Pager', 'Ignition Delver', 'Origin', 'Check up on job listings remotely.', '["Grants a Talent tool that acts as a remote-access Job Board, allowing you to pick up jobs from any location."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('union-hook', 'Union Hook', 'Ignition Union', 'Quest', 'You can now make use of the Ignition Union hooks to ascend or descend.', '["Prerequsites: Save Epsi in the entrance of Firfire then speak to Alpha OR Ignition Delver Origin"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('agitating-spark', 'Agitating Spark', 'Immolator', 'Common', 'Applying Burning to enemies spreads to to anyone nearby. Including yourself.', '["On proc, a small orange particle will trail between the burning target you hit and other targets nearby, setting them on fire.","Agitating Spark bypasses block and parry.","Agitating Spark procs caused by self damage will not apply burn. Flame Within is an exception to this.","Has a 1 second cooldown.","Can spread to allies. The Controlled Combustion Talent will prevent Agitating Spark spreading burn to yourself and your allies."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('immolation', 'Immolation', 'Immolator', 'Common', 'Fire spells cost 70% less while on fire. If you hit someone while on fire, apply fire damage. You take 50% less damage from self-inflicted flames. (+8 Sanity)', '["\"Self-Inflicted flames\" include Flame Within, Agitating Spark you spread and environmental burns created by you.","\"Apply fire damage\" applies the burn status effect instead of adding Flamecharm damage. It also applies burn even if you have Eruption Path: Lava Serpent.","Not all attacks proc this effect, unlike what the Talent description implies. Instead, all instances of Physical damage apply burn, even if the attack doesn''t deal pure Physical damage (e.g. Clutching Shadow or Metal Eruption). And all attacks that have the slash (blood particle) vfx on hit like Ice Daggers or Gale Lunge will also proc Immolation, applying burn."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('phoenix-flames', 'Phoenix Flames', 'Immolator', 'Advanced', 'Any time you would burn to death, you instead rise again with 50% of your health restored. Has a 60 second cooldown.', '["Healing scales on your Flamecharm investment; heals 25% health at 0 Flamecharm and scales up to 50% health at 75 Flamecharm, gaining 0.33% healing per point in Flamecharm.","If you used Flame Within while knocked to proc Phoenix Flames, then the healing received will be halved. Though, if you activated Flame Within prior to being knocked, you''ll receive the full healing."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('corpse-explosion', 'Corpse Explosion', 'Inferno', 'Common', 'Your flames will incinerate unconscious Targets much faster and bodies that you burn to death immediately explode dealing massive damage.', '["Burn grip unconscious targets, even yourself, in 3.5 seconds instead of 7.","The time it takes for burn to execute is very reliant on server performance, it may take longer than what is listed here.","The explosion does not work; you''ll burn them to death without an explosion."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pleekstys-faith', 'Pleeksty''s Faith', 'Inferno', 'Common', 'When on fire, automatically quench flames at the cost of some ether.', '["Does not proc with flames produced by the user with Flame Within or Agitating Spark.","Is also a requirement to fight Aska in Firfire. Without either this Talent, Pleeksty''s Will, or the Flame Worshipper Armor you will wipe through his flames."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('simmerbloom', 'Simmerbloom', 'Inferno', 'Common', 'Basic Attacks on Pleeksty''s Inferno are now granted flames.', '["Pleeksty''s Inferno Basic Attacks now apply burn/eruptions. This has no cooldown.","Due to this equipment Talent, Pleeksty Inferno users can save a few, otherwise necessary, talents like Flaming Flourish.","Obtained from Simmerbloom Diadem","Requirements for Equipment: Power 10, 80 Flamecharm"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ad-astra', 'Ad Astra', 'Innate', 'Race', 'Return Home', '["Grants a Talent tool that teleports you to The Floating Keep on use.","Using it while inside of the Floating Keep will take you back to where you initially used it."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chitin', 'Chitin', 'Innate', 'Race', 'You have a layer of Natural Armor that replenishes when you rest.', '["Grants 5% damage reduction in the form of Natural Armor.","Chitin has 215 durability at power 1, scaling up to 500 durability at power 20.","Chitin''s damage reduction stacks multiplicatively with the Exoskeleton Talent, granting 14.5% damage reduction assuming you have at least 40 Fortitude.","Having both Exoskeleton and Chitin will cause Exoskeleton''s durability to take priority, with +200 flat durability added on top, leading to 800 total durability at power 20.","Natural Armor regenerates while resting at a campfire at a rate of 2.2% per 0.2s, aka 11% per second.","Natural Armors are affected by PEN, but its effectiveness is reduced by 75%. (i.e. if someone has 100% PEN, your Natural Armor will resist 7.5% of their damage instead of nothing.)","Natural Armor will lose durability if you get hit by any attack, even if it doesn''t resist it.","Natural Armor loss is based on scaled damage received and cannot normally be increased nor decreased by anything, with the exception being damage reductions, like Reinforce, which will reduce the Natural Armor loss."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('deepfolk', 'Deepfolk', 'Innate', 'Race', 'The secrets of the Deep are easier for you to unravel. Your mind is sturdier against its effects, as well as using less Knowledge in Knowledge exchanges.', '["1.2x Sanity gain multiplier. You require 1 less Knowledge when making deals with Deep Shrines (Knowledge cost can''t go below 1)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('feathered-glider', 'Feathered Glider', 'Innate', 'Race', 'As a show of independence when they come of age, Tirans will strike out on their own with just their hand-crated glider, gliding down from the mountain peaks where they make their homes. You take 10% less fall damage.', '["Tirans gain Feathered Glider, a Glider with infinite durability. The glider changes color depending on the Aspect variant, and can be dyed.","When using the Glider hotkey, regular and Sharkscale Gliders will take priority over the Feathered Glider. You must use all of the durability in your other Gliders if you want to deploy the Feathered Glider with the hotkey."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('echolocator', 'Echolocator', 'Innate', 'Race', 'Your highly tuned hearing helps you navigate, seeing better in the dark and sensing potential threats.', '["Pings the location of nearby players who unsheathe their weapons (even through Tacet and Lowstride) and event spawns."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('loyalty', 'Loyalty', 'Innate', 'Race', 'Your bond with your allies is strong enough to reduce damage between you.', '["Allies take 35% less damage from you and deal 35% less damage to you. This can stack with the Give and Take Talent, totaling to 48% damage reduction.","This does not apply to self damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mark-of-jurik', 'Mark of Jurik', 'Innate', 'Race', 'Mark of Jurik, the Moonseye. A beacon of calm, those in your presence are resistant to insanity.', '["Gain a tool that lowers the sanity drain of nearby players. Also buffs effected players'' HP regen and slightly buffs their food & thirst replenishment from consuming food and their blood regen. 4m CD.","These buffs last 1 minute, the HP regen is 15% of their total HP over that one minute period, healing 0.25% HP per second.","Also buffs non allies. Does not require you to be resting at a campfire."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mark-of-ku', 'Mark of Ku', 'Innate', 'Race', 'Mark of Ku, the Mother. Improves the rest of those in your presence.', '["Gain a tool that buffs the blood regen of nearby players. Also buffs the effected players'' HP regen and slightly buffs their sanity and their food & thirst replenishment from consuming food. 3m 30s CD.","These buffs last 1 minute, the HP regen is 15% of their total HP over that one minute period, healing 0.25% HP per second.","Also buffs non allies. Can only be used while you are resting on a campfire."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mark-of-nemit', 'Mark of Nemit', 'Innate', 'Race', 'Mark of Nemit, the First Beast. Food consumed in your presence is more nourishing.', '["Gain a tool that buffs the food and thirst replenishment of nearby players. Also buffs the effected players'' HP regen and slightly buffs their blood regen and sanity. 3m 30s CD.","These buffs last 1 minute, the HP regen is 15% of their total HP over that one minute period, healing 0.25% HP per second.","Also buffs non allies. Can only be used while you are resting on a campfire."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('maudet', 'Maudet', 'Innate', 'Race', 'Your understanding of your destiny is such that learning new things often comes naturally to you. People appreciate your diplomatic ways of speaking.', '["Passively obtain the benefits of the Autodidact Boon, gaining 3 Free Training Attribute points to spend every level. This effect stacks with the Boon in question.","Increases reputation gain with factions."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('molt', 'Molt', 'Innate', 'Race', 'Ailments and blessings alike fade away more quickly.', '["Status effects, good or bad, have a shorter duration.","Only works on Chilled, Potions, and Suffocation."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mothwing-dust', 'Mothwing Dust', 'Innate', 'Race', 'You release Mothwing Dust when others are the first to strike, granting you vision of your attacker. Your antennae improve your peripheral senses, narrowing the angle at which you can be backstabbed.', '["When you are hit at the start of combat, the player who hit you will be highlighted with a translucent red outline. This effect lasts 10 seconds.","The angle at which you can be backstabbed is reduced heavily."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('navaes-guidance', 'Navae''s Guidance', 'Innate', 'Race', 'Navae''s star guides your path, showing you the way forward. Right-clicking on maps sets a Waymarker which can be followed. You are less prone to starvation.', '["Receive a compass, displayed at the top of your screen, which points East.","Right clicking on the map will place a waypoint both in the physical world and on the map itself. If you already have a waymarker placed, right clicking on the map will change its location instead of placing a new one.","Lower the passive hunger decay.","If you have the Blind flaw, gain an area of vision around your character."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('nightchild', 'Nightchild', 'Innate', 'Race', 'Relying on your instincts, you are naturally more stealthy. You are more nimble on wooden surfaces.', '["Start with 20% more stealth and gain a 1.2x stealth gain multiplier.","This Stealth gain multiplier does not apply to Stealth gained from Crouching, Lowstride, Tacet, or Tacet Minimization.","This Stealth multiplier affects the Obvious Flaw, reducing your Stealth by 24%. With the innate Stealth Felinor has, this will result in a net -4% Stealth on spawn.","Gain bonus agility when climbing on all kind of surfaces, not only wooden ones."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('seaborne', 'Seaborne', 'Innate', 'Race', 'You have a keen understanding of ships and their maintenance.', '["Ships cost 20% less Notes, turn 20% faster, and have 10% more health."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('teachings-of-the-edenkite', 'Teachings of the Edenkite', 'Innate', 'Race', 'Find your centre.', '["Allows you to meditate, emitting a white aura and causing two white orbs to circle your head. Very heavily reduces your hunger and thirst consumption while you passively gain EXP and Attribute EXP and regenerate health at a mediocre rate, which is slightly reduced when in combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('versatile', 'Versatile', 'Innate', 'Race', 'You learn how to use new pieces of equipment quicker than others. You can equip things at 3 points lower than the requirement.', '["This does not work on Power requirements.","This works for both Equipment and Weapon requirements.","Versatile lowers all requirements on things with more than one, so a 72 Galebreathe 37 Medium Weapon Curved Blade of Winds would be possible on a Khan for example. Additionally, Versatile stacks with Silentheart''s Weapon stat requirement reduction."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('critical-engine', 'Critical Engine', 'Intelligence', 'Common', 'You gain the ability to use Deep Gems on your critical attack. Hold out the Deep Gem you wish to apply to your crit then use the tool to enhance your critical.', '["Equipping a Deep Gem to your critical will not consume the Deep Gem.","Proccing this Talent will put the respective Deep Gem on cooldown if it has one.","Mantle of Enmity can proc Critical Engine. If you use a Blessed Gem, your Mantle aerial attack will halve your critical cooldown rather than your Mantle''s.","Aegis Gem grants you 10% damage reduction for 10 seconds on hit.","Blessed Gem halves your critical cooldown on hit.","Warmaster''s Medallion critical cooldown reduction is applied before this effect, allowing for a 60% (55% in Chime of Conflict) reduction in critical cooldown overall.","Bloodless Gem Reduces your critical damage by 20%, but grants healing equal to 30% of the damage dealt.","Blue Gem grants you Ether back on hit. The Ether restoration is 1:1 with scaled damage dealt; it cannot be increased nor decreased through modifiers or resistances. This effect does not have PvE scaling.","Insignia Gem reduces the windup of your next Mantra cast by 15% on hit.","Might Gem increases the posture damage of your critical by 10%.","The posture damage bonus can be increased with the Ascended Outlaw Hat Talent, scaling on how many Might Gems you have equipped on your Mantras.","Warped Blue Gem grants the Etherguard status effect on hit if you are wearing the Bluestone Set.","Wayward Gem teleports you to your opponent after landing your critical. There is a 1 second delay between you landing your critical and teleporting.","Wind Gem gives you a speed boost for 8 seconds on hit.","Wrath Gem applies the Wrath status effect for 9 seconds, increasing your critical damage by 7.5% per player combat tag you have. This damage bonus does not apply to the hit that procced Wrath Gem and is affected by the damage modifier cap. Additionally, this can be used to proc the Reinforced War Set Talents.","Nocturnal Gem will deal an additional 10 slash damage after a 1 second delay."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('backstabber', 'Backstabber', 'Inquisitive Lethality', 'Faction', 'Landing a backhit with a light attack causes you to grab your opponent and stab them again, dealing an extra 15 damage.', '["Procs on M1s, Silentheart abilities, and criticals with the M1 tag.","This Talent does not have a range limit.","Applies daze and ragdolls."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('executioners-frenzy', 'Executioner''s Frenzy', 'Inquisitive Lethality', 'Faction', 'Landing a light attack while your opponent''s posture is paused reduces their assassination cooldown by 5 seconds.', '["The Paused Posture status effect comes from Stature Break and Maiming Claws."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fatal-stealth', 'Fatal Stealth', 'Inquisitive Lethality', 'Faction', 'You deal increased backstab damage to opponents based on how high your stealth stat currently is.', '["Grants +0.2% damage per 1 Stealth to attacks that hit your opponent''s back. This affects all damage sources that can receive damage modifiers.","Stealth that is not gained from Equipment or Outfit sources do not count towards this Talent.","Strangely, the Obvious Flaw is an exception to this, reducing your backhit damage by 4%.","The following Stealth sources do not apply to this Talent''s damage buff: Felinor''s innate Stealth and its Stealth gain multiplier, Agility investment, Crouching, Lowstrude, Murmur: Tacet, and Tacet Minimization.","This does not buff assassinations.","See the Stealth page for info on where stealth can be obtained.","The maximum Stealth you can gain from Equipment alone is 30% (+6% damage).","Notably the Inquisition Light Outfit grants 50% Stealth (+10% damage)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flanking-maneuvers', 'Flanking Maneuvers', 'Inquisitive Lethality', 'Faction', 'Enemies you assassinate take more PEN from your squadmates in your party.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stature-break', 'Stature Break', 'Inquisitive Lethality', 'Faction', 'Landing a backstab of any kind disables posture for 8 seconds.', '["This applies the Paused Posture Status effect, denying most sources of Posture restoration.","During Paused Posture, you cannot restore posture by: passive posture regen, Parrying, or the Steady Nerves Talent. All other forms of posture restoration entirely ignore this status effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tacet-minimization', 'Tacet Minimization', 'Inquisitive Lethality', 'Faction', 'Focus your Tacet even further, allowing the radius at which you get spotted to become smaller temporarily.', '["Decreases your Tacet bubble size to the minimum possible and grants 400% flat Stealth for 10 seconds. 1 minute cooldown.","Requires maximum Ether to use, even though it does not consume Ether.","Tacet gained by obtaining Soulbreaker does not count for this Talent''s obtainment."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ironsing-unbounded', 'Ironsing Unbounded', 'Ironsing Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Ironsing to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ironsinger', 'Ironsinger', 'Ironsinger', 'Mantra Level', 'Grants you the ability to command Metal as an Ironsinger. Press input=X to Pull on Metal Rods.', '["Ironsing mantras apply stacks of Metal Rods on targets. Pressing input=X will pull affected towards you, with the strength of the pull depending on the amount of Metal Rods present.","You cannot apply more than 5 Metal Rods to one target, unless you have one of the Rending Needle Talents.","Rod pull''s keybind can be configured in settings.","Obtained at 1 Ironsing"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-ironsinger', 'Adept Ironsinger', 'Ironsinger', 'Mantra Level', 'You can now obtain 1-star Ironsinger mantras.', '["Obtained at 20 Ironsing"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-ironsinger', 'Expert Ironsinger', 'Ironsinger', 'Mantra Level', 'You can now obtain 2-star Ironsinger mantras.', '["Obtained at 30 Ironsing"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-ironsinger', 'Master Ironsinger', 'Ironsinger', 'Mantra Level', 'You can now obtain 3-star Ironsinger mantras. (+5 Health)', '["Obtained at 50 Ironsing"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('alloyblood', 'Alloyblood', 'Ironsinger', 'Advanced', 'You don''t bleed like others do. Bleed damage reduced by 30%. Blood loss is reduced by 75%.', '["While at 100 Ironsing, bleed damage is reduced from 15% scaled damage to 10.5%. Bleed from Speed Demon is reduced from 7.5% scaled damage to 5.25%.","Blood loss reduction is less effective if you are using the Curse of the No Life King Enchantment.","Blood loss reduction stacks multiplicatively with Cauterized Wounds.","Alloyblood''s effects linearly scale with Ironsing investment up to its requirement, losing 0.3% bleed damage reduction and 0.75% blood loss reduction per point in Ironsing below 100.","Makes your blood a shade of light grey when being attacked by a bleed damage attack. Additionally, it changes your Bloodrend mantras to the same grey."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heavy-shoulders', 'Heavy Shoulders', 'Ironsinger', 'Common', 'If your opponent has 3 or more rods, their dodges are slower.', '["Reduces roll distance by 10%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ironclad-punishment', 'Ironclad Punishment', 'Ironsinger', 'Common', 'Your Ironsing mantras deal more posture damage to enemies the more armor durability they have.', '["Gain +0.15% posture damage on Ironsing Mantras for every 1% armor durability your opponent has, capping at +15% if your opponent is at maximum armor.","Has limited PvE usage because most non-humanoid monsters cannot block."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('laced-traps', 'Laced Traps', 'Ironsinger', 'Common', 'People hit by your ''Caltrops'' cannot jump and are slowed for a small duration, while also applying Sluggish to PvE enemies for a few seconds.', '["Landing a Caltrop slows down your opponent and disables their ability to jump for 1.1 seconds. This effect refreshes if the victim gets hit by another Caltrop.","The Sluggish status effect applies a -15% damage debuff to affected targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('metal-shackles', 'Metal Shackles', 'Ironsinger', 'Common', 'Guardbreaking an opponent prevents them from receiving speed boost for 5 seconds, while PvE opponents will be Sluggish for 12 seconds.', '["The Sluggish status effect applies a -15% damage debuff to affected targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('oh-the-irony', 'Oh The Irony', 'Ironsinger', 'Common', 'Opponents affected by ''Taunt'' receive double iron rods for the duration.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('piercing-metal', 'Piercing Metal', 'Ironsinger', 'Common', 'Deal additional armor damage to enemies per metal rod affecting them.', '["Each rod increases armor damage dealt through weapon attacks and Mantras by 5%.","This stacks additively, up to 25% more armor damage without any Rending Needle Talent or 50% more armor damage with Jailer or Impaler.","Works amazingly in PVE.","Does not affect armor drain effects such as Metal."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('thornmail', 'Thornmail', 'Ironsinger', 'Common', 'Getting flourished applies a metal rod on your attacker.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('willpower-unbounded', 'Willpower Unbounded', 'Iron Will', 'Common', 'You have gained the ability to surpass your limits and train your willpower to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('enrage', 'Enrage', 'Instigator', 'Common', 'Whenever you stun an opponent who''s taunted with encore, enrage them.', '["Unlock requirement: wipe while using the Strange Merchant memento."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grand-skewer', 'Grand Skewer', 'Javelin Lord', 'Rare', 'Your Grand Javelin now carries opponents through the air.', '["Press input=F during Grand Javelin''s windup to activate this effect.","Does not work in Guild Bases or in Layer 1 of The Depths."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('acceleration-points', 'Acceleration Points', 'Jetstriker', 'Oath', 'Striking an opponent in the back with mobility mantras or Basic Attacks now steals and grants additional momentum.', '["Requirements: Oath: Jetstriker, speak to Alirian after collecting X Jetstriker Orbs OR pay 10 to Alirian to skip Jetstriker''s progression entirely (requires you to have fully progressed the Oath at least once)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('decisive-winds', 'Decisive Winds', 'Jetstriker', 'Oath', 'When damage below 50% health, don an aura of Decisive Winds for 10s. (+5 Ether)', '["Decisive Winds grants a 25% speed boost as long as you are within 20 studs the target who initiated this effect.","30 second cooldown.","Procs through block/parry/dodge, despite the description stating otherwise. But it does not proc on self damage.","Opposite to the description, Decisive Wind''s has no \"aura\", there is no SFX or VFX, with the only activation cue for this talent being the Cooldown Indicator.","Requirements: Oath: Jetstriker, speak to Alirian after collecting X Jetstriker Orbs OR pay 10 to Alirian to skip Jetstriker''s progression entirely (requires you to have fully progressed the Oath at least once)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('jetstream-pursuit', 'Jetstream Pursuit', 'Jetstriker', 'Oath', 'Upon a successful flourish, teleport to the opponent when they stop moving. Receive a significant boost of momentum.', '["When proccing on non-humanoid NPCs, sends you to the center of the NPC''s hitbox.","Requirements: Oath: Jetstriker, speak to Alirian after collecting X Jetstriker Orbs OR pay 10 to Alirian to skip Jetstriker''s progression entirely (requires you to have fully progressed the Oath at least once)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rush-of-ancients', 'Rush of Ancients', 'Jetstriker', 'Oath', 'Dashing at maximum sprint momentum makes you one with the wind itself. (+4 Passive Agility)', '["Extends your dash distance and makes you invisible for a very brief duration when you dash.","Requirements: Oath: Jetstriker, speak to Alirian after collecting X Jetstriker Orbs OR pay 10 to Alirian to skip Jetstriker''s progression entirely (requires you to have fully progressed the Oath at least once)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stratos-step', 'Stratos Step', 'Jetstriker', 'Oath', 'Holding space while climbing will now let your perform Stratos Steps to get even higher. (+5 Health, +3 Passive Agility)', '["Stratos Steps will only proc twice before going on a cooldown. Said cooldown applies to individual steps. Additionally, Stratos Step consumes Ether per step.","Requirements: Oath: Jetstriker, speak to Alirian after collecting X Jetstriker Orbs OR pay 10 to Alirian to skip Jetstriker''s progression entirely (requires you to have fully progressed the Oath at least once)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('electrify', 'Electrify', 'Jumpstarter', 'Common', 'Shock yourself and apply Amped for 15s. Can be used while Carried to escape.', '["Grants a Talent tool.","Electrify has a 1 minute cooldown.","Deals 5% of your current health as Thundercall self damage.","Wearing the Stormchanter''s Raiments will remove Electrify''s self damage. Additionally, pairing this with the Deepscorn Casque will cause you to heal on Electrify cast instead.","Amped grants your weapon attacks a 10% damage buff and allows them to apply Shock or Surge Rods on hit.","While Amped, you take 10% more damage from all sources.","Deals Thundercall self damage with hitstun and applies Shock/Surge Rods to yourself on cast, if used without being carried.","Formerly known as Static Withdraw."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('amplified-reflexes', 'Amplified Reflexes', 'Jumpstarter', 'Common', 'Amped now grants enhanced speed and parkour, but triples the self-damage on use and doubles its cooldown.', '["Increases Electrify''s cooldown from 1 minute to 2.","Deals 15% of your current health as Thundercall self damage. Stormchanter''s Raiments still works to remove the self damage.","Increases walk speed by 50% and grants a 20% buff to climb height. All other forms of parkour and movement are unaffected by Amplified Reflexes.","Formerly known as Jumpstart.","Mutual Exclusive: Amplified Rage"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('amplified-rage', 'Amplified Rage', 'Jumpstarter', 'Common', 'Amped now grants you an additional +10% weapon damage.', '["Increases Amped''s damage buff from +10% to +20%.","Formerly Known as Raging Static.","Mutual Exclusive: Amplified Reflexes"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('jus-karita', 'Jus Karita', 'Justicar', 'Quest', 'Adopt the kick-based fighting style of the Justicars.', '["Allows you to use the Jus Karita fist style."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('justicars-prowess', 'Justicar''s Prowess', 'Justicar', 'Common', 'Jus Karita gains +30% posture damage against other fist styles.', '["Gain +30% posture damage on weapon attacks against opponents using Way of Navae, Fang and Coil, Imperium Kata, Untrained Fist, or Legion Kata."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('justicars-renewal', 'Justicar''s Renewal', 'Justicar', 'Common', 'Hitting an opponent with your Jus Karita critical resets the cooldown. (Cooldown of 10 seconds).', '["Whenever you land the critical of Jus Karita, you can immediately use it again with no delay.","This effect can only happen every 10 seconds.","Despite the card saying \"hitting\", you do not need to damage someone to reset the cooldown (if it gets blocked, parried or dodged, it also resets it)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('swiftkick-prodigy', 'Swiftkick Prodigy', 'Justicar', 'Common', 'Hitting successive Basic Attacks with Jus Karita will give a temporary speed buff.', '["Hitting your opponent with the M1s 3 times will grant you a speed boost."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flying-swiftkick', 'Flying Swiftkick', 'Justicar', 'Common', 'Hitting a Jus Karita critical attack while Swiftkick Prodigy is active will greatly slow your enemy, and consume your speed boost.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('kickstart', 'Kickstart', 'Kickstarter', 'Common', 'Play the resurrector. Use your lightning to defibrillate your allies on the battlefield.', '["Use kickstart on a knocked target to bring them back up in 3 seconds at the cost of some ether.","Kickstart''s animation takes 3 seconds to complete, and you cannot act during this animation.","Despite the description stating \"allies\", this can be used on non-allies and even humanoid NPCs.","Takes 5% ether on use and an extra 20% on successive use.","Heals 10% of the affected target''s health.","Can be used on people who are using Kickstart or are affected by Paralytic Dust."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blades-edge', 'Blade''s Edge', 'Lancer', 'Common', 'Spears Damage dealt with the tip of the spear is increased by 10% (+2 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('defensive-sweep', 'Defensive Sweep', 'Lancer', 'Common', 'Spears Posture breaking an opponent grants you +50% PEN for 3 seconds.', '["The PEN buff only applies to M1s.","14 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('driving-impact', 'Driving Impact', 'Lancer', 'Common', 'Spears The first hit of your Spear''s Critical Attack will deal greatly increased posture damage. Subsequent hits will do reduced posture damage.', '["This only works on the default spear critical.","Doubles the posture damage of the first hit of your spear critical at the cost of nullifying the posture damage from the second. This essentially consolidates the posture damage of the critical to the first hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lancers-impale', 'Lancer''s Impale', 'Lancer', 'Common', 'Spears Hitting an enemy after a perfect dodge makes your next attack deal 30% bleed damage. If that attack would already bleed, it adds +10% chip damage instead. (+4 Passive Agility)', '["Only grants 15% Bleed damage despite what the description states."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hoplite', 'Hoplite', 'Lancer', 'Common', 'Posture damage is reduced by 15% when wielding a spear and standing still. (+2 Passive Agility)', '["The Legion Phalanx Plate equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('eruption-path-lava-serpent', 'Eruption Path: Lava Serpent', 'Lava Serpent', 'Common', 'Your fire abilities no longer proc burn and instead proc an eruption under the enemies feet.', '["Instead of setting your target on fire, create an eruption on hit with a 3 second cooldown. Eruption damage scales with your Flamecharm investment.","Despite what the Talent description says, you can still apply burn with Eruption Path.","Burn can still be applied via: Agitating Spark, Flame Within (Self), Flash Point, Immolation, and hitting flammable terrain with Flamecharm or Thundercall Mantras.","Because of there being so few sources of burn application with Eruption path, using Talents that require burn, especially Emperor Flame, with this path is not recommended. Those Talents all still function normally though of course.","Eruptions have 15 base damage with 5 Flamecharm Scaling. Formula to calculate damage here: \"15 * (1 + (5/10) * (Flamecharm invest/100))\"","Mutual Exclusive: Flashboil, The Final Act, Wraith Path: Twisted Puppets"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('empowered-eruption', 'Empowered Eruption', 'Lava Serpent', 'Common', 'Your next Eruption after landing a critical is Empowered with +50% range and damage. 10s cooldown.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flash-point', 'Flash Point', 'Lava Serpent', 'Common', 'Block breaking an opponent causes your Eruptions to be Empowered for the next 10s. 45s CD. Block breaking an opponent with a Fire Mantra procs Burning.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('the-floor-is-lava', 'The Floor is Lava', 'Lava Serpent', 'Advanced', 'Your Eruptions leave lethal pools of lava beneath them. Don''t fall in.', '["Has slight Flamecharm scaling for its damage.","Duration of the lava pools scales on your Flamecharm investment."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('callout', 'Callout', 'Leader', 'Common', 'You can mark objects or enemies by pressing input=Z, which will mark them for all nearby allies.', '["Callout''s activation keybind can be configured in settings."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('spotter', 'Spotter', 'Leader', 'Common', 'Marking enemies while in Rhythm will now indicate their health status to your allies.', '["Activated by using Callout (pressing input=Z).","Callout''s keybind can be configured in settings.","Disabled on players with Not a Scratch.","Note: This Talent does not work if you don''t have Callout, you''ll need Callout to use Soulbreaker''s Spotter."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('observation', 'Observation', 'Leaf in the Wind', 'Rare', 'Dodge frames are larger if you cancel your roll immediately. (+1 Passive Agility)', '["Cancelling your roll quickly will grant dodge frames equal to the length of a regular roll. Basically giving extra 0.1s dodge frames.","Mutual Exclusive: Risky Moves"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('safety-dance', 'Safety Dance', 'Leaf in the Wind', 'Rare', 'Your base dodge frames are increased by 0.05s. (+1 Passive Agility)', '["You gain more invincibility frames while dodging, granting you longer immunity to damage.","Dodge IFrames increased from 0.3s to 0.35s.","Mutual Exclusive: Risky Moves"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('air-pressure', 'Air Pressure', 'Legion Shock Trooper', 'Common', 'Dodging an attack or hitting an enemy''s block will transform your next dash into a Gale Dash. Gale Dashes carry you further than regular dashes and have extended iframes, but will clear immediately should you initiate an attack. (+1 Passive Agility)', '["8 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cyclone-blade', 'Cyclone Blade', 'Legion Shock Trooper', 'Common', 'After a successful Gale Dash you wrap your weapon in wind, causing your next Light attack to do +30% damage as bleed and have +10% chip damage. (+2 Passive Agility)', '["Does not have a cooldown, lasts for 3s.","Also procs from Phantom Step dashes.","Despite the Talent description stating \"Light attack\", it also grants its buffs to weapon criticals."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pressure-break', 'Pressure Break', 'Legion Shock Trooper', 'Common', 'Breaking an enemy''s posture will cause them to take intense wind pressure, increasing the attack''s damage by +25% and flinging the enemy backwards. (+2 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('wind-step', 'Wind Step', 'Legion Shock Trooper', 'Common', 'Create a step of wind below you when jumping in the air. Jumping while sliding down a slope or off a cliff launches you forwards.', '["Press space while in the air to double jump. This leaves a small tornado behind that someone else can jump into to also double jump.","While in combat, this ability cost Ether to use.","Jump while sliding down a slope to perform a gale leap that propels you forwards."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('savior', 'Savior', 'Liberator', 'Common', 'After saving a player from being gripped gain a short speed boost for a short duration. (+1 Sanity)', '["\"Saved\" being interrupting a grip attempt.","The speed boost lasts 15 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scorched-peak', 'Scorched Peak', 'Lichtenberg', 'Common', 'Blockbreaking an enemy on fire or with a fire mantra causes them to be struck by lightning.', '["\"On fire\" means currently burning.","Deals 10 Thundercall damage.","Procs Grounding Bolt."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('comeback-kid', 'Comeback Kid', 'Limitbreaker', 'Common', 'When waking up from being Unconscious you are unable to be knocked down for 5 seconds.', '["Gain total immunity to getting knocked when you wake up from being knocked. You can still be damaged but wont be knocked even at 0%.","2 minute cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('defiant-until-the-end', 'Defiant until the End', 'Limitbreaker', 'Common', 'Slow the enemy trying to execute you down with one last shout of your determination. (+6 Sanity)', '["Players with this Talent will shout \"THINK YOU''VE SEEN THE LAST OF ME\" when gripped, which slows down the grip attempt.","Stacks with Last Second Negotiations (with both a grip takes about 6.5 seconds).","The Ironsinger Heavy Plate equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('last-resort', 'Last Resort', 'Limitbreaker', 'Common', 'Deal +5% more damage when your health is below 25%. (+10 Sanity)', '["Red particles appear around your shoulders while the Talent is active."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('the-eleventh-hour', 'The Eleventh Hour', 'Limitbreaker', 'Common', 'When below 15% health your mantras require no ether to cast for 11 seconds. (+10 Sanity)', '["Lasts 30 seconds with a 90 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('entropy-link', 'Entropy Link', 'Linkstrider', 'Oath', 'The world is broken, linked by fragile webs. Traverse the path by stating your destination amidst the flame.', '["You are able to fast travel to certain places while resting at a campfire. Locations are unlocked by interacting with special meteorites that are scattered around the map. By sitting at a campfire and typing out the name of the desired meteorite, you will be transported directly to it.","You can carry objects and people during teleportation. If you are carrying a player, take caution, as there is a high rate of failure (due to overall bugginess).","Six meteorites can be located throughout the overworld:","Etrean Luminant:","Ceres (Overlooking the path to the abandoned cabin below Etris, on a black rocky outcrop)","Europa (On the top part of the rocks overlooking the entrance to Valley of Heroes, to the right.)","Fortuna (Above Erisor''s Church)","Eastern Luminant:","Hygiea (Near Songseeker Wilds Sea Highway)","Eunomia (Above Sibex)","Pallas (On the small bit of land by the Miner''s Landing''s Sea Highway)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('symbiotic-link', 'Symbiotic Link', 'Linkstrider', 'Oath', 'Activate by pressing input=X while hovering over an ally or enemy. The Links are destroyed when you receive damage from a non-ally, you stray too far or you activate it again. Only one cord of each type may exist at once, links give a 3 second warning in break range, in the warning phase, they can''t be broken.', '["Blue Cords (Allies) gain a speed boost, 20% damage resistance, and a 5% damage increase.","Red Cords (Enemies) gain a minor speed debuff.","This ability only can be used to a humanoid npcs and players.","Allows you to passively see the health bar of allies, even when not active."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mark-of-the-lone-warrior', 'Mark of the Lone Warrior', 'Lone Warrior', 'Origin', 'Progress much faster when progressing alone. Gain a damage boost when facing threats alone and also when outnumbered.', '["Grants an experience multiplier if no other player has credit for the mob kill or event completion.","Deal 5% more damage to opponents you''ve combat tagged or opponents who have combat tagged you, but only if they have less or an equal amount of combat tags as you.","The damage buff does not work if any of your allies are in the server, even if you have No Holds Barred toggled on."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('silencers-song', 'Silencer''s Song', 'Maestro''s Technique', 'Common', 'Silencer''s Blade now procs on your mantras.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('old-habits-die-hard', 'Old Habits Die Hard', 'Marauder', 'Common', 'Blocking an attack with your lingering block frames after failing a parry will cause the attack to deal 15% less posture damage. (+5 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('thresher-claws', 'Thresher Claws', 'Marauder', 'Rare', 'All of your attacks have +5% more PEN. Your Basic Attacks and Criticals have an additional +5% PEN on top.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('leg-shot', 'Leg Shot', 'Marksman', 'Rare', '[Rifles] Landing your critical slows your enemy for a bit while making PvE enemies Sluggish, and also disables any speed boosts they get for the next 10 seconds.', '["The Sluggish status effect applies a -15% damage debuff to affected targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stock-bash', 'Stock Bash', 'Marksman', 'Common', 'Rifles Your running attacks now apply a brief amount of daze and Stagger PvE enemies.', '["The Stagger status effect makes your opponent take 33% more posture damage.","Applies daze for one second."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tactical-reload', 'Tactical Reload', 'Marksman', 'Rare', 'Rifles Activate to make your rifle shoot bullets for 15 seconds.', '["90 second cooldown.","Upon activating the Talent tool, your rifle will gain the ability to fire Bullets for 15 seconds, with a downtime of 75 seconds.","You do not need to have physical bullets in your inventory for this to work.","Has a 45 second cooldown instead if you are wielding the Rosen''s Peacemaker, giving it a downtime of only 30 seconds.","This talent has no effect on Rifle Spear."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('survival-kit', 'Survival Kit', 'Master Survivalist', 'Common', 'You keep a well-stocked set of tools on your person at all times. Your flint never runs out of uses.', '["Flint now has infinite uses.","Obtainment: Wipe with Iron Gut and Termite."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('impervious-slumber', 'Impervious Slumber', 'Meditative Trance', 'Rare', 'Getting hit while Unconscious no longer resets your time Unconscious.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('breathing-exercise', 'Breathing Exercise', 'Mental Fortress', 'Common', 'Your sanity recovers more quickly once out of terrifying situations. (+5 Health)', '["Your passive sanity regen is increased by 50%","You do not regen sanity when something is actively draining it, like being in The Depths.","Increases passive sanity regeneration at day time 0.25>0.375 sanity per second (0.05>0.075 during night time), Campfire sanity regen 0.5>0.75 sanity per second.","The Celtor Commander Plate and Pathfinder Lantern equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('conquer-your-fears', 'Conquer your Fears', 'Mental Fortress', 'Common', 'Killing the beings of the deep replenishes your sanity somewhat. When an Ally grips an enemy nearby to you, you regain Sanity. (+3 Sanity)', '["Recover sanity when killing monsters in The Depths, the amount depending on how strong the monster is.","You regain Sanity when Allies grip a humanoid near you (either a player or a mob).","The Diver''s Light Plate equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('disbelief', 'Disbelief', 'Mental Fortress', 'Common', 'You''re resistant to the effects of Illusion magic. You are resistant to charms and tricks. (+5 Sanity)', '["Halves the duration of the Charmed status effect and Illusionary Servant casted against you.","Tough Love: 2s -> 1s","Overcharm''s Basic Attacks and Kyrsieger critical attack: 5s -> 2.5s","Unnecessary Theatrics (at reqs): 7s -> 3.5s","Dread Whisper and Sing: 7.5s -> 3.25s","Overcharm''s self-charm proc: 8s -> 4s","Charismatic Cast, Allure: 10s -> 5s","Chaotic Charm, Fadetrimmer''s Charming Spray: 15s -> 7.5s","Lasting Charisma (at reqs): 20s -> 10s","The Dark Owl Cloak equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('art-of-the-deal', 'Art of the Deal', 'Merchant', 'Common', 'Your rapport with merchants gives you lower prices!', '["Reduces an item''s purchase price by 10%.","Obtained by equipping an Aristocrat Coat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('intuitive-repairs', 'Intuitive Repairs', 'Metallurgist', 'Common', 'Your ''Iron Skin'' repairs armor while it''s active.', '["Iron Skin also repairs natural armor from Chitin and Exoskeleton."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('metal-absorption', 'Metal Absorption', 'Metallurgist', 'Common', 'Your ''Iron Hug'' also absorbs armor from the enemy.', '["Iron Hug will steal 10% of your opponent''s current armor durability and siphon it back to yourself."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('metal-eater', 'Metal Eater', 'Metallurgist', 'Common', 'When you have no ether, consume Armor durability to cast your Ironsing mantras.', '["Consumes 30% of your maximum armor on proc regardless of the Ether cost of the Mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('metal-thief', 'Metal Thief', 'Metallurgist', 'Common', 'Pulling an opponent absorbs a portion of their current Armor durability.', '["Steals 2% of your opponent''s current armor durability per rod."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('polished-armor', 'Polished Armor', 'Metallurgist', 'Common', 'You receive 5% less damage when your Armor protects you from an attack and has over 90% durability. This 5% will scale up to 10% less damage at 100 MTL.', '["The damage reduction of Polished Armor is increased by 0.05% per Ironsing investment, granting 8.75% damage reduction at requirements."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chain-of-perfection', 'Chain of Perfection', 'Metamancer', 'Echo', 'You gain stacks of Perfection on hitting mobs with Weapon Attacks or Mantras. Mantras are only worth half a stack.', '["Gain a 5% damage buff against PVE enemies for every stack of Perfection above 5, capping at +100% damage at 25 stacks.","Upon taking damage from any non-self damage source, you will lose all stacks of Perfection. Fall damage also removes all stacks.","Perfection acts as a final damage multiplier that bypasses the damage modifier caps.","Damage sources that cannot receive damage modifiers (e.g. Burn) do not benefit from Chain of Perfection stacks.","You cannot gain more than 3 stacks per attack.","Upon taking damage from any non-self damage source (excluding fall damage), all stacks will be lost.","Once you have obtained this Talent on any character, you will receive this Talent automatically on all subsequent characters."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('already-dead', 'Already Dead', 'Ministry Prophet', 'Common', 'You take reduced damage from abilities with a health cost.', '["Removes Deepspindle running critical self-damage.","Reduces the self damage from Shade Devour, Flame Within (on cast, NOT the burn ticks), Rush Hour, Shadow Travel, and Electrify.","When paired with the Stormchanter''s Raiments Talent, Circuit Breaker, using Electrify will cause you to heal instead of taking damage.","Lowers self damage from the Poison (HP drain) Corrupted Resonance downside by ~1%.","Lowers the Wither application from the Wither Corrupted Resonance downside by ~2%.","Lower the Wither application from Symbiotic Sustain to 5%","Obtained from: Deepscorn Casque"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('withering-soul', 'Withering Soul', 'Ministry Prophet', 'Common', 'Your Basic Attacks proc 12.5% of their damage as Wither. Wielding the Deepspindle or Umbrite Witherblade will double the amount to 25%.', '["The Wither applied is based off your weapon''s scaled damage.","Obtained from: Darkened Bastion"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('echoing-lunatic', 'Echoing Lunatic', 'Mindbreaker', 'Common', 'Your Ardour Scream now applies a bit of insanity.', '["Removes around 10 sanity (flat value, not %).","The effects of this talent may be negated if the Ardour Scream is blocked, similarly to the roars of Megalodaunts/Primadon."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lose-your-mind', 'Lose Your Mind', 'Mindbreaker', 'Rare', 'Deal more damage the more insane you are. Grants +15% damage at maximum insanity. (+5 Sanity)', '["The damage buff starts at 70% Sanity (Tier 1 Insanity) and scales non-linearly with your sanity until it caps out at +15% damage with 0% Sanity (Tier 3 Insanity).","The specific specific formula is- f(x) = 15 - 15 * (x/0.7)^1.2 {0.7≥x≥0} (x= current sanity / maximum sanity)","ex. 321 sanity w/ 175 current sanity would be a 3.89% increase [https://www.desmos.com/calculator/q9hbw3enrw]","Deepbound''s Sanity gain from killing mobs in the Depths is reduced.","Can also be obtained from the Thrall of Enmity face equipment."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('piercing-will', 'Piercing Will', 'Mindbreaker', 'Rare', 'When your sanity is below 35%, gain up to +15% PEN on your attacks. Starting at 5% PEN, the lower your sanity, the higher your PEN.', '["Grants a 10% PEN bonus at full insanity despite what the description states.","The bonus PEN is applied starting from 35% Sanity.","Scales on your current sanity percentage, similar to Lose Your Mind."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shared-misery', 'Shared Misery', 'Mindbreaker', 'Common', 'Using a Basic Attack/Critical Attack on an enemy while losing sanity causes them to lose sanity. (+5 sanity)', '["Activates when you are actively losing sanity or for 15 seconds after using Heretic''s Sutra.","On proc remove 3% of the targets maximum sanity. This effect has no cooldown.","The amount of sanity damage per hit will scale down if you have less than 85 Willpower."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('charisma-unbounded', 'Charisma Unbounded', 'Mr Charm', 'Mastery', 'You have gained the ability to surpass your limits and train your charisma to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('murmur-ardour', 'Murmur: Ardour', '[[Murmur]]', 'Common', 'An application of your Soul Murmur that enables one to channel the murmur into raw strength. Press input=H.', '["While active your weapon''s swing trail will become purple and your weapon will emit a soft hum sound effect.","If you have Soulbreaker, your weapon will passively emit purple lightning while its unsheathed.","Increases outgoing M1 posture damage by 20% and reduces incoming posture damage by 15%. The posture damage buff also applies to criticals with the M1 tag.","Gain a +2.5% (+5% if Soulbreaker) damage buff to M1s and criticals with the M1 tag. Additionally applies a +15% damage buff to M1s and criticals with the M1 tag that guardbreak.","Drains Ether while active. Ether drain scales inversely with your level, being entirely negated at power 20.","Ardour automatically deactivates if you have no Ether. This also happens upon using Ardour Scream.","Ardour''s activation keybind can be configured in settings."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ardour-scream', 'Ardour Scream', '[[Murmur]]', 'Common', 'Amplify your shout into a scream using Ardour, dominating weaker foes, Victims take 12.5% more damage and 50% more posture damage for 10s. (Tool in your inventory) (+9 Sanity).', '["Activated by utilizing the Ardour Scream tool in your inventory or holding and releasing your Ardour hotkey.","Ardour''s keybind can be configured in settings, changing the key you''ll need to hold in order to activate Ardour Scream (default input=H).","Takes 100% Ether to be used, therefore deactivating Ardour.","Can be used at 40% Ether rather than needing to be at 100% with the Soulbreaker Oath.","Instead of debuffing affected players and making them take 12.5% more damage, it actually applies an on-hit buff when attacking someone affected by Ardour Scream, granting a 25% damage buff to that attack. This means Ardour Scream is affected by the damage modifier cap.","Will also combat tag anybody hit.","Can stack with m1s, crits, Silentheart attacks, and other non-mantra skills."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('murmur-rhythm', 'Murmur: Rhythm', '[[Murmur]]', 'Common', 'An application of your Soul Murmur that enables the user to perceive the subtle murmur emanating from all things. Press input=G while crouched.', '["Rhythm''s activation keybind can be configured in settings.","Pings all nearby Monsters, NPC’s, and Players, through walls while gray-scaling your screen.","Red = Low Health, Yellow = Moderate Health, Grey = Healthy.","Disabled on players with Not a Scratch."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('murmur-tacet', 'Murmur: Tacet', '[[Murmur]]', 'Common', 'An application of your Soul Murmur that enables the user to suppress their own murmur. Press input=T while crouched.', '["Tacet''s activation keybind can be configured in settings.","On use, a sphere around your character will be created. This sphere is commonly referred to as the ''Tacet bubble''. To everyone outside of the bubble, you are invisible.","Tacet bubble size scales inversely on your level and your stealth stat, becoming smaller the higher your level and the more stealth you have.","Being in Tacet grants 400 Stealth, making you effectively invisible to PvE enemies; sometimes even physically touching the NPC directly will not cause them to aggro. However, the unaggro range is still fairly large, even in Tacet, so you may need to run away before reactivating Tacet.","Tacet will be disabled during Hell Mode, Diluvian, and Depths Trials.","After 3 seconds of not crouching, Tacet will deactivate. After 1.5s of sprinting, Tacet will deactivate. Attacking, being hit, or using Soulbreaker''s Formless will instantly deactivate Tacet."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('armor-conserver', 'Armor Conserver', 'Natural Armor', 'Common', 'You lose 15% less armor when hit.', '["Does not affect Natural Armor from Exoskeleton and Chitin."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lightweight', 'Lightweight', 'Natural Armor', 'Common', 'Move faster when your armor runs out of durability. (+3 Passive Agility)', '["When your Armor is at 0% or if you are wearing the Stranded outfit, movement speed is increased by 25%.","This is a mobility buff, NOT a speed boost.","The Bounty Hunter and Corsair Outlaw Outfits and Glassdancer Wraps equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('padded-armor', 'Padded Armor', 'Natural Armor', 'Common', 'While your armor is broken (or if you have no armor), you take 5% less damage. (+3% Blunt Armor)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('steel-scales', 'Steel Scales', 'Natural Armor', 'Common', 'You take an additional 5% less damage when your armor is broken. (+3% Slash Armor)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('captain-etrea', 'Captain Etrea', 'Navaen Nomad', 'Common', 'Fists Moving while blocking with a shield no longer slows you down.', '["Works with Jus Karita.","Despite the Talent description saying \"With a shield\", blocking without a shield equipped will still make the Talent work, thus removing slowdown on blocking completely."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fists-of-fortitude', 'Fists of Fortitude', 'Navaen Nomad', 'Rare', 'Fists Every 6 hits with your fists builds up a shield of endurance reducing incoming damage by 15%.', '["Lasts 10 seconds then goes on a 70 second cooldown once the buff ends.","Only procs on M1s and criticals with the M1 tag.","Wraithclaw''s neutral critical is extremely good for this Talent due to it being a multihit.","Mutual Exclusive: Orbital Ice","If you have the Icebringer''s Vestments Outfit, you can bypass mutual exclusives and stack this with Orbital Ice."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('way-of-navae', 'Way of Navae', 'Navaen Nomad', 'Quest', 'Gain the ability to use fist combat against weapons. Including the ability to block weapons with your hands using Ether.', '["Allows you to use the Way of Navae fist style."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('defensive-stance', 'Defensive Stance:', 'Needle', 'Common', 'Rapier Gain more parry frames the lower your health is.', '["Prerequisitses: Using Rapier, 50 Light Weapon"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('duelists-lunge', 'Duelist''s Lunge', 'Needle', 'Common', 'Rapier Running attacks deal increased posture damage. Upon landing your Critical, your next running attack will have increased range.', '["Running attack with rapiers deal 35% more posture damage.","After landing a Critical, the next rapier running attack has +2 stud range."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('frenzied-dance', 'Frenzied Dance', 'Needle', 'Common', 'Rapier The more posture you currently have, the more chip and posture damage you deal.', '["Frenzied Dance activates when your posture is 70% or higher.","When your posture is 70% or higher, your posture damage is increased by 33%, and chip damage by 20%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pressure-skewer', 'Pressure Skewer', 'Needle', 'Common', 'Rapier Flourishing an enemy causes your M1''s to deal additional chip damage, blood loss and makes your hits deal 3 extra true damage until you take damage.', '["Increase blood bar damage by 50%.","While active, also grants +25% chip damage.","Also applies to criticals with the M1 tag."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fast-blade', 'Fast Blade', 'Nimble Blade', 'Common', 'Extend the speed boost you get from successfully parrying an attack. (+1 Passive Agility)', '["Increases the parry speed boost from 12.5% to 27.5%, and duration from 0.5s to 1.5s.","Parrying without this Talent gives you a 12.5% speed boost, but it''s barely noticeable and lasts for the duration of the parry (0.5s)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lightspeed-reflexes', 'Lightspeed Reflexes', 'Nimble Blade', 'Rare', 'Feinting gives a very brief auto-parry window. (+1 Passive Agility)', '["Grants 0.15s of auto-parry frames."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('speed-emission', 'Speed Emission', 'Nimble Blade', 'Common', 'Gain a slight speed boost after landing a vent.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('all-knowing', 'All Knowing', 'Omniscient', 'Rare', 'Your prediction now ignores the range requirement to reflect attacks.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('intelligence-unbounded', 'Intelligence Unbounded', 'Omniscient', 'Common', 'You have gained the ability to surpass your limits and train your Intelligence to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('successive-prediction', 'Successive Prediction', 'Omniscient', 'Common', 'Predicting an attack will briefly allow you to predict another.', '["Allows you to reflect the entirety of multi-hit moves (such as Enforcer''s spin attack)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('twelve-steps-ahead', 'Twelve Steps Ahead', 'Omniscient', 'Common', 'Landing Prediction will halve the cooldown to a minimum of 2s. Whiffing will double the cooldown to a maximum of 30s. This effect stacks for up to 30 seconds.', '["This effect requires your opponent to be within 90 studs of you.","For every point of Intelligence below 80, Prediction''s maximum cooldown will be increased by 0.125 seconds, capping at 33.125 seconds with 55 Intelligence."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('strength-unbounded', 'Strength Unbounded', 'One Eyed King', 'Common', 'You have gained the ability to surpass your limits and train your Strength to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('absolute-force', 'Absolute Force', 'Operator''s Technique', 'Faction', 'Evolve the technique of your Oppressive Force, letting both hits of your flourish deal 50% more posture damage.', '["Because the second hit of Oppressive Force cannot receive posture damage modifiers, this Talent only benefits the initial hit of your Oppressive Force flourish."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('amp-overdrive', 'Amp Overdrive', 'Operator''s Technique', 'Faction', 'Guardbreaking an opponent causes them to take extra thunder damage and applies Electrify for 7 seconds.', '["Deals 15 Thundercall damage.","The Electrify status effect changes your opponent''s damage type to Thundercall and gives you 10% damage reduction to their attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('martial-brutality', 'Martial Brutality', 'Operator''s Technique', 'Faction', 'The less health your opponent has, the more posture damage you deal to them.', '["Increases your posture damage by 0.1% per 1% health missing, up to a maximum of +10% posture damage against someone at 0% health."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shocking-reverb', 'Shocking Reverb', 'Operator''s Technique', 'Faction', 'Landing enough lightning mantras without getting hit grants you a defensive lightning cloak for 15 seconds, letting you negate damage from light attacks and ironsing.', '["Goes on a 2 minute cooldown on proc.","You need to reach a threshold of 150 scaled damage with Thundercall Mantras without getting hit to proc this Talent.","The damage buildup to reach the threshold is unaffected by resistances and damage modifiers.","Also negates damage from critical attacks and Silentheart abilities."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lock-n-load', 'Lock n Load', 'Outlaw', 'Common', '1H Guns The first bullet in your gun does more damage when fully loaded. This damage buff scales with the number of bullets up to 15%.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rapid-fire', 'Rapid Fire', 'Outlaw', 'Common', '1H Guns When you land a critical shot, gain Rapid Fire for 2s. 12s Cooldown.', '["The Rapid Fire status effect entirely removes your Pistol critical cooldown for its duration, allowing you to spam it.","Procs on dodge, block, and hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rapid-reload', 'Rapid Reload', 'Outlaw', 'Common', '1H Guns You have 20% faster reload when reloading an empty pistol.', '["it takes 0.4 seconds to reload each bullet of an empty gun instead of 0.5 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sleight-of-hands', 'Sleight of Hands', 'Outlaw', 'Common', '1H Guns When you flourish an opponent you instantly load a bullet.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ultrakill', 'Ultrakill', 'Outlaw', 'Common', '1H Guns When under the effects of Rapid Fire you reload 2X as fast.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cult-of-personality', 'Cult of Personality', 'Politician', 'Common', 'You gain +3% PEN for each person Charmed, capping at +15% PEN.', '["The PEN gain per target will be reduced if you do not meet Cult of Personality''s Charisma requirement."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pardon-me', 'Pardon Me', 'Politician', 'Common', 'Crimes you commit in allied territories are often ignored. Who''s asking?', '["Guards from faction which you are at or above neutral reputation will not aggro on you.","Crimes still induce reputation loss however, guards will turn hostile/react to crimes when your reputation becomes negative."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('excavator', 'Excavator', 'Prospector', 'Quest', 'Chance to receive two sets of ore when mining, mine ores a lot faster.', '["The Miner''s Hardhat has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('harvester', 'Harvester', 'Prospector', 'Quest', 'Chance to receive two sets of ingredients when harvesting.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('celebrity', 'Celebrity', 'Public Figure', 'Common', 'Your natural skill in mediating conflict makes people think more highly of you. Your base reputation with factions is higher and your reputation caps out higher.', '["This Talent was merged with the old \"Diplomat\" Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('under-the-radar', 'Under The Radar', 'Public Figure', 'Common', 'The negative reputation threshold for a faction to put out posters of you is now higher. (+1 health)', '["If it is stacked with the \"Celebrity\" Talent you can immediately avoid being hunted by Voidwalkers until you lose one of the two Talents or continue to have a very bad reputation with The Knives of Eylis or some other faction."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('youll-need-to-get-past-me', 'You''ll Need To Get Past Me', 'Public Figure', 'Common', 'When you''re attacked, one of your many allies will leap into action to protect their boss.', '["Spawns in an NPC to attack whoever hits you. The 3 known NPCs are Bandits, Bandit Leaders, or Bounty Hunters.","The cooldown of this Talent scales on your Charisma investment, having a base cooldown of 69.286 seconds and every investment point into Charisma decreasing this by 0.143 seconds.","At requirements, this Talent will have a 58.57 second cooldown, has a maximum cooldown of 62.14 seconds at 50 Charisma, has a minimum cooldown of 55 seconds at 100 Charisma.","The spawned NPC is considered your ally for proccing Talents.","The spawned NPC applies a player combat tag on hit.","Note that an ally appearing with the Talent only works with players and is scaled by the level of the attacking enemy.","An ally is able to appear anywhere on the map and in any locations (aka Luminants, Depths and Dungeons).","The ally will perform just like a normal NPC","You''ll Need to Get Past Me can only proc when hit while outside of combat.","The NPC can drop their weapon on death."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('going-nowhere', 'Going Nowhere', 'Pursuer', 'Rare', 'When enemies dodge your attacks, their momentum is killed and they''re briefly prevented from sprinting. (+6 Passive Agility)', '["When an enemy dodges your attack, halts their momentum and disables their ability to sprint for 1 second."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('volcanic-glass', 'Volcanic Glass', 'Pyroclast', 'Advanced', 'Detonating crystals causes an eruption soon after.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hungry-flames', 'Hungry Flames', 'Pyromancer', 'Common', 'When you have no Ether, consume Stomach and Water to instantly cast your next fire mantra.', '["15 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blood-bag', 'Blood Bag', 'Quack Doctor', 'Common', 'You receive extra blood from knocking an enemy.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blood-transfusion', 'Blood Transfusion', 'Quack Doctor', 'Rare', 'Successfully landing a critical attack while under a negative status effect will transfer the effect plus recover a small portion of your blood bar.', '["20 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('just-a-taste', 'Just a Taste', 'Quack Doctor', 'Common', 'First Bloodrend mantra you hit in combat has increased blood drain.', '["Currently does not work."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('open-wound', 'Open Wound', 'Quack Doctor', 'Common', 'Guardbreaking enemies leaves enemies more susceptible to blood loss from Bloodrend mantras.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('beiruuls-vengeance', 'Beiruul''s Vengeance', 'Quest', 'Quest', 'Deal 5% more damage to factions that despise you. Serves them right.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('kjs-courage', 'Kj''s Courage', 'Quest', 'Quest', 'Gain 10% more Knowledge from all sources, rounded down.', '["This will only impact you if you gain 10 or more Knowledge in one instance."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('nanjis-training', 'Nanji''s Training', 'Quest', 'Quest', 'Nanji shows you a better way to properly block attacks using a weapon, granting you 1 Posture. (+1 Posture)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('supernatural-sense', 'Supernatural Sense', 'Quest', 'Quest', 'After dealing with real actual literal ghosts, you feel emboldened. (+10 Sanity)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bulldozer', 'Bulldozer', 'Raging Bull', 'Rare', 'Enemies you flourish into a wall have a chance of breaking the wall and are guard broken on impact.', '["This has a 50% chance to break destructible objects when you flourish people into them.","Mutual Exclusives: Dazing Finisher"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('broken-ankles', 'Broken Ankles', 'Raging Bull', 'Common', 'Blockbreaking an opponent puts their Mobility slot Mantras on CD for 12s.', '["30 second cooldown.","Broken Ankles'' duration will be reduced by 0.15 seconds for every point in Strength below 70, capping at 8.25 seconds with 45 Strength."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('piercing-blow', 'Piercing Blow', 'Raging Bull', 'Advanced', 'Attacks that break an opponent''s block ignore their Armor resistances.', '["If you do not have 100 Strength, this Talent will instead halve your opponent''s armor resistances multiplicatively, before PEN on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shield-breaker', 'Shield Breaker', 'Rampaging Brute', 'Common', 'Blunt damage now fully ignores the posture bonus from shields. (+1 Posture)', '["Bypass the increased posture from your enemies shield. Effectively, your enemy is stripped from their shield."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unwavering-resolve', 'Unwavering Resolve', 'Rampaging Brute', 'Common', 'Getting parried punishes your posture 33% less. (+2 Posture)', '["The posture reduction effect is reduced by 0.433% for every point in Strength below 40, having a minimum value of 22.166% posture reduction from being parried at 15 Strength.","The Adjudicator''s Coat equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('million-ton-piercer', 'Million Ton Piercer', 'Rampaging Brute', 'Advanced', 'Gain 5% extra PEN and remove the cap on your PEN. Go beyond your limits.', '["The additional 5% PEN scales with your Strength, only granting the full +5% PEN at 90 Strength.","Like Ether Overdrive, this removes the 50% Mantra and Weapon PEN cap.","Mutual Exclusive: Ether Overdrive"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('jolting-current', 'Jolting Current', 'Rampant Static', 'Common', 'Your lightning attacks in water strike others near them with lightning.', '["While you and your opponent are in the water, landing any attack that would apply Shock or a Surge Rod will strike other waterborne targets in a 20 stud AoE from the initial target, dealing 50% of the attack''s damage and applying Shock or a Surge Rod."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rending-needle-augmenter', 'Rending Needle: Augmenter', 'Rending Needle', 'Rare', 'If an enemy has 5 or more rods, your Ironsing Pull will use their rods to form a powerful sword to attack with. This also makes your Metal Armament stronger while the weapon is equipped.', '["Equips the Metal Greatsword weapon on proc.","Having Metal Greatsword equipped increases your Metal Armament damage by 50%.","Metal Greatsword lasts 10 seconds before reverting to your original weapon.","Maximum amount of Iron Rods you can apply to a single target is 5.","Mutual Exclusives: Rending Needle: Conductor, Rending Needle: Impaler, Rending Needle: Jailer, Gilded Path: Scrapsinger"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rending-needle-conductor', 'Rending Needle: Conductor', 'Rending Needle', 'Rare', '5 metal rods will combine into a conductor rod. If an enemy uses a non-Ironsing elemental mantra, they''re dealt with their element back in return.', '["Works as default path with exception of applying a Conductor rod after 5 normal metal rods are applied.","Conductor rods last 30 seconds or until an elemental mantra is used.","On proc, the Conductor Rod will apply the elemental effect of the Mantra your opponent is trying to use to themselves.","If your opponent uses a Mantra while being affected by a Conductor rod, 5% of their current armor durability will be drained and it proc have the following effect:","Flamecharm Mantra: Apply Burn (base path) / No effect with Eruption path, rod falls off.","Frostdraw Mantra: Deals a very low amount of damage (Base path) / Apply Crystal on victim (Crystallization path)","Galebreathe Mantra: Suffocate + Cancels mantra (Base path) / Spawn Apparition (Specter Path)","Shadowcast Mantra: Doubles the Ether cost of the Mantra cast","Thundercall Mantra: Applies Shock + Cancels mantra (Base path) / Applies Surge stack (Surge path)","Attunement-less/Ironsing/Bloodrend/Oath Mantra: The rod does not fall off, but their armor is still drained till conductor rod expires.","You can''t pull out Conductor rods, nor can they be consumed with Scrapsinger.","Conductor''s rod on proc doesn''t apply pull immunity.","Mutual Exclusives: Rending Needle: Augmenter, Rending Needle: Impaler, Rending Needle: Jailer"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('conductors-cable', 'Conductor''s Cable', 'Rending Needle', 'Common', 'Applying Conductor rods on opponents steals some of their armor to you.', '["Steals 10% of your enemy''s maximum armor durability on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rending-needle-impaler', 'Rending Needle: Impaler', 'Rending Needle', 'Rare', 'If an enemy is affected by 5 or more metal rods, your Ironsing Pull instead pulls out all of the rods for massive damage.', '["Increases the maximum amount of iron rods you can apply to a single target from 5 to 10.","Has a base damage of 4 physical damage per rod, with 5 Ironsing scaling.","Formula: 4 + Ironsing investment * 0.02","Deals 5.5 physical damage per rod at 75 Ironsing.","Affected by most damage modifiers.","Innately has 0% PEN.","Has 6.5x PvE multiplier.","Mutual Exclusives: Rending Needle: Augmenter, Rending Needle: Conductor, Rending Needle: Jailer"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rending-needle-jailer', 'Rending Needle: Jailer', 'Rending Needle', 'Rare', 'If an enemy has 5 or more rods, your Ironsing Pull will restrain them instead of pulling them.', '["Increases the maximum amount of iron rods you can apply to a single target from 5 to 10.","When affected by Jailer, the victim will be unable to do anything except Vent.","The victim is given 30% damage reduction when Jailed.","When Jailed, the victim will have a 6 second rod and pull immunity. When Jailer expires, their rod pull immunity will be automatically reduced down to 1 second.","Jailer''s duration scales on the amount of rods applied, having a 1.08s duration at 5 rods, and gaining 0.104 seconds per rod after 5. This caps at a 1.6s duration with 10 rods.","Mutual Exclusives: Rending Needle: Augmenter, Rending Needle: Impaler, Rending Needle: Conductor"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('family-recipe', 'Family Recipe', 'Saboteur', 'Quest', 'You can now craft bombs at a crafting bench.', '["Iron Bombs are crafted with 2 Iron and 1 Coal at any crafting bench.","Bombs have a base damage of 10, scaling on Intelligence. At 100 Intelligence, they deal 45.5 damage.","Bombs deal typeless damage, ignoring armor resistances.","Press input=E while holding a bomb to throw it. Press input=M1 while holding a bomb to drop it at your feet.","Bombs do not deal self damage.","Bombs have a 5 second cooldown on throw.","It is highly recommended that you use the Miner''s Hardhat when farming for the crafting materials, as it doubles your mining output with a chance to quadruple it."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('incendiary-formula', 'Incendiary Formula', 'Saboteur', 'Common', 'Bombs will set your enemies on fire upon detonation, as well as launch with more force. Bombs will deal 20% increased damage to burning enemies.', '["Bombs apply burn on hit. This burn, like all other burn scales on your Flamecharm investment and can be improved through the usage of Flamecharm Talents.","Your bombs go further when thrown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sulphur-surprise', 'Sulphur Surprise', 'Saboteur', 'Common', 'Your cooldown for throwing bombs will be shortened after your first bomb damages an enemy.', '["Reduces the bomb throw cooldown from 5 seconds to 4 seconds. This only applies to the bomb thrown directly after this Talent procs, not on the bomb that procced this Talent.","20 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hot-potato', 'Hot Potato', 'Saboteur', 'Common', 'Gain a large boost of speed after throwing a bomb. Your bombs have a chance to detonate twice. (+6 Passive Agility)', '["This speed boost lasts 2 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('explosive-efficiency', 'Explosive Efficiency', 'Saboteur', 'Common', 'Crafting a bomb will yield two bombs. Chance to make three.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pocket-bombs', 'Pocket Bombs', 'Saboteur', 'Common', 'You have a chance to activate a bomb in your inventory when damaged. (+1 Health, +5 Carry Load)', '["On proc, this consumes 1 Iron Bomb to drop 2 bombs at your feet.","Has a 1 second cooldown that will activate upon taking damage, even if the Talent does not proc and even if you do not have Iron Bombs in your inventory."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chorus-of-souls', 'Chorus of Souls', 'Sage of Wisps', 'Advanced', 'Alone, the Wisps lack a voice. But surrounded by so many, the frequencies overlap and you hear it true. (+1 Wisp Mantra Slot)', '["Grants heavily increased health regeneration if you have all Wisps active.","This will not proc unless you have every Wisp Mantra equipped and active. If one of your Wisps runs out, this Talent will deactivate until you recast the Wisp.","This Talent will not work if you do not have the Oathless Oath."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('will-o-wisp', 'Will o'' Wisp', 'Sage of Wisps', 'Advanced', 'Your mastery over the Wisps of the Song enables you to mediate the innate conflicts between your wisps, allowing any number of Wisps to be active at a time. (+1 Wisp Mantra slot)', '["Allows the player to summon one of each Wisp at the same time."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('wisp-convergence', 'Wisp Convergence', 'Sage of Wisps', 'Rare', 'When empowered by the Chorus, your Wisps now grant their elements to your strikes.', '["This will not proc unless you have every Wisp Mantra equipped and active. If one of your Wisps runs out, this Talent will deactivate until you recast the Wisp.","Your basic attacks will apply Burn, Shock, Chill, Winded, Shadow, Metal Rods, and Blood Poison all at once.","This Talent will not work if you do not have the Oathless Oath."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heavy-weapons-unbounded', 'Heavy Weapons Unbounded', 'Saint of Blades', 'Mastery', 'You have gained the ability to surpass your limits and train your Heavy Weapons attribute to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('light-weapons-unbounded', 'Light Weapons Unbounded', 'Saint of Blades', 'Mastery', 'You have gained the ability to surpass your limits and train your Light Weapons attribute to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('medium-weapons-unbounded', 'Medium Weapons Unbounded', 'Saint of Blades', 'Mastery', 'You have gained the ability to surpass your limits and train your Medium Weapons attribute to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ether-proselyte', 'Ether Proselyte', 'Saintsworn', 'Oath', 'All of your Elemental Mantras below Lv. 5 are now 1 level higher. Your Mantras are now converted to the element of your current stance.', '["Increases the level of all Attuned Mantras by 1 unless they are already level 5.","Allows your Attuned Mantras to proc the Attunement Talents of your current Saint Stance. (E.g. Clutching Shadow in the Flamecharm Stance can proc Scorched Peak, creating a lightning strike if you guard break with this Mantra.)","Not all Attuned Talents are eligible to proc Ether Proselyte. More info as to what does and doesn''t work is on the Saintsworn page."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heros-assist', 'Hero''s Assist', 'Saintsworn', 'Oath', 'Heroes come to your aid based on your current stance.', '["Hero''s Assist summons the past heroes of the attunements themselves to aid you in battle. You can spawn heroes independent of your current Saint Stance.","This passive ability works once per Saint Stance, requiring you to cycle to the next one to reactivate.","Flamecharm: Upon flourishing an enemy, set down 3 deadly eruptions in the direction of the flourish, each of which innately proc the talent The Floor is Lava.","Galebreathe: Upon uppercutting, block-breaking an enemy with a mantra, or taking damage while casting a mantra (can be from any source), shoot a miniscule version of the Galebreathe mantra Tornado at the enemy, while also suffocating and knocking them away.","Shadowcast: Upon parrying an attack, summon the Hero of Shadow to do minor damage in an AoE, proccing the talent Sightless Still on anyone hit.","Frostdraw: Upon landing a Frostdraw Mantra, any attuned Mantra while in the Frostdraw Saint Stance, or the Frostdraw-specific Blade of Saints version, summon a stationary turret that fires ice projectiles in a straight line. Applies chill/crystals on hit.","Thundercall: Upon casting a mantra for the first time, your mantra cast will have much higher windup and damage.","The damage buff is currently bugged and does not work, meaning this does nothing but nerf your mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('saints-negation', 'Saint''s Negation', 'Saintsworn', 'Oath', 'Once per stance cycle you can fully block an attack that matches your Saint Stance.', '["Allows you to fully negate the damage of one attack that has a damage type that corresponds with your current Saint Stance.","Can only proc once per full cycle, meaning you''ll have to fully cycle through all of the Stances before you can proc it again."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('saints-overload', 'Saint''s Overload', 'Saintsworn', 'Oath', 'After a full rotation of stances your elemental scaling is increased by 15% and Mantra Modifiers increased by 10%.', '["Increases your Attunement investment scaling by 15% and the effects of your Mantra modifiers by 10% for a few seconds after preforming a full rotation of Saint stances. You''ll need to fully cycle through all of the Stances before you can proc this effect again.","Acts similarly to Songchant in the sense that it increases the effectiveness of your investment.","Turns your Saintsblade and the Saintsworn Oath cosmetic (the swords on your back) white on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('saints-synergy', 'Saint''s Synergy', 'Saintsworn', 'Oath', '15% of your highest element scaling is applied to other elemental damage.', '["15% of the investment scaling from your highest Attuned stat is added to your other Attuned Mantras, granting them slight dual scaling."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('perpetual-distillery', 'Perpetual Distillery', 'Saltchemist', 'Oath', 'Your very body has become a distillery for your alchemy. Gain 3 Autobrew slots that will automatically produce 3 concoctions of your choice.', '["Upon clicking the Distillery Talent, you''re given three empty spaces where you input your potions. You''re able to switch the mode from \"Throw\" to \"Drink\", and vice versa. Upon clicking on a key you''ll automatically drink or throw the potion in that slot. Some potions are unable to be slotted.","The potions within the Distillery are infinite, and are used within their directed cooldowns. This allows builds to be able to use up to three individual potions without the lackluster windup and cooldown in the throwing and drinking process.","Drink potions place other drink slots on a cooldown if they share buffs.","When replacing a potion in the Distillery, the one that was previously there is voided. Potions cannot be recovered once placed in the Distillery.","Potions in the distillery will scale their potency to the Salchemist''s current Intelligence investment, even if they were made with higher/lower Intelligence.","Upon casting Lethal Injection, all potions in your Distillery will be used at once unless they''re on cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('antithetic-salts', 'Antithetic Salts', 'Saltchemist', 'Oath', 'Alter your brews to invert their effects. Does not count towards the ingredient limit.', '["Gives you a Talent tool-like ability that acts as a potion ingredient on use.","When applied to your potions, it inverts the effects of the ingredients in the potion. For example, 3 Urchins and 2 Goblettos would restore sanity, lower health regen, and slightly increase speed.","The name of the potion will change to fit its new effect. The color can change, but this is inconsistent.","Oath Skipping Saltchemist is generally not recommended due to how easy it is to get the materials needed for the craft."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('aromatic-salts', 'Aromatic Salts', 'Saltchemist', 'Oath', 'Alter your brews to create lingering clouds of mist on shattering. Does not count towards the ingredient limit.', '["Gives you a Talent tool-like ability that acts as a potion ingredient on use.","Each \"hit\" of the mist count as a potion application, triggering the enhanced potion effects from Chain Reaction.","Lasts for roughly 10 seconds.","Ingredients that alter a potion''s duration such as Redds and Spider Eggs do not affect the lingering clouds.","Oath Skipping Saltchemist is generally not recommended due to how easy it is to get the materials needed for the craft."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('biotic-salts', 'Biotic Salts', 'Saltchemist', 'Oath', 'Alter your brews to not provide their positive effects to your enemies. Does not count towards the ingredient limit.', '["Gives you a Talent tool-like ability that acts as a potion ingredient on use.","Biotic Salts half negative effects of potions for allies, and positive effects for enemies.","This should be used in every potion possible, as it has no downsides whatsoever.","Due to how potions work, even your negative potions may have some positive effects and vice versa; this Talent is very good for diminishing those unwanted effects to basically nothing without any downsides.","Biotic Salts count yourself as an ally.","Oath Skipping Saltchemist is generally not recommended due to how easy it is to get the materials needed for the craft."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('enhanced-flow', 'Enhanced Flow', 'Sanguine Wager', 'Common', 'Refine your Rush Hour, allowing you to now also gain temp health whenever you hit a player while using Rush Hour. You now also take less damage from Rush Hour.', '["When you land basic attacks during Rush Hour, gain Temporary Health equal to 30% of your weapon''s scaled damage.","This cannot give more than 50 Temporary Health in one instance.","This reduces Rush Hour''s self damage by 22%, from 4.5 damage per tick to 3.5 damage per tick.","Despite what the description states, this Talent still procs when hitting monsters or other non-player enemies."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('torture-mastery', 'Torture Mastery', 'Sanguine Wager', 'Common', 'Landing a critical on opponents applies 15 seconds of Torture Mastery. Heal any chip damage off players who have Torture Mastery on them. This duration is doubled if you have Rush Hour on.', '["On proc, all chip damage you deal will be converted into healing.","The conversion of chip damage to healing is 1:1."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dark-receiver', 'Dark Receiver', 'Sapper', 'Common', 'Shadow moves will also steal Ether from those you are Static Linked tethered to.', '["Deal 4.5x Ether steal against linked targets. Additionally, drain Ether from all linked targets equally when landing Shadowcast moves."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blood-bank', 'Blood Bank', 'Scarlet Donor', 'Common', 'Consuming ''Charm'' now gives slight temporary health.', '["Procs when you proc Donation Drive or Manipulator.","Grants 25 flat temporary health.","Has an indirect 10 second cooldown due to it relying on Manipulator."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('donation-drive', 'Donation Drive', 'Scarlet Donor', 'Common', 'Consuming ''Charm'' on an opponent replenishes some blood. Additionally, you can also activate this effect and Manipulator through blockbreaking with a Bloodrend mantra.', '["Donation Drive''s cooldown scales on your Charisma investment, having an 8 second cooldown at 60 Charisma and gaining 0.1s for every point in Charisma below 60.","Donation Drive has a 8.5 second cooldown at 55 Charisma, and a maximum cooldown of 10.5 seconds at 35 Charisma."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sharing-is-caring', 'Sharing is Caring', 'Scarlet Donor', 'Common', 'Your ''Charm'' on opponents also slightly increases your blood drain against them.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('windwaker', 'Windwaker', 'Scholar of the Cloud', 'Quest', 'Call upon a gust of wind to propel your boat even faster.', '["The ability can be used as long as the player is standing on a boat, even if not in control.","Сannot be used in combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dirty-boxing', 'Dirty Boxing', 'Scoundrel', 'Rare', 'Fist Enemies hit after you feint them with your fist suffer slight bleed and have their vision obscured slightly and makes PvE enemies Sluggish. (+1 Passive Agility)', '["8 second cooldown.","This Talent also works with Jus Karita."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pocket-sand', 'Pocket Sand', 'Scoundrel', 'Common', 'Fist Feinting into an uppercut blinds, applies Stagger to PvE enemies and also applies Dazed briefly. We''re even now, right?', '["30 second cooldown.","Procs through Block/Parry/Dodge, and applies to all uppercut mantras (ex: Rising Flame).","The Stagger status effect makes your opponent take 33% more posture damage.","This Talent does not work with Jus Karita."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gilded-path-scrapsinger', 'Gilded Path: Scrapsinger', 'Scrapsinger', 'Common', 'Flourishing an enemy consumes any rods they have and siphons their armor to you per rod.', '["Your Ironsing Mantras/abilities, Ironsing legendary weapons, and Metal Rods are now yellow.","Mutual Exclusive: Rending Needle: Augmenter"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('artisans-blade', 'Artisan''s Blade', 'Scrapsinger', 'Common', 'Activating Scrapsinger forges a metal blade behind you for every 2 rods you consume. Metal blades will fire at a target upon landing an ironsing or metal infused attack.', '["Each Artisan Blade has 8 Base damage with 5 Ironsing scaling; simplified formula as follows: 8 + 0.04 * Ironsing investment. They deal 4.5 posture damage each if blocked. Their damage cannot be modified.","Has 6.47x PVE scale (10 DMG PVP, 64.70 PVE DMG).","Artisan''s blade have windup of 1.2s.","Parrying Artisan''s blade gives brief Auto Parry frames.","Pulling rods normally also procs this Talent.","Artisan Blades have an individual 20 second duration.","\"Metal infused\" attacks are Ignition Deepcrusher M1s and critical attack, Iron Requiem unloaded M1s and critical attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('masterwork', 'Masterwork', 'Scrapsinger', 'Rare', 'Successful hits from Artisan''s Blades will proc metal rods and deal 50% more damage.', '["Increases Artisan''s Blades damage by 1.5x, additionally Artisan''s Blades will apply 1 rod per each hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('refine-and-reuse', 'Refine and Reuse', 'Scrapsinger', 'Common', 'Consuming rods with Scrapsinger reduces incoming PEN against you for 14 seconds. Each rod reduces PEN by 5% multiplicatively.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('songs-unforged', 'Songs Unforged', 'Scrapsinger', 'Common', 'Your weapon criticals will now activate scrapsinger.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reshape-and-remold', 'Reshape and Remold', 'Scrapsinger', 'Advanced', 'Successful procs of Scrapsinger will increase the amount of armor damage your opponent takes. After hitting 10 stacks, the opponent will take +5% damage until the stacks drop below 10.', '["Increases the armor drain effect of your rods by 25%, from 2% drain to 2.5%.","The effectiveness of the increased armor drain scales down if you have less than 70 Ironsing.","5% DMG bonus is currently bugged. (Since Summer 2023)","Your Scrapsinger proc vfx is changed after obtaining this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gruesome-harvest', 'Gruesome Harvest', 'Septicemia', 'Advanced', 'Landing Bloodrend mantras on opponents with over 70% blood poison will give you slight temporary health.', '["Grants 15 flat temporary health on proc.","Has a 2 second cooldown between procs."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hemolysis', 'Hemolysis', 'Septicemia', 'Common', 'Deal 20% more critical attack damage to opponents with over 25% blood poisoning.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hemolytic-transfusion', 'Hemolytic Transfusion', 'Septicemia', 'Common', 'Guardbreaking an enemy with a Bloodrend mantra increases the amount of blood poison from the attack.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('juicy-snack', 'Juicy Snack', 'Septicemia', 'Common', 'Eliminating enemies returns their amount of blood poison as health to you.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('panacea', 'Panacea', 'Septicemia', 'Rare', 'Hitting an enemy with a Bloodrend mantra stops their blood poison from decaying for 7 seconds.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tainted-ground', 'Tainted Ground', 'Septicemia', 'Common', 'Enemies who stand in blood pools do not decay blood poison and gain 15% more blood poisoning.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('vasculitis', 'Vasculitis', 'Septicemia', 'Common', 'Hitting your opponent while they have over 20% blood poisoning disables their deep gems for a brief duration while giving you Gem Enhancement against PvE temporarily.', '["On proc, your opponent will be unable to use their Deep Gems for 8 seconds.","Gem Enhancement increases the effectiveness of your Deep Gems in PvE."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shadowcast-unbounded', 'Shadowcast Unbounded', 'Shadowcast Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Shadowcast to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shadowcaster', 'Shadowcaster', 'Shadowcaster', 'Mantra Level', 'Grants you the ability to command shadows as a Shadowcaster.', '["Obtained at 1 Shadowcast"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-shadowcaster', 'Adept Shadowcaster', 'Shadowcaster', 'Mantra Level', 'You can now obtain 1-star Leveled Shadowcaster Mantras.', '["Obtained at 20 Shadowcast"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-shadowcaster', 'Expert Shadowcaster', 'Shadowcaster', 'Mantra Level', 'You can now obtain 2-star Leveled Shadowcaster Mantras.', '["Obtained at 30 Shadowcast"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-shadowcaster', 'Master Shadowcaster', 'Shadowcaster', 'Mantra Level', 'You can now obtain 3-star Leveled Shadowcaster Mantras. (+5 Health)', '["Obtained at 50 Shadowcast"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blossoming-darkness', 'Blossoming Darkness', 'Shadowcaster', 'Common', 'The more Ether you drain during Shadow Roar, the bigger it gets.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fear-the-dark', 'Fear the Dark', 'Shadowcaster', 'Common', 'Enemies will briefly hang in place when they run from you.', '["After you land a Shadowcast Mantra, if your opponent attempts to distance themselves from you, they will be locked in place for 1.5 seconds.","This does not apply hitstun."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lasting-sorrow', 'Lasting Sorrow', 'Shadowcaster', 'Common', 'Shadows last longer on your opponent.', '["Doubles the shadow effect duration."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shadow-travel', 'Shadow Travel', 'Shadowcaster', 'Rare', 'Teleport to a location in exchange for Ether cost. Certain ranges will require a health sacrifice. Be careful as this technique can prove lethal to the user.', '["Deals 0.25 self damage damage per stud teleported. This can kill you if you don''t have enough health to survive the teleport.","If your teleport distance is less than 300 studs, you will not take self damage.","Drains 100 Ether on use, with each stud travelled increasing this Ether cost by 0.2.","The maximum distance you can travel is based on your Ether. Subtract your Ether by 100 and multiply the result by 5 to get the maximum amount of studs you can travel.","Studs teleported calculations are directly based on your starting position (where you casted Shadow Travel) and your end position, meaning that height and length aren''t calculated separately.","The Already Dead Talent from the Deepscorn Casque halves the self damage taken from Shadow Travel.","Can teleport users to the roof of the depths, and wipe them due to fall damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sightless-still', 'Sightless Still', 'Shadowcaster', 'Common', 'The more a person is affected by your Shadowcast the more you obscure their vision. Block breaking an opponent obscures their vision even more and applies Ether Sunder to PvE', '["The Ether Sunder status effect grants you 30% damage reduction against affected enemies'' elemental attacks.","This Talent was merged with the old Black Out Talent.","Mutual Exclusive: Singularity"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('singularity', 'Singularity', 'Shadowcaster', 'Common', 'Enemies will briefly hang in place when hit by a shadow move. Also procs Shaky Block.', '["Mutual Exclusive: Sightless Still"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('knights-rally', 'Knight''s Rally', 'Shieldmaster', 'Common', 'When using a shield, you ready your block more quickly after taking a hit. (+4 Sanity)', '["When holding out a shield (One-Handed Stance), being hit will inflict 5% less \"shaky block\", allowing the user to escape certain combos easier with their block."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('turtle-shell', 'Turtle Shell', 'Shieldmaster', 'Common', 'If your shield is on your back, take reduced backstab damage and negate Spine Cutter.', '["Grants 25% damage reduction to attacks from the back.","Currently does not work.","Turtle Shell is pretty inconsistent, as some attacks will bypass it entirely and deal their full damage. Ex: Sightless Beam and Radiant Dawn.","Each time this Talent takes effect, white square particles will release from around the user.","This shares a visual effect with the Arcwarder \"Arc Suit\" mantra."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grounding-bolt', 'Grounding Bolt', 'Shock Therapy', 'Common', 'Anytime you summon a lightning strike on your opponent, apply knockdown if it lands.', '["10 second cooldown.","Storm Strikes from the Specialist Set Talents, Storm/Stormbreaker Enchants during the rain, Scorched Peak, Fulgurite Formation''s lightning strikes all proc this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unnecessary-theatrics', 'Unnecessary Theatrics', 'Showboater', 'Common', 'Deliver a one-liner on uppercuts, flourishes and critical attacks that charms your opponents briefly.', '["Charms for 7 seconds.","The Charm duration is reduced by 0.066 seconds per point of Charisma under 75, capping at 5.3 seconds at 50 Charisma.","Does not proc \"Golden Tongue\" Talent.","The cooldown indicator says that this Talent has a 10s CD, which is technically incorrect. There is no CD for the Charm application, but there is a 10s CD on the one-liners."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('silencers-blade', 'Silencer''s Blade', 'Silencer', 'Rare', 'Meleeing a ''Suffocated'' opponent will extend the duration of the Suffocation and grant a speed boost.', '["Landing M1 attacks or criticals with the M1 tag on suffocated targets applies a new stack of suffocation that lasts 5 seconds.","Grants an ~22.5% speed boost for 3 seconds.","bleed damage can proc this effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('a-world-without-song', 'A World Without Song', 'Silencer', 'Advanced', 'Every 3 hits with a Wind Mantra now procs Suffocating.', '["Requires 4 hits to proc if you have less than 75 Galebreathe.","Requires 5 hits to proc if you have less than 40 Galebreathe.","Suffocation prevents the victim from casting Mantras and deals a small amount of damage over time."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ankle-cutter', 'Ankle Cutter', 'Silentheart', 'Oath', 'You can now do a special ground slash while sliding, applying a temporary speed debuff to those hit, as well as preventing jumping.', '["Deals fixed damage with innate bleed.","Attack speed scales on your weapon''s swingspeed stat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dread-fighter', 'Dread Fighter', 'Silentheart', 'Oath', 'Parrying and getting hit by mantras now give you stacks of Dread. Each stack increases your mantra resistance, up to 25%. Each stack lasts for 15 seconds.', '["Stacks of dread are represented as a halo that grows from your chest. Each stack makes the halo larger and adds 5% Mantra resistance. Stacks up to 5 times for 25% Mantra resistance."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flow-state', 'Flow State', 'Silentheart', 'Oath', 'Enter a moment of extreme focus in which you can change the windup of your special attacks with the correct timing.', '["Grants a Talent tool that when used just before using a Silentheart move, it will modify the base behavior of the move.","Increases the damage of most Silentheart moves.","Mayhem variants autogrip when buffed with Flow State.","Often lowers the windup of your Silentheart abilities.","Active for 2 seconds. 15s CD, landing a Flow State-enhanced Silentheart ability refreshes Flow State''s cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mayhem', 'Mayhem', 'Silentheart', 'Oath', 'Initiate a special dash attack by pressing input=M1 during the start of your dodge.', '["Movesets and damage differ depending on the weapon type; Light, Medium, or Heavy.","11s CD per weapon type, meaning if you swap weapon types you can use multiple different versions of Rising Star back to back.","Capable of auto-gripping with Flow State active.","Can proc your weapon''s Enchantment, putting Silentheart Enchant procs on cooldown for 30 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('merciless-blade', 'Merciless Blade', 'Silentheart', 'Oath', 'You can now execute enemies much faster.', '["Grip speed is increased by 25% (3 seconds down to 2.25 seconds)."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('relentless-hunt', 'Relentless Hunt', 'Silentheart', 'Oath', 'M1 while doing an Aerial Attack to initiate a special gap closer attack.', '["Movesets differ depending on the weapon type; Light, Medium, or Heavy.","11s CD per weapon type, meaning if you swap weapon types you can use multiple different versions of Rising Star back to back.","Has faster windup with Flow State active. Useful for mixups.","Movesets and damage differ depending on weapon type; Light, Medium, or Heavy.","Can proc your weapon''s Enchantment, putting Silentheart Enchant procs on cooldown for 30 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rising-star', 'Rising Star', 'Silentheart', 'Oath', 'Press input=CTRL + input=M2 to activate a special uppercut attack.', '["Instead of being binded to M2, it''s actually binded to your feint key. Meaning if you''ve changed your Feint keybind off M2, M2 will no longer proc Rising Star.","Procs all \"on uppercut\" Talents.","Movesets and damage differ depending on the weapon type; Light, Medium, or Heavy.","Can proc your weapon''s Enchantment, putting Silentheart Enchant procs on cooldown for 30 seconds.","12s CD per weapon type, meaning if you swap weapon types you can use multiple different versions of Rising Star back to back."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('silent-cascade', 'Silent Cascade', 'Silentheart', 'Oath', 'Landing physical attacks on an opponent charges up your Silent Cascade, a devastating barrage that can be released with CTRL + M2.', '["Landing 8 weapon attacks or Silentheart abilities will grant the Silent Cascade status effect for 30 seconds.","Your next uppercut while you have the Silent Cascade status effect will perform the Silent Cascade attack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('true-vantage', 'True Vantage', 'Silentheart', 'Oath', 'Successfully landing a Vent briefly gives you invisibility, along with giving a speed boost.', '["Changes your Vent color to align with your Oath Cosmetic color. Can be dyed."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unmatched-dexterity', 'Unmatched Dexterity', 'Silentheart', 'Oath', 'Press input=X to Quick Swap between weapons within your toolbar.', '["This keybind can be changed in settings.","Selects a random weapon on your hotbar to equip.","Works on offhand weapons.","This Talent passively allows Silenthearts to manually swap equipment and weapons while in danger as well.","Notably, the Curse of the No Life King and Curse of Void curse effects of always having a stained healthbar have their durations extended for 60 seconds upon taking damage. This means you cannot avoid being sent to The Depths by swapping swapping to a non-cursed weapon just before being knocked Unconscious."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('vengeful-pursuit', 'Vengeful Pursuit', 'Silentheart', 'Oath', 'Your running attacks that don''t hit send out a special mid-range crescent projectile that slows on hit. Tracks onto those with their backs turned to you. 8s CD', '["Base damage and scaling depend on your current weapon''s type; Light, Medium, or Heavy."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('friends-in-high-places', 'Friends in High Places', 'Silvertongue', 'Common', 'Your connections often let you off the hook when you''re in trouble with the law. Nepotism sure does pay!', '["Whenever you are knocked by town guards from a faction in which you have good reputation, the town guards will scold you instead of gripping you, letting you live.","Angering a faction by attacking a player ally of their own will prevent guards from aggroing on you."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('golden-tongue', 'Golden Tongue', 'Silvertongue', 'Rare', 'Typing or using a gesture gives a random buff to you and those around you. (60 second cooldown)', '["Sending a message in chat or using an emote will proc this Talent.","Can either restore 30% of max ether or grant 10% damage reduction for 30 seconds, similar to reinforce (does not stack).","The buff is random for each person affected.","For every point in Charisma above 40, the cooldown will be decreased by 0.25 seconds, having a 45 second cooldown at 100 Charisma.","For every point in Charisma below 40, the cooldown will be increased by 0.25 seconds, having a 1 minute 6.25 second cooldown at 15 Charisma."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('snake-oil', 'Snake Oil', 'Silvertongue', 'Common', 'Okay, the amount you''re charging people for your items is getting downright criminal. But I''m just a Talent description, I can''t stop you.', '["Gain 40% more notes from selling items."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('absolute-pitch', 'Absolute Pitch', 'Songmaster', 'Advanced', 'You can cast Ritual Mantras instantly.', '["Removes the ritual cast on all ritual cast Mantras.","If you have less than 100 Intelligence, the number of ritual keys will be halved instead, rounding up if necessary."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ether-overdrive', 'Ether Overdrive', 'Songmaster', 'Advanced', 'Gain 5% extra PEN and remove the cap on your PEN. Go beyond your limits.', '["The additional 5% PEN scales with your Intelligence, only granting the full +5% PEN at 90 Intelligence.","Like Million Ton Piercer, this removes the 50% Mantra and Weapon PEN cap.","Mutual Exclusive: Million Ton Piercer"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bloodiron-spirit', 'Bloodiron Spirit', 'Soul Converter', 'Rare', 'You regain some Armor upon killing enemies. (+5 Health)', '["Any kill gives you 2.5% of your total armor durability.","Stacks with Bloodiron Ring, totalling in 5% armor per kill."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('soul-infusion', 'Soul Infusion', 'Soulbreaker', 'Oath', 'Infuse Ardour into your executions. If your execute is interrupted, the opponent remains down for a longer amount of time. Your Ardour Screams are projected further.', '["Reduces Ardour Scream''s minimum Ether to cast from 100% ether to 40%. It will still drain all of your Ether however.","You automatically use Ardour Scream for free upon finishing an execution.","Grants a unique visual and sound effect to your Ardour Scream and massively increases its range.","Purple lightning particles are left on knocked players after the secondary effect of this Talent procs.","You perform grips much faster and have a unique grip animation. The grip animation approximately takes 1.8 seconds to complete, which is even faster than using Reaper."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('formless', 'Formless', 'Soulbreaker', 'Oath', 'Teleport to a location within your Tacet bubble. Receive a slight speed boost when activating Tacet.', '["Grants a Talent tool that activates Formless on cast. After an animation and a fairly long delay, you will teleport to your cursor''s location. Cannot teleport yourself outside of the range of your Tacet bubble.","Formless can only be used during Tacet, and will end your Tacet upon successful teleport.","Formless costs 50 Ether and has a 5 second cooldown.","Because Formless'' maximum teleportation distance is determined by the size of your Tacet bubble, having low or even negative stealth is a viable option.","The speed boost granted upon activating Tacet lasts 2.5 seconds and is retained upon exiting Tacet.","Outside of Tacet''s innate cooldown, the speed boost for activating it has no cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heart-reverb', 'Heart Reverb', 'Soulbreaker', 'Oath', 'Those picked up by your Rhythm are marked for 8 seconds. Whenever an opponent dodges your attack, detect their rhythm and vigor. You can use Rhythm while standing.', '["After activating Rhythm, it won''t deactivate unless manually toggled or if you get hit.","If your Rhythm detects a player who''s performing an action, it will put a red highlight on them for 8 seconds. 3 second cooldown. This highlight can be seen through walls and can detect players from very far away, even further than your Rhythm range.","When someone would dodge through one of your attacks, their health and posture will be shown in text as a percentage.","Unlike base Rhythm, the visual HP and posture percentages works on players with the Not a Scratch Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('haunted-path-specter', 'Haunted Path: Specter', 'Specter', 'Common', 'Build up spectral energy by performing successful dodges and landing Wind mantras. Phantom winds from Haunted Gale no longer appear. You can no longer suffocate enemies.', '["Any Talent that requires you to have suffocated an enemy beforehand to activate, such as Silencer''s Song, will be unable to, making them not worth taking.","Any Talent or Mantra that applies suffocation will have the status effect replaced with a Haunted Phantom."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('apparitions', 'Apparitions', 'Specter', 'Common', 'Your Haunted Phantoms become Apparitions that apply Winded on hit. Apparitions cannot be parried if you are in Phantom Step.', '["Apparitions can be parried in \"Phantom step\" (Possibly a bug)","Landing an ability that would normally apply Suffocation or landing a Galebreathe Mantra during Haunted Gale creates an Apparition.","Apparitions have the same stats as Haunted Gale''s Ghosts, with 7 base damage and 5 Galebreathe scaling. Though, their model is very different and Apparitions can proc Specter Talents.","The Freezing Wight Talent gives your Apparitions the Frostdraw damage type, Chill application, and an additional 5 Frostdraw scaling."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('phantom-step', 'Phantom Step', 'Specter', 'Common', 'Press input=X to begin running at high speeds and your regular dashes transform into gale dashes. (Must have at least 10% Spectral Gauge)', '["Phantom Step''s activation keybind can be configured in settings.","Has a 3 second cooldown on activation.","Passively drains your Spectral Gauge while active.","Grants a speed boost for the full duration.","Phantom Step dashes have an extended travel distance and increased i-frames, however they will end early if you attack.","Phantom Step dashes have a 3 second cooldown.","Phantom Step dashes and Gale Dashes have separate cooldowns.","Phantom Step dashes can proc Cyclone Blade."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('vanishing-wraith', 'Vanishing Wraith', 'Specter', 'Rare', 'Your ''Aerial Attacks'' while in Phantom Step will now teleport you behind your target', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('possession', 'Possession', 'Specter', 'Advanced', 'After an apparition hits an enemy, receive 7.5% posture damage on all Galebreath attacks for 8 seconds. If the apparition hits while you have Phantom Step active, receive a 7.55% chip damage buff for 6 seconds.', '["Only applies to Galebreathe Mantras.","The posture damage and chip damage buffs have reduced effects if you have under 75 Galebreathe."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heartwing-beat', 'Heartwing Beat', 'Spoils of Enmity', 'Common', 'Your heart beats a new rhythm, as your aerial attack takes on a new manifestation.', '["Replaces your aerial attack with a swooshing attack that applies wither and has innate bleed.","You cannot use Silentheart''s Relentless Hunt unless this Talent is on cooldown.","Heartwing Beat has 25 base damage, and mirrors the scaling stat from your equipped weapon. Tangentially, this Talent uses the weapon scaling formula.","For example, using Heartwing Beat on the Sword will give it 2.5 Medium scaling, while using it on the Repeater will give it 15 Light Weapon scaling.","Heartwing Beat has a 10 second cooldown.","Granted by the Mantle of Enmity torso equipment."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('death-from-above', 'Death From Above', 'Starkindred', 'Oath', 'Upon cancelling your Air Dash, reveal your wings and strike your enemy.', '["Cancelling an Air Dash without your wings grows your wings without having to use any Starkindred Mantras.","Cancelling an Air Dash with your wings out makes you perform three large slashes with your weapon.","Deals moderate Slash damage and posture damage per hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ichor-imbuement', 'Ichor Imbuement', 'Starkindred', 'Oath', 'Using a Starkindred mantra while your wings are not out increases the damage they deal by 2 times.', '["Doubles the damage of your Starkindred Mantras if they are casted without your wings out.","This Talent is extremely situational, as your wings will be equipped upon casting a Starkindred Mantra or using Death From Above, regardless of it hits or not, and there is no way to deactivate your wings once they are out."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-link', 'Static Link', 'Static Weaver', 'Common', 'Flourishing or uppercutting an enemy creates a static link between you and your enemy.', '["Static Link lasts 15 seconds.","The links are non-refreshable, meaning you''ll need to wait until after the duration ends to reapply the status effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('jumper-cables', 'Jumper Cables', 'Static Weaver', 'Common', 'Being made Unconscious with an active thether allows you to steal health from a tethered target and not be made Unconscious.', '["Whenever you would get knocked but have a tether active, steal HP from the latest static linked target to survive the hit.","Deals 30 true damage to the Jumper Cables victim, and heals you for 30 health.","Nullifies the damage that the hit would have done.","The Static Link is removed on proc.","45 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('link-conduction', 'Link Conduction', 'Static Weaver', 'Common', 'While you have active tethers your lightning mantras cost less ether.', '["Each active link reduces the Ether cost of your Thundercall Mantras by 30%."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-ace', 'Static Ace', 'Static Weaver', 'Common', 'Using Lightning Stream with an active tether link targets your closest active link.', '["Using Lightning Stream with a tether will instantly grab the target with no travel time.","Actually target the first active tether, not the closest."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-allure', 'Static Allure', 'Static Weaver', 'Common', 'Having two active tethers will cause the previous tethered enemy to get magnetized to your newest tethered enemy, also increases the duration of tethers by 15 seconds.', '["The magnetization instantly procs upon applying a second Static Link.","The Static Link duration increase is only applied to the Static Link that procced the magnetization effect."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('storm-link', 'Storm Link', 'Stormcaller', 'Common', 'While you have a Static Link on someone, your Wind mantras that hit them are imbued with flashes of Lightning.', '["Adds a secondary instance of damage to your Galebreathe Mantras if they hit a Static Linked target. This deals 10% of your attack''s scaled damage as Thundercall damage.","This does not allow your Galebreathe Mantras to proc any Thundercall Talents or status effects."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grasp-on-reality', 'Grasp on Reality', 'Sturdy Resolve', 'Common', 'Damage taken from insanity is reduced.', '["Reduce damage taken from the Tier 2 insanity effect, Scratching.","The Celtor Commander Helm equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('magical-resolve', 'Magical Resolve', 'Sturdy Resolve', 'Common', 'Being hit increases Ether regen for a short duration, the strength of the regen scales off your Willpower. (+7 Sanity)', '["Does not work on self damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('unfazed', 'Unfazed', 'Sturdy Resolve', 'Common', 'You are more resilient to the side effects of going insane. You no longer Shiver and you Panic with less severity.', '["Contrary to the card''s description, effect of insanities are delayed by a full tier.","You now Shiver at Tier 2 insanity instead of Tier 1.","You now Scratch yourself at Tier 3 insanity instead of Tier 2."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('voltaic-conductor', 'Voltaic Conductor', 'Superconductor', 'Common', 'Your Thundercall Mantras deal 30% chip damage against enemies with conductor rods.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('iron-gut', 'Iron Gut', 'Survival Instinct', 'Common', 'You have resistance against being poisoned by foods.', '["Does not work when eating Pufferfish (gamebreaking).","The Herbalist''s Hat and Big Herbalist''s Hat equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('termite', 'Termite', 'Survival Instinct', 'Common', 'You can eat things most would consider inedible. (+3 Health)', '["Allows user to eat Sticks, Bamboo, Beeswax, Coral, Spider Eggs, all Lotuses, and every Ore.","Unlock requirement: Wipe with the Iron Gut Talent (can''t be given by armor)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('winters-protection', 'Winter''s Protection', 'Survivor', 'Common', 'Your tightly-bound winter gear negates elemental damage buffs from weather on damage against you. Also seems to provide some resistance to the Gale.', '["Increases the time it takes for the Second Layer''s parasites to kill you.","Negates damage buffs from weather:","Frostdraw will no longer apply its 5% damage buff during snow.","Thundercall will no longer gain its 5% damage buff during rain. Stratoshock will also no longer apply its additional 5% damage buff.","Obtained by equipping Winter Corps Parka."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dustlunge', 'Dustlunge', 'Swiftshade', 'Advanced', 'You can now assassinate your enemies from much farther, shadestepping to their location if they''re too far. Assassinating an enemy will automatically assassinate other nearby enemies. (+1 Passive Agility)', '["Your assassination range is greatly extended, teleporting you to your target when outside the standard assassination range. (The teleport near for assassination is disabled when in combat)","Has reduced range if you have under 90 Agility.","When you assassinate a player, everyone else nearby gets backstabbed by a shadow. These apply all your backstab Talents.","Also grants the ability to assassinate players who are in combat."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('none-left-behind', 'None Left Behind', 'Swiftshade', 'Common', 'You can now shadestep to pick up Unconscious humanoids far away from you. (+1 Passive Agility)', '["15 second cooldown.","Utilizing the ''Carry'' action on a knocked entity who''s in close/medium range teleports you to them.","Can be used to go through walls if you can aim at the knocked entity through it."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('foolish-outburst', 'Foolish Outburst', 'Tactician', 'Common', 'Blocking or parrying a vent will absorb the Tempo cost of the vent. A Tactician steadies the course of battle.', '["Steals 40% of the Tempo used.","Every point in Intelligence below 50 will reduce the Tempo steal by 0.66%, capping at a minimum of 23.33% of the Tempo absorbed with 25 Intelligence.","The Veteran Adventurer Outfit has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hard-read', 'Hard Read', 'Tactician', 'Common', 'Hitting your opponent during a feint will cause them to be Dazed.', '["Applies daze for 1 second."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('punishing-blow', 'Punishing Blow', 'Tactician', 'Rare', 'Heavy Weapons Daze opponents for 1s and Stagger PvE enemies for 2s when you interrupt their Basic Attack / actions with your own.', '["If you M1 your opponent during their M1 animation, they will be dazed for 1 second.","Also procs if you land a critical with the M1 tag during their M1 animation.","The Stagger status effect makes your opponent take 33% more posture damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('target-switch', 'Target Switch', 'Tactician', 'Common', 'Parrying an opponent then hitting someone else makes your next mantra free.', '["This effect is signalled by a yellow halo.","Has a 4 second activation window with a 10 second duration.","This talent will still proc if you hit a knocked enemy."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('water-off-a-ducks-back', 'Water off a Duck''s Back', 'Tactician', 'Common', 'Venting will shift any elemental status effects affecting you onto those hit by your vent. Will also remove potion splash statuses on vent.', '["Transfers Suffocation, Winded, Chill, Shock, Burn, and potion effects from yourself to your enemy on vent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('controlled-combustion', 'Controlled Combustion', 'Tamed Flame', 'Common', 'Your Agitating Spark no longer spreads to your allies.', '["Your Agitating Spark no longer spreads to yourself too.","In some places, this Talent doesn''t work well, spreading to your allies if they are too close to the target."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('artisan-chef', 'Artisan Chef', 'Tavernkeep', 'Common', 'The food you cook now becomes Artisan food, increasing its hunger and thirst gained by +25%.', '["Increases food nutritional value by 25%.","Increases the amount of health regenerated by Fondant Splitter''s critical by a flat +1.25 on each tick, totaling to +2.5 Health. This stacks additively with Master Chef''s effect, which does the same thing.","Having both Master and Artisan Chef will increase the healing amount from Fondant Splitter''s critical from a flat 15 to a flat 20.","The food items must be cooked individually to count; bulk crafting will not count as multiple food items cooked. Additionally, any craftable food item works."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-chef', 'Master Chef', 'Tavernkeep', 'Common', 'Buffs applied by food you cook now have their buff effects amplified by +30%.', '["Increases food boosts by 30%.","Increases the amount of health regenerated by Fondant Splitter''s critical by a flat +1.25 on each tick, totaling to +2.5 Health. This stacks additively with Artisan Chef''s effect, which does the same thing.","Having both Master and Artisan Chef will increase the healing amount from Fondant Splitter''s critical from a flat 15 to a flat 20.","The food items must be cooked individually to count; bulk crafting will not count as multiple food items cooked. Additionally, any craftable food item works."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('umami', 'Umami', 'Tavernkeep', 'Common', 'Feast on foes with mighty cutlery. Chef Weapons now steal opponents hunger.', '["Has a 35% chance to proc with a 3 cooldown per proc attempt, going on cooldown even if it fails to proc.","Hunger and thirst steal formula is as follows: 1.95 * ln(D) + 1.075, where D = scaled damage dealt. A calculator is listed [https://www.desmos.com/calculator/yktgme7xnc here].","The hunger and thirst steal are NOT affected by damage modifiers or resistances, rather exclusively being based on scaled damage dealt.","Acts similarly to and stacks additively with the Gluttony enchant.","Procs on: The Long Tong of The Law, The Flippers of Fate, The Pastry Paster, and Fondant Splitter.","Obtained from: Chef''s Toque"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('explosive-finish', 'Explosive Finish', 'The Demon Blade', 'Common', 'If an enemy is on fire when you flourish, blast them away with a fire blast.', '["Deals 5 Flamecharm damage.","Upon proccing Emperor Flame, this Talent will be put on a 3s cd."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flaming-flourish', 'Flaming Flourish', 'The Demon Blade', 'Common', 'Set enemies on fire when you flourish or uppercut them.', '["You also apply burn on enemies by swinging uppercut nearby. Aka doesn''t have to be a hit to apply burn."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('emperor-flame', 'Emperor Flame', 'The Emperor''s Blade', 'Common', 'Absorb fire produced by you, once you reach 5 stacks your next attack will be an automatic Explosive Finish flourish. This flourish will deal additional damage and proc Wither, reducing your opponent''s maximum health temporarily.', '["Landing a basic attack while you have the Emperor Flame status effect will proc the flourish, dealing 15 Flamecharm damage, 25 Wither damage, and applying burn to the victim and anyone else nearby. This cannot proc on knocked enemies and does not proc Dazing Finisher.","The Emperor Flame status effect lasts 10 seconds or until you land a basic attack. Emperor Flame has a 30 second cooldown.","Hitting enemies with attacks that apply burn will grant Emperor Flame stacks. This will proc regardless of if the target is currently burning or not. There is a 2 second cooldown for stack gain.","Emperor Flame extinguishes burn applied to yourself through Agitating Spark. If Emperor Flame is on cooldown, your self applied burn will not be extinguished."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mirage-clone', 'Mirage Clone', 'The Emperor''s Blade', 'Rare', 'Successfully dodging leaves behind a heat mirage clone that sets enemies that swung at you on fire.', '["Has a 20s Cooldown","With eruption path, it will proc eruption."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('grasp-of-eylis', 'Grasp of Eylis', 'The Knives of Eylis', 'Origin', 'You can temporarily teleport to locations near your bounty target, if one can be found. However, you must stay close, or be desynchronized.', '["Grants a Talent tool that can only be used in the Voidheart.","After picking up a bounty, you can use this tool to select your bounty hunt method; stealth or ferocity.","Stealth: Teleport near, but far away from your target. The bounty indication will be hidden.","Ferocity: Teleport close to your target, highlighting them through walls briefly. Your character will be enveloped in shadows, signifying that you have a bounty.","Grasp of Eylis can only be used on bounties targets that are less than 4 levels lower than you.","You cannot use Chime of Dwelling while on a bounty hunt."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('voideye', 'Voideye', 'The Knives of Eylis', 'Origin', 'Voidmother''s blessing, the method to travel back to the Voidheart.', '["Grants a Talent tool that teleports you back to the Voidheart on use.","Has a short animation that can be interrupted.","1 minute cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('voidwalker-contract', 'Voidwalker Contract', 'The Knives of Eylis', 'Origin', 'You progress much faster from completing bounties, and less from events. Gain access to the Voidheart, and factions have a negative outlook on you.', '["Gain increased EXP from bounties of all kinds, but gain reduced EXP from all other sources."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('last-second-negotiations', 'Last Second Negotiations', 'The Negotiator', 'Common', 'Most enemies will hesitate a moment longer to execute you.', '["Whenever you are getting gripped, your character will say \"WAIT WAIT WAIT WAIT!!!\", which has a chance to automatically cancel the grip attempt, forcing the target to attempt a grip again. This also slightly slows down the grip attempt.","Does not work in PVE."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cap-artist', 'Cap Artist', 'Thief', 'Common', 'Pressing [input=,] while crouching allows you to fake being dead. You also take a bit less damage from PvE while ragdolled as well. (+2 Passive Agility)', '["Your eyes are still open, your name is still visible and you do not leave a loot bag.","Cap Artist''s activation keybind can be configured in settings.","Cancelled by pressing the activation key again.","Using Cap artist in the depths makes you have normal gravity.","Disabled with Brick Wall.","The Tillian''s Beret equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pickpocket', 'Pickpocket', 'Thief', 'Common', 'Gain the ability to pickpocket by pressing input=N. Deal a little more damage the more notes you have against PvE opponents as well. (+2 Passive Agility)', '["The target needs to be Unconscious to be pickpocket-able.","The Pickpocket keybind can be configured in settings.","Gain +0.0002% PvE damage for every 1 you have. At 15,000 Notes, this provides a 3% damage buff."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-thief', 'Master Thief', 'Thief', 'Common', 'Gain more notes when mugging a player.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('another-mans-trash', 'Another Man''s Trash', 'Thief', 'Advanced', 'Take unequipped equipment when mugging a player. Gain a little more damage against PvE the more you are currently carrying. (+2 Passive Agility)', '["If the player you are mugging doesn''t have any Notes, you will still take any unequipped equipment.","Does not take enchanted or Soulbound items.","Gain +0.01% PvE damage for every 1 weight in your inventory. Every 100 weight equates to +1% damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('discharge', 'Discharge', 'Thunder Brawler', 'Common', 'Light Weapons On 5th successful attack you will discharge static dealing lightning damage to those nearby.', '["Deals 5 Thundercall damage with 5 Thundercall scaling, gaining 0.025 damage per point in Thundercall.","Applies Shock or 1 Surge Rod on proc."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rain-of-static', 'Rain of Static', 'Thunder Caster', 'Common', 'After successfully casting lightning impact, strike down countless thunder at those below. In return your Lightning Impact will require more time to cast.', '["When casting Lightning Impact, hover above the ground and fire 4 thunder projectiles. Afterward, you strike down normally."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('windup-battery', 'Windup Battery', 'Thunder Caster', 'Common', 'Landing 3 Thundercall Mantras without whiffing reduces the windup of your next Mantra by 10%.', '["Applies this bonus to non-Thundercall Mantras.","Requirement: 30 Thundercall, 30 Intelligence","The old Jolt Cast Talent was reworked into this."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-blade', 'Static Blade', 'Thunderblade', 'Common', 'Medium Weapons Hitting blocks, blocking or parrying hits will now generate an electric charge in your blade, granting a small speed buff. Charges can stack up to 5 times.', '["Grants stacks when you get parried, not when you parry attacks. Also grants stacks when you hit blocks or block attacks.","Each stack lasts for 15 seconds and refresh upon gaining another, including when you''re at max stacks. You can be at max stacks indefinitely.","Each stack grants an ~2.35% speed boost, totaling to ~11.75% speed at max stacks. The duration of this speed boost is effectively indefinite, as gaining stacks can be done very easily just by playing the game.","This speed boost can proc speed boost Talents, like Speed Demon or Cheap Shot."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gathering-electricity', 'Gathering Electricity', 'Thunderblade', 'Common', 'Medium Weapons Reaching 5 Static Blade charges will now consume the stacks and apply a lightning buff to your blade. 60 second cooldown.', '["Clears all Static Blade stacks on proc.","You can still gain Static Blade stacks while Gathering Electricity is active.","For 15 seconds, this increases the base damage on your weapon attacks, including criticals by 3.","+3 base damage might not seem like a large buff, but due to how Deepwoken''s damage calculation works, this is very significant."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('overcharge', 'Overcharge', 'Thunderblade', 'Common', 'Your next dash after activating Static Blade is enhanced by lightning.', '["Lightning Dashes increase your dash distance travelled by 2.3x and the duration of i-frames from rolling, but will end early if you attack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('thundercall-unbounded', 'Thundercall Unbounded', 'Thundercall Master', 'Mastery', 'You have gained the ability to surpass your limits and train your Thundercall to its fullest. (+10 Health)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('thundercaller', 'Thundercaller', 'Thundercaller', 'Mantra Level', 'Grants you the ability to command Lightning as a Thundercaller.', '["Obtained at 1 Thundercall"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('adept-thundercaller', 'Adept Thundercaller', 'Thundercaller', 'Mantra Level', 'You can now obtain 1-star Thundercaller mantras.', '["Obtained at 20 Thundercall"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('expert-thundercaller', 'Expert Thundercaller', 'Thundercaller', 'Mantra Level', 'You can now obtain 2-star Thundercaller mantras.', '["Obtained at 30 Thundercall"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('master-thundercaller', 'Master Thundercaller', 'Thundercaller', 'Mantra Level', 'You can now obtain 3-star Thundercaller mantras. (+5 Health)', '["Obtained at 50 Thundercall"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('discovery-of-fire', 'Discovery Of Fire', 'Thundercaller', 'Common', 'Flints and Flamecharm are for simpletons.', '["Using this ability will consume 20 Ether to cause a lightning strike that lights nearby entities aflame including campfires, players, and monsters.","Has a 1 second delay between usage and the lightning bolt striking, potentially allowing for movestacks.","15 second cooldown. This cooldown starts when the lightning bolt strikes.","Deals 3 flat Thundercall damage on impact, applying burn with no hitstun and 1.08x PvE scaling.","Discovery of Fire can be parried and blocked, applying parry stun to the caster if parried, and dealing 0 posture damage if blocked.","Does not have hitregistry in Chime of Conflict."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shocking-finish', 'Shocking Finish', 'Thundercaller', 'Common', 'Following a flourish up with a lightning beam causes it to be casted instantly.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-fakeout', 'Static Fakeout', 'Thundercaller', 'Rare', 'Roll cancelling immediately after a parry will cause you to teleport behind your opponent.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('static-flash-clone', 'Static Flash Clone', 'Thundercaller', 'Common', 'When using lightning clones you instead disappear leaving behind a static clone for a short duration.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('stratoshock', 'Stratoshock', 'Thundercaller', 'Common', 'Your lightning deals an additional +5% damage when in the rain.', '["Thundercall damage innately gains a 5% damage buff during rain, with Stratoshock increasing this to +10% damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('manipulator', 'Manipulator', 'Toxic Personality', 'Common', 'Deal 20% more critical attack damage to charmed enemies, but the effect is removed on impact.', '["10 second cooldown.","Works insanely well with Unnecessary Theatrics and Overcharm as they reapply the charm after the charm is removed on the same hit.","Will not allow you to proc Manipulator twice as it has a cooldown.","Tough Love and Manipulator proc at the same time, allowing for a 30% damage bonus.","Manipulator is inherently weaker on multihit criticals, but that doesn''t mean it''s always bad.","For example, a 5 hit multihit critical will only gain the 20% damage bonus from Manipulator on the first hit as it only procs once and then goes on cooldown.","The effectiveness of Manipulator on multihitting criticals depends entirely on the critical itself, with its hit count and scaled damage multipliers being very important factors, as well as whether or not you expect to even land the whole thing. Sometimes front loading the critical proves more effective than having a more consistently applied damage multiplier."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('narcissist', 'Narcissist', 'Toxic Personality', 'Common', 'Charming an already Charmed opponent Overcharms you briefly. Guess you really were always that great.', '["Overcharms yourself for 4 seconds.","Charms yourself for 8 seconds (halved to 4s if you have Disbelief).","The self Charm proc reduces self damage taken by 10% and allows you to benefit from Charismatic Cast''s secondary effect, which reduces your time knocked by 50%.","Landing M1s and criticals while Overcharmed charms your opponent for 5 seconds (halved to 2.5s if they have Disbelief). Additionally, Overcharm grants a 10% damage bonus to melee attacks when hitting charmed opponents.","Mutual Exclusives: Tough Love"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('sow-and-mend', 'Sow and Mend', 'Transitory Vitality', 'Rare', 'Sacrifice 35% of your blood for temporary health. (30s CD)', '["Gives 25 flat Temporary Health on use."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cyclical-exsanguination', 'Cyclical Exsanguination', 'Transitory Vitality', 'Common', 'Whenever you deal more than 20 damage to an enemy in an instance, pause your temporary health decay for 3 seconds.', '["8 second cooldown.","This can proc on self damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('embolism', 'Embolism', 'Transitory Vitality', 'Common', 'If an enemy is guardbroken while you have temporary health, convert your temporary health into additional damage.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hypovolemic-focus', 'Hypovolemic Focus', 'Transitory Vitality', 'Common', 'While you have temporary health, your opponent regains far less posture from parrying you', '["The opponent regains 20% less posture damage from parrying you."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cheap-shot', 'Cheap Shot', 'Trickster', 'Rare', 'Your attacks gain 10% PEN multiplicatively when you have an active speed boost. (+6 Passive Agility)', '["It multiplies your PEN by 1.1x. IE: if you are at 30% PEN, Cheap Shot will give you an additional 3% PEN.","Cheap Shot cannot bypass the PEN cap.","Cheap Shot''s PEN multiplier will be reduced by 0.11% for every point in Agility below 65, having a minimum multiplier of +7.22% PEN (or 1.072x PEN) at 40 Agility."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('crippling-comeuppance', 'Crippling Comeuppance', 'Trickster', 'Advanced', 'Landing Revenge puts your opponent''s Mobility slot Mantras on CD and applies Sluggish to PvE enemies for 15s. (+1 Passive Agility)', '["30 second cooldown.","For every point of Agility below 100, Crippling Comeuppance''s duration is reduced by 0.1 seconds, having a minimum duration of 12.5 seconds at 75 Agility."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('down-comes-the-claw', 'Down Comes the Claw', 'Trickster', 'Common', 'Landing a Critical while you have a speed boost prevents your opponent from being able to dodge twice in a row for 5s. (+1 Passive Agility)', '["Down Comes the Claw cannot be reapplied while it''s currently active.","Lasts 6.5 seconds.","For every point in Agility under 75, Down Comes the Claw loses 0.055 seconds of duration, capping at a minimum of 5.11 seconds with 50 Agility."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('maiming-claws', 'Maiming Claws', 'Trickster', 'Common', 'Down Comes the Claw now disables your opponent''s posture regeneration for 6s on proc. (+1 Passive Agility)', '["Applies to passive posture regeneration, Steady Nerves, and posture restoration from parrying. All other sources of posture restoration ignore Maiming Claws entirely.","Cannot be reapplied while Down Comes the Claw is currently active.","Maiming Claws'' duration will be shortened if you do not meet its requirements."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pursuit', 'Pursuit', 'Trickster', 'Common', 'If you land your Revenge, clear the cooldown immediately. (25s cooldown) (+1 Passive Agility)', '["Procs even if Revenge is blocked, parried, dodged, or vented.","For every point in Agility below 90, Pursuit will gain +0.375 seconds to its cooldown, capping at 29.375 seconds with 65 Agility."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('face-cutter', 'Face Cutter', 'Twinblade', 'Rare', 'Your Spine Cutter now deals an additional hit. (+2 Passive Agility)', '["Grants an additional hit to your Spine Cutter that deals 50% of your weapon''s scaled damage.","Similarly to Spine Cutter, the damage this deals cannot be buffed, and the attack has no PEN."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('turning-of-the-wheel', 'Turning of the Wheel', 'Twinblade', 'Rare', 'After perfect dodging a swing or critical attack, step backwards and ramp up your swingspeed.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('wraith-path-twisted-puppets', 'Wraith Path: Twisted Puppets', 'Twisted Puppets', 'Common', 'Your Flamecharm mantras summon puppets of shadow and flame. Your flames are now black.', '["Turns Hero Blade of Flame, Ysley''s Pyre Keeper, Pleeksty''s Inferno, Rosen''s Hellflame, Blazing, and Railblade''s criticals and all Flamecharm mantras black. Additionally, the orange on the Hero Blade of Flame''s and Ysley''s Pyre Keeper''s models change to black. And the orange on Pleeksty''s Inferno''s model changes to purple.","Twisted Puppets has two different burn types. They both look identical and they both scale on your Flamecharm investment, deal Flamecharm damage, and drain 6.25 Ether per tick from affected players.","Shadow damage from any source applies Shadow Burn. Shadow Burn does 75% less damage than base Flamecharm burn. This burn type cannot be applied to knocked targets.","Anything that would normally apply burn applies Puppet Burn. Puppet Burn does 87.5% less damage than base Flamecharm burn. Puppet Burn allows you to spawn Puppets.","Both these damage multipliers are applied after other damage boosters such as Ash Ember thus working extremely poorly with it.","Puppets deal 20 typeless damage with no innate investment scaling. Because Puppets deal typeless damage, they bypass armor resistances and Everchanging Aegis. They do NOT do True Damage however, as general resistances still work on them.","Puppet damage can be increased with damage modifiers. Additionally, Puppet damage is reduced when it''s raining unless you have the Unyielding Inferno Talent.","Puppets deal 10 posture damage.","Puppets spawn whenever Puppet Burn deals damage with a 4 second cooldown.","Increases the uptime of your Flame of Denial by 25%, from 25 seconds to 31.25.","Mutual Exclusives: Eruption Path: Lava Serpent, Azure Flames, Flashboil"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('burning-puppets', 'Burning Puppets', 'Twisted Puppets', 'Common', 'Your puppets can now inflict burn and fire-based Talents when they explode.', '["Grants Puppets 5 Flamecharm scaling, increasing their damage by 0.1 per point in Flamecharm.","Your Puppets will deal 30 damage at 100 Flamecharm with this talent.","Your Puppets apply Puppet burn, allowing you to spawn more Puppets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('burning-sacrifice', 'Burning Sacrifice', 'Twisted Puppets', 'Rare', 'Sacrifice puppets who have been alive for half of their lifetime and burn purple for Emperor Flame Stacks, a damage boost per puppet, and a slight speed boost.', '["Gives you a Talent tool that must be actively used to proc this Talent.","Grants +4% basic attack damage and a speed boost per Puppet for 6s. Caps off at +12% damage.","Puppets turn purple after being alive for 15 seconds.","15 second cooldown if at least one Puppet is successfully sacrificed, 1 second cooldown if not."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('explosive-rage', 'Explosive Rage', 'Twisted Puppets', 'Common', 'Causing explosion will make your puppets go into a frenzy - speeding up and dealing 50% more damage.', '["The buff is signified by an orange swirling aura around your Puppets.","Buffs all currently alive Puppets and all Puppets that spawn within the next 10 seconds.","The damage buff is bugged and does not work.","The following abilities and Talents proc Explosive Rage: Explosive Finish, Emperor Flame, The Final Act, and the Detonation enchant."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('moths-to-a-flame', 'Moths to a Flame', 'Twisted Puppets', 'Common', 'You summon a puppet of black flames that homes onto enemies with black flames.', '["Your Puppets home onto the closest entity (excluding yourself) who is burning from either of the Twisted Puppets burn types.","This can include allies.","Puppets move significantly faster when they get close to a burning target."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('audacity', 'Audacity', 'Tyrant', 'Advanced', 'Once you''ve brought down your prey, instill fear into all those who would separate you from claiming it. Charmed or nearby enemies will fear for longer. Nearby allies gain a 10% damage buff (40s). (+1 Posture)', '["25 second cooldown.","Audacity''s buff duration will be reduced by 0.1 seconds for every point of Charisma and Strength you are below its requirements, capping at 35 seconds with 75 Charisma and 25 Strength.","You create an AoE stun and slow around you when you start gripping someone.","Makes you immune to Defiant Until the End and Last Second Negotiation when it procs. (Bugged on NPCS)","The damage buff is indicated by a white glowing halo effect surrounding the affected player''s head."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('no-survivors', 'No Survivors', 'Tyrant', 'Common', 'Your allies and yourself execute faster when affected by Overcharm.', '["Reduces grip time by 0.5 seconds (16.67% faster)"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('rule-through-fear', 'Rule Through Fear', 'Tyrant', 'Rare', 'Executing an enemy applies Overcharm to nearby allies and yourself.', '["Overcharms for 10 seconds.","Landing M1s and criticals while Overcharmed charms your opponent for 5 seconds (halved to 2.5s if they have Disbelief). Additionally, Overcharm grants a 10% damage bonus to melee attacks when hitting charmed opponents. This bonus does not stack with Tough Love."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('denial-repulse', 'Denial Repulse', 'Undying Ember', 'Rare', 'You now emit a delayed burst of flames after coming close to death.', '["When Flame of Denial activates, release an explosion around you.","This explosion deals 20 Flamecharm damage with 5 Flamecharm scaling, adding up to 30 Flamecharm damage at 100 Flamecharm.","This cannot be parried nor dodged, but can be blocked, dealing 5 posture damage.","This has a windup of 0.6 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('undying-flame', 'Undying Flame', 'Undying Ember', 'Rare', 'Your Graceful Flame burns brightly even underwater. Those that gather around it are soothed and regain sanity.', '["Graceful Flame can now be casted in the First Layer. It cannot be used in the Diluvian Mechanism or Depths Trials, however.","Graceful Flame now passively restores sanity and health to those around it.","Merged with the old Soundness of Mind Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('surge-path-unstable-capacitor', 'Surge Path: Unstable Capacitor', 'Unstable Capacitor', 'Common', 'Your lightning no longer applies Shock, instead apply Surge. At maximum stacks of Surge, your opponents will Overload, sending arcs of lightning in every direction.', '["Turns all Thundercall mantras, Jumpstart, Stormseye, Hero Blade of Lightning and Boltcrusher blurple. May affect Arcwarder and Saintsworn in the future.","Each Surge stack lasts 30 seconds.","You need to apply 5 Surge stacks and then land another attack that would apply a Surge stack to cause an Overload.","This is reduced to 4 Surge stacks with the Charged Ring.","Surge Overload deals 2.5 Thundercall damage per Surge stack with 5 Thundercall scaling to Overloaded target.","Surge Overload AoE deals 2 Thundercall damage per Surge stack.","Surge stacks are a global status effect, meaning anyone with Surge path can utilize them, with the effects changing based on who caused the Overload."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('battery-sapper', 'Battery Sapper', 'Unstable Capacitor', 'Common', 'If your Human Battery targets have Ether, it will drain their Ether to help pay for your Mantras. 10s cooldown.', '["This Talent is currently bugged and does nothing."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('catalytic-strike', 'Catalytic Strike', 'Unstable Capacitor', 'Common', 'Posture breaking an enemy will Overload their Surge stack.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('closed-circuit', 'Closed Circuit', 'Unstable Capacitor', 'Common', 'Surge Overloads that fail to arc to other opponents will deal additional damage to the Overloaded enemy.', '["Adds 5 damage to the Overload with 5 Thundercall scaling."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('fried-circuits', 'Fried Circuits', 'Unstable Capacitor', 'Common', 'Overloading an enemy applies Sapped for 5s.', '["Sapped effect causes the duration of mantra cooldowns to increase, which acts similar to Thunder Wisp."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('human-battery', 'Human Battery', 'Unstable Capacitor', 'Common', 'When you are out of Ether, convert the Surge stacks of nearby enemies into Ether to pay the cost of your Mantras.', '["Every Surge stack equates to 10 Ether.","Works on Surge stacks that weren''t applied by you.","Does not work on Surge stacks applied to yourself."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('both-ends', 'Both Ends', 'Vanguard Arts', 'Common', 'Pressing input=M2 after landing a light attack with the staff performs a follow-up swing from the opposite end.', '["This attack comes out much faster, but only deals 45% of your weapon damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('counter-spin', 'Counter Spin', 'Vanguard Arts', 'Common', 'After blocking an attack, press input=M2 to counter with your staff.', '["On proc, swiftly thrust your Staff forwards, dealing 45% of your weapon''s damage on hit."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('flashboil', 'Flashboil', 'Vaporborne', 'Common', 'Landing Ice/fire attacks on burning/chilled enemies extinguishes the flame and generates steam.', '["Dealing Frostdraw damage to a burning target or Flamecharm damage to a chilled target removes the burn and creates a stationary steam cloud.","The burn status effect doesn''t count as \"Flamecharm damage\" for this Talent, meaning if you apply burn via Agitating Spark, Immolation, or some other non-Flamecharm damaging source to a chilled target, nothing will happen.","Steam clouds deal 2 typeless damage per tick in an AoE at 6 ticks per second. Has a DPS of 12.","Steam clouds are unparryable, unblockable, and bypass armor resistances.","Steam clouds last 5 seconds and have an internal proc cooldown per target of 5 seconds.","This Talent is incredibly good for PvE in high mob density areas like The Diluvian Mechanism because of the AoE nature and long duration per cloud. Additionally, you can create a large amount of steam clouds at the same time by hitting multiple mobs at once.","Mutual Exclusives: Eruption Path: Lava Serpent, Glass Path: Crystallization, Wraith Path: Twisted Puppets"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('boiling-point', 'Boiling Point', 'Vaporborne', 'Common', 'Using a fire mantra near your own steam cloud detonates it.', '["Landing a Flamecharm Mantra on one of your steam clouds causes the cloud to detonate, dealing 10 typeless damage in an AoE.","Because this procs when the steam cloud is hit and not the player, even if your opponent defends against your Mantra, it will still detonate your steam.","Landing a Flamecharm Mantra on a chilled opponent will instantly detonate the newly created steam cloud.","Has a short delay which can throw players off.","The detonation is unparryable, unblockable, and bypasses armor resistances."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('action-surge', 'Action Surge', 'Vigil Swordsman', 'Common', 'Adrenaline Surge now increases your swing speed by 0.04 for its duration. (+1 Passive Agility)', '["This is additive with Vigil''s Grace, granting +0.06x swing speed when combined.","Both this and Vigil''s Grace are applied before Lightning Cloak''s swing speed multiplier."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('bear-trap', 'Bear Trap', 'Vigil Swordsman', 'Common', 'Landing a hit with your critical makes your opponent unable to jump for a duration. Also slows your opponent and procs Sluggish on PvE. (+1 Passive Agility)', '["The status effect is represented by blood pouring from the legs.","Makes the opponent unable to jump for 4 seconds.","Upon being applied to an opponent, they Bear Trap immunity for 6 seconds.","The Sluggish status effect applies a -15% damage debuff to affected targets."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('blade-dancer', 'Blade Dancer', 'Vigil Swordsman', 'Common', 'Landing a Basic Attack removes your roll cooldown. (+1 Passive Agility)', '["The Monastery Cowl and Deepwoken Cloak equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cut-to-the-chase', 'Cut to the Chase', 'Vigil Swordsman', 'Rare', 'Air Counter damage scaling is largely increased. Landing an Air Counter now initiates an uppercut. Deal 5% more damage to PvE enemies in the air. (+5 Passive Agility)', '["Air Counters do not innately deal damage. Having this Talent gives your Air Counter 10 true damage.","The damage bonus to your Air Counters will scale down if you have less than 60 Agility.","Air Counter is initiated when using an Aerial attack after your opponent does any of the following: wall jumps (parkour), uses Wind Step (Galebreathe Talent), uses aerial Arc Beam, is launched into the air by Eyes of Ethiron''s one-handed critical, or uses a Lifevent (Starswept jump pad).","Can be synergized with uppercut-based Talents, such as Flaming Flourish.","The old Air Counter Talent was made innate and then reworked into this."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('speed-demon', 'Speed Demon', 'Vigil Swordsman', 'Rare', 'Your attacks now inflict a reduced-strength bleed while you have a speed boost. 1s cooldown. (+1 Passive Agility)', '["Bleed is not accounted for in the damage modifier cap and bypasses armor.","Speed Demon''s bleed deals 2.5% of your weapon''s damage every 0.3s, three times. This totals to +7.5% damage over a 0.9 second period.","Works with M1s and criticals."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('spinning-swordsman', 'Spinning Swordsman', 'Vigil Swordsman', 'Common', 'Running attacks do +15% extra damage when you have a speed boost. (+1 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('oath-visionshaper', 'Oath: Visionshaper', 'Visionshaper', 'Oath', 'You vow to only see that which you wish to see. Reality itself is malleable, pliable to your deft hands. (+1 Support Mantra Slot, +2 Combat Mantra Slots)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('cheap-trick', 'Cheap Trick', 'Visionshaper', 'Oath', 'When hit below half health briefly disappear, leaving behind an illusion clone to keep your enemy occupied for a short duration. Briefly disappear after knocking an enemy.', '["Being hit while under half HP grants I-frames and turns you invisible for a very short duration. 60s CD.","Knocking an opponent turns you invisible for 2.5 seconds with no I-frames."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('reality-shift', 'Reality Shift', 'Visionshaper', 'Oath', 'Command the closest conjured servant to attack their hallucinating target, either using a Critical Attack or a Mantra.', '["The last non-Oath mantra or critical attack you used before spawning your clones will be stored into the clone. The stored ability will be listed above the clone''s head in white text with a purple outline.","Pressing input=J (can be rebinded in settings) or utilizing the Reality Shift tool will make your clones use their stored ability.","Clones created from Mirror Illusion or Illusory Counter''s Reversal Spark will copy your opponent''s last used critical or Mantra instead.","If the clone is too far away from your opponent upon using Reality Shift, they will teleport to them.","Clones will copy your attunement path and mantra modifiers when utilizing your mantras, but they do not utilize your enchants or most Talents.","Clones will only copy the neutral or aerial criticals of weapons and cannot trigger any other alternate criticals such as running or sliding criticals."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('shaper-mimicry', 'Shaper Mimicry', 'Visionshaper', 'Oath', 'The servants you have conjured will imitate your actions when you Swing/Block/Parry/Jump.', '["Although it isn''t listed in the Talent description, your clones will also Vent when you Vent.","Your clones will still Vent even if you don''t have enough Tempo."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('encore', 'Encore', 'Vocalist', 'Rare', 'Your sing will stun opponents who are already charmed.', '["On proc, apply 0.4s of \"full stun\". This can interrupt enemy attacks.","Doesn''t affect allies."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('propagandist', 'Propagandist', 'Vocalist', 'Common', 'Your Sing will now stir your allies into a frenzy, causing them to become Overcharmed for 15s, applying Charmed to enemies they hit with Basic Attacks.', '["Landing M1s and criticals while Overcharmed charms your opponent for 5 seconds (halved to 2.5s if they have Disbelief). Additionally, Overcharm grants a 10% damage bonus to melee attacks when hitting charmed opponents. This bonus does not stack with Tough Love."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('vow-of-mastery', 'Vow of Mastery', 'Vow of Mastery', 'Common', 'The Vow of Mastery grants the Master the power to command their Subject. To initiate a vow you must ask the other player if they''d like to make the vow. e.g. "wanna make a vow of mastery?"', '["Players who take the vow are considered allies with their master and others who take the vow.","Commands Given: \"Sleep\", \"Drop\", \"Run\", \"Eat\", \"Say (Text)\", \"Use\", \"Locate\", \"Leech\" at base, \"Fight\", \"Sacrifice\" at 50 Charisma, \"Return\" at 60 Charisma and \"Explode\" at 75 Charisma."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('command-live', 'Command: Live', 'Vow of Mastery', 'Common', 'Once per hour, command a servant to defy all odds and obey your command - live.', '["Effect: Will fully heal your servant if they have lower than 40% hp","Cooldown scales off the caster''s current Charisma investment."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('command-summon', 'Command: Summon', 'Vow of Mastery', 'Advanced', 'Command your servant to obey your summons and appear before you no matter the distance.', '["Effect: Teleports the subject to the master regardless of distance. Teleportation takes 10 seconds to complete, and any hit will cancel it.","Has a cooldown of 30 seconds for the master and 2 minutes for the subject."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('chronostasis', 'Chronostasis', 'Warrior', 'Rare', 'Landing a Basic Attack or Critical puts the target''s Resonance on cooldown for a short duration, while also applying Ether Sunder to PvE opponents. (+1 Posture)', '["On hit, apply a 13 second Resonance cooldown.","This cannot proc if their Resonance is already on cooldown.","The Ether Sunder status effect grants you 30% damage reduction against affected enemies'' elemental attacks."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('conditioned-swimmer', 'Conditioned Swimmer', 'Waterborne', 'Common', 'You lose less hunger and thirst while swimming. (+1 Passive Agility)', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brutal-momentum', 'Brutal Momentum', 'Weapon Master', 'Common', 'Heavy Weapons Successfully dodging will give you hyperarmour on your next swing.', '["Brutal Momentum works on all heavy weapons, including those who could not utilize this Talent previously like Railblade or Greataxes.","Hyperarmor lasts for 1 second. Successful procs have a cooldown of 8 seconds."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('matador', 'Matador', 'Weapon Master', 'Common', 'Deal +20% more damage to human enemies with hyperarmor.', '["Doesn''t work on Non-Humanoid Monsters."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('showstopper', 'Showstopper', 'Weapon Master', 'Rare', 'When an enemy would roll through one of your physical attacks, stomp the ground, dazing anyone nearby. Removes speed buffs from target upon landing.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('switchblade', 'Switchblade', 'Weapon Master', 'Advanced', 'You can now utilize Dagger Talents when not wielding a dagger.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('warriors-swing', 'Warrior''s Swing', 'Weapon Master', 'Common', 'Heavy Weapons Reduces incoming damage by 5% if hit during Heavy swing hyperarmor.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('haunted-gale', 'Haunted Gale', 'Whisper', 'Common', 'Landing 3 Galebreathe Mantras without whiffing calls for a Haunted Phantom. The Phantom will attack alongside you for the next 8s before dissipating.', '["On proc, gain the Haunted status effect, spawning ghosts that attack your opponent every time you land a Mantra. Only one Ghost can spawn per Mantra.","Gale Wisp increases the duration of Haunted by 3 seconds.","Haunted Gale Ghosts have 7 base damage with 5 Galebreathe scaling.","If your Mantra is blocked, parried, or dodged, it will be \"whiffed\", resetting all stacks of Haunted Gale.","Haunted Gale stacks are counted per person, not globally.","If you have Apparitions, landing a Galebreathe Mantra while having the Haunted Gale status effect will create an Apparition instead.","Landing non-Galebreathe Mantras will create Haunted Gale''s Ghosts even if you have Apparitions.","Having the Freezing Wight Talent will give your Ghosts a Chill proc, the Frostdraw damage type, and an additional 5 Frostdraw scaling."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('agility-unbounded', 'Agility Unbounded', 'Windrunner', 'Mastery', 'You have gained the ability to surpass your limits and train your agility to its fullest.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ash-ember', 'Ash Ember', 'Withered Flame', 'Common', 'The more wither your opponent has, the more damage your burn deals.', '["At 90 FLM 90 WPN you gain a 0.0175 burn damage increase per 1 point of wither.","Ash Ember caps at 15 total burn damage.","Every Emperor Flame proc will increase your burn damage by 0.4735, or 1.3125 if you have Scorching Decay."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scorching-decay', 'Scorching Decay', 'Withered Flame', 'Common', 'The wither dealt from your Emperor''s Flame is massively increased.', '["Increases the Wither application from your Emperor Flame from 25 to 75."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('brassneck', 'Brassneck', 'Miscellaneous', 'Common', 'Knocking an enemy grants you 20% damage resistance for 15 seconds.', '["This does work on non humanoid monsters, granting you the damage resistance buff on kill.","This Talent was previously named \"Berserker.\""]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('careful-handling', 'Careful Handling', 'Miscellaneous', 'Quest', 'Reduce your chances of dropping ingredients on death.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('dragons-song', 'Dragon''s Song', 'Miscellaneous', 'Common', 'Using a mantra after an uppercut grants ether.', '["Grants +20 Ether on proc.","2 second cooldown."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('full-reset', 'Full Reset', 'Miscellaneous', 'Common', 'Knocking an enemy resets your resonance cooldowns. This effect has a 60 second cooldown.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('gourmand', 'Gourmand', 'Miscellaneous', 'Common', 'Your hunger and thirst gain from eating is increased. (+5 Carry Load, +1 Posture)', '["Increases hunger and thirst gain by 20%.","Having this alongside the Gourmet Boon increases the hunger and thirst gain from eating by 80%.","The Chef''s Toque equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('heavy-haul', 'Heavy Haul', 'Miscellaneous', 'Common', 'Enemies who carry you move significantly slower. Take slightly less posture damage from large enemies. Takes one to know one.', '["The Grand Authority Plate equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('martyr', 'Martyr', 'Miscellaneous', 'Common', 'When you''re knocked Unconscious, enemies gain less health and posture, and allies around you are granted Martyrdom for 20s.', '["Martyrdom grants +20% damage and damage reduction for 20 seconds.","Martyrdom cannot be given to the player who knocked you, even if they are your ally. Additionally, Martyr does not consider yourself an ally, meaning the buffs won''t be applied to yourself.","Enemies who knock you restore only half of the posture and health they would normally obtain (50% -> 25%).","If the enemy have the Talent Replenishing Knockout, both Talents negate each other, resulting in a normal health pack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pack-mule', 'Pack Mule', 'Miscellaneous', 'Common', 'The max quantity for food you can hold is increased by 5. (+10 Carry Load)', '["Stacks with the Boon of the same name, increasing the maximum amount of food items you can carry in one stack from 10 to 20."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pleekstys-will', 'Pleeksty''s Will', 'Miscellaneous', 'Quest', 'You gain significantly more ether from consuming elemental ingredients.', '["Consuming Gale Stones, Heartstars, Dying Embers, Spark Glands, and Frigid Prisms gives significantly more Ether.","Consuming elemental ingredients has a 20 second cooldown.","Is also a requirement to fight Aska in Firfire. Without either this Talent, Pleeksty''s Faith, or the Flame Worshipper Armor you will wipe through his flames."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('polite-awakening', 'Polite Awakening', 'Miscellaneous', 'Common', 'Recover 15% of your max health after getting up from being downed. (Only Procs when below 20% HP) (+1 Passive Agility)', '["The Khan Pauldrons and Woodland Pauldrons equipment have this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ready-or-not', 'Ready or Not', 'Miscellaneous', 'Common', 'The first attack to hit you while out of combat has its damage cut in half.', '["The Royal Pathfinder equipment has this Talent."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('replenishing-knockout', 'Replenishing Knockout', 'Miscellaneous', 'Common', 'You gain more health and posture from downing enemies.', '["Knocking enemies will replenish 1.5x more of your health and posture (50% -> 75%).","If the target has the Talent Martyr, both Talents negate each other, resulting in a normal health pack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('treefelling-blow', 'Treefelling Blow', 'Miscellaneous', 'Quest', 'You can collect lumber from the trees you fell with your fists. It''s only natural.', '["Allows you to gain Wood when you destroy trees with Strong Left.","Landing a weapon critical puts your opponent''s Resonance on a 25 second cooldown. This does not require Ironsing Rods to proc.","This reduces the posture damage of incoming Mantras by 1 (flat) per hit, per combat tag you have.","If you have more combat tags than the Mantra does posture damage, this can go into the negatives and your posture will be restored instead.","Works in PvE, but you cannot have more than 1 PvE combat tag, so it won''t be very effective.","All of your Medium Weapon Mantras gain a second damage instance that scales directly on your Willpower investment. This deals physical damage.","This deals 0.15 damage per 1 Willpower investment. At maximum this will deal an additional 15 damage at 100 Willpower, or up to 15.45 if you have 103 Willpower.","This effect has no cooldown, allowing your Master''s Flourish and Twincleave to benefit from this effect twice per cast.","This secondary damage instance cannot receive damage modifiers.","Decreases Prominence Draw''s windup by 0.1s (from 0.55s to 0.45s).","Adds a new sound effect to Prominence Draw.","Restores 4% of the user''s maximum health upon landing M1 attacks.","This also procs on Silentheart abilities.","This bleed damage is not like normal bleed damage, as it deals 6 damage per tick regardless of the initial hit''s damage, and it ticks 5 times over 5 seconds instead of 3 ticks immediately. Additionally, this bleed has no cooldown and procs on Motif-applied criticals.","If you are knocked during the duration of this ''bleed'' effect, you will be automatically gripped.","This Talent was formerly called \"Bloodthirsty\".","The final hit of your Pressure Blast gains 3x posture damage, going from 12 to 36 posture damage.","Assuming all hits hit your opponent''s block, your Pressure Blast now does 60 posture damage compared to the previous 36.","Grants a very large increase to the AoE of your Pressure Blast.","Landing weapon attacks while your health is at or below 30% will heal you for 1% of your maximum health.","This is capped at 30 Wither per proc.","If you interrupt someone''s attack with the shock from your Krulian Charge critical, apply the Cruel Counter status effect to your opponent, increasing all damage taken by critical attacks for 20 seconds.","This grants a +40% damage modifier to all critical attacks, even if it isn''t a Krulian Knife critical, and even if the critical they got hit by was used by someone else.","This damage modifier bypasses the damage modifier cap, potentially allowing for absurd critical damage output.","Agility Mantras gain +3 Mantra levels. This bypasses the normal Mantra level cap of 5.","Jetstriker Mantras are unaffected.","Passively increases the speed of your Onslaught.","Grants the Expeditious Combo status effect on uppercut. This status effect will be consumed if you cast Onslaught. The duration of your Expeditious Combo is displayed on the bottom left of the screen on the cooldown indicator.","This effect has no cooldown, but as the Expeditious Combo status effect is consumed on proc, you will need to land another uppercut to proc it again.","\"Uppercut\" or \"uptilt\" Mantras do not grant the Expeditious Combo status effect; you need to land a basic attack uppercut to proc this.","Has a sound effect on uppercut.","Your M1s deal 3 posture damage to non-blocking opponents. Your criticals deal 10 posture damage to non-blocking opponents.","This cannot guardbreak.","This does not benefit from posture damage modifiers. Additionally, your weapon''s damage and weight stat have no impact on this Talent''s effects.","Consumes all of your Chains of Perfection stacks for a secondary instance of damage on your critical.","This deals 7 typeless damage per Chain of Perfection stack. Deals 166 typeless damage per Chain of Perfection stack in PvE.","The first 5 hits that normally do not grant stacks will contribute to this, allowing you to deal 150 typeless PvP damage or 3.5k typeless PvE damage at maximum chain stacks.","The damage this deals can be increased with damage modifiers, though it is not considered weapon damage so it is fairly difficult to buff.","Finishing Slay has no cooldown, allowing for multihit criticals to benefit from it multiple times. However, finishing slay can only proc once per damage instance in a critical hit, for example if you hit three targets with your critical, Finishing Slay will only proc on one of them, and the other two will not take any additional damage.","This procs on Motif and enchant-granted criticals.","Applies a 70% slow for 15 seconds.","Due to the innate slow resistance players have, in actuality this only reduces their movement speed by 52.5%, unless they are casting a Mantra.","This Talent has no cooldown, allowing you to apply multiple rods to a singular person.","If a player has two or more Forced Fulfilment rods, they will not be able to move unless they have a speed boost.","Grants a Talent tool that grants the Fortified status effect, granting 15% damage reduction at the cost of reducing your movement speed by 36%.","The default spear critical no longer gets canceled if the first hit is parried. Additionally, parrying the first hit of this critical does not provide autoparry frames.","Gain various stacking buffs scaling on the amount of combat tags you have. This effect is greatly improved whenever you grip a player.","On basic attack, gain +10% to the following stats: damage, posture damage, elemental damage resistance, physical damage resistance, chip damage, and speed boost per combat tag you have.","The damage, posture damage, and chip damage bonuses are additive and ignore the damage and posture damage modifier caps. These effects cap at +30% (3 or more combat tags), and are applied to Mantras as well. The chip damage bonus will only apply if some amount of chip is already present.","The elemental and physical damage resistance bonuses are multiplicative to other resistance sources.","The speed boost has no cap and is applied per M1. For example, if you land 5 m1s and are combat tagged by 5 people, you will gain +250% speed. Each speed boost stack lasts 5 seconds and does not refresh upon acquiring another. Additionally, being hit by an attack will also proc this bonus.","After parrying a guard break, gain the Punishing Riposte status effect for 15 seconds, making your critical guaranteed guardbreak if it hits block.","Being combat tagged by 2 or more players will cause your critical attack to deal an additional 10 true damage per hit. This stacks based on how many combat tags you have, dealing a minimum of +20 true damage per hit.","Reduces the cooldown of Tactical Reload by 45 seconds; from 90 seconds to 45.","Your Shadowcast Mantras now gain the damage buff and the modification transfer effect from Inhale. Additionally, you can also Inhale Shadowcast Mantras.","Grants a Talent tool that consumes 5 on use to grant the user a random buff within a set pool.","This Talent has a 0.5 second cooldown, and you can overlap the buffs.","The potential buffs are:","20% damage buff. This is also applied to Mantras","Hyperarmor for 10 seconds","Instantly heal 50 health","Thirst restoration","Stomach restoration","Speed boost for 10 seconds","Using your critical attack will no longer slow you.","This Talent allows you to retain all of your momentum during your weapon''s critical attack, making it extremely strong for playstyles that utilize sliding and Gale/Phantom Step dashes often.","Equipping a Motif onto the Withered Gale Pale will disable this Talent.","Punishment has its reflected damage output increased by 12.5%, meaning at level 5 you can reflect 112.5% of someone''s damage on top of the 30 base damage. The base damage of this Mantra is unaffected.","If you are wearing the Authority Commander Outfit, the longevity of the attack window on your punishment is increased by 3x; from 20 seconds to a full minute.","Prediction''s active frames are increased slightly.","Curse of the Unbidden has its posture restoration increased by 10%, restoring 40% of your posture instead of the usual 30%.","Payback, the Resonance, has its active counter frames increased by 0.7 seconds.","Oath-based counters (Illusory Counter and Equalizer) do not have any affect with this Talent.","Increases shaky block duration by 0.004s per point in Thundercall. At 100 Thundercall, shaky block lasts 1 second against players with 1x or slower swing speed weapons.","On proc, you gain the Swift Strike status effect indefinitely. This effect will be consumed when you use your critical.","The teleport has a range limit.","20 second cooldown.","This deals 0.5x your weapons scaled damage per hit (4), dealt as typeless damage.","Deals 5 true damage per slow effect removed.","Uppercutting your opponent applies the Vital Wound status effect, reducing their passive posture recovery by 40% for 30 seconds.","This has no cooldown, but cannot be reapplied to the same target once active.","Your critical cooldown is reduced by 20%, but your Resonance cooldown is 20% longer.","In 1v1 Chime of Conflict, your critical cooldown is reduced by 10% instead.","This effect is applied before Critical Engine Blessed Gem is applied, allowing for 60% reduction in your critical cooldown (55% in Chime of Conflict).","Removes the self damage from Deepspindle''s running critical.","Reduces the self damage from Shade Devour, Flame Within (on cast, NOT the burn ticks), Rush Hour, Shadow Travel, and Electrify.","When paired with the Stormchanter''s Raiments Talent, Circuit Breaker, using Electrify will cause you to heal instead of taking damage.","Lowers self damage from the Poison (HP drain) Corrupted Resonance downside by ~1%.","Lowers the Wither application from the Wither Corrupted Resonance downside by ~2%.","Grants immunity to the Watcher''s Watcher Gaze attack, preventing Sanity loss, vision distortion, and the spawning of Hollow Angel(s).","Grants unique dialogue with Watchers, as you cannot speak to Watchers without this Talent.","Angels will still aggro onto you while you have this Talent.","Grants a Talent tool that on use allows you to teleport to your opponent when you M1 for 20 seconds.","The teleportation has a range limit of 25 studs.","Bane additionally grants a speed boost for its full duration.","Grants faction reputation when selling items to their respective Antiquarian.","Makes everything darker and creates fog at long distances","Even though the Blindseer Oath grants full vision even with a Blindfold, the Talent still works.","The Talent grants immunity to the Flame Blind and Gaze Mantras.","You will now need a scaled damage of 94 (up from 63) to heal 15 health, and a scaled damage of 187 to reach 30 healing.","M1s apply stacks of Blood Plague.","On critical, all Blood Plague stacks will be consumed to grant Temporary Health if your critical attack lands, with the amount of Temporary Health given scaling on the stacks of Blood Plague.","The stacks of Blood Plague will be consumed regardless of if your critical attack lands, however.","Increases your movement speed by +2 studs/s, permanently.","Reduce posture damage taken by 10% while 2 handing a weapon (unavailable for light weapons).","Deals 35 Blunt damage with 20 Posture damage.","Cannot be buffed through damage modifiers.","Increases your Vent''s windup from 0.25s to 0.5s.","Procs all \"on Vent\" Talents and effects.","Counts as a damage modifier, so it will build up to and is affected by the damage modifier cap.","Gives Way of Navae M1s 10% more PEN. This does NOT apply to criticals unless it has the M1 tag.","This bypasses the 50% PEN cap.","The Electrify Talent tool no longer consumes health on use.","When paired with the Deepscorn Casque Talent, Already Dead, using Electrify will cause you to heal instead.","Grants full immunity to the Second Layer''s Parasites.","Drain 5% of your opponent''s armor after landing a Critical attack or Flourish. This has a 10 second cooldown and can only proc once per critical attack.","Increases your Astral enchant damage bonus on basic attacks from +20% to +25%.","Grants +20% PEN to anything that is not a weapon attack.","Primarily, this is just 20% Mantra PEN, however this will also affect non-Mantra/weapon damage sources like Crystal detonations, Eruptions, Surge overloads, and others.","Reinforce''s general resistance is affected by PEN, meaning Crippling Darkness will make things such as bleed or Steam, which bypass armor, deal more damage against Reinforce than they would otherwise.","Procs through parry, block and dodge with no cooldown.","Duration is 5 seconds + 0.02 seconds per point of Strength, lasting 7 seconds at 100 Strength.","Wrath Gems last 9 seconds with no visual indication.","On use, lose 50 Ether to travel a short distance forwards in iframes. Additionally, 20% of your current posture will be dealt to you as self-posture damage.","1 second cooldown.","Your Ardour Scream now destroys all campfires within its range.","Also doubles the range of your Ardour Scream.","Gain 10 Ether for every Mantra you have equipped.","Maximum of +140 Ether (6 innate Mantra slots, +1 from Neuroplasticity, +1 from Will o'' Wisp, +1 from Wisp Convergence, +5 from Saintsworn).","Wisp Convergence will not work if you do not have Oathless, but it will still grant its additional Wisp Mantra slot.","20 second cooldown.","Cannot parry ALL types of attacks, similar to Hunter''s Brace, you can parry kicks and some other knockback moves. Additionally, your movement speed is reduced.","Grants a Talent tool ability. Upon activating it, your body will emit light and Deep Gems cannot be procced on you. This effect lasts 3 minutes.","Gem Enhancement increases the effectiveness of your Deep Gems in PvE.","Once the duration ends, you will need to kill another player of an equal power or a boss to recharge it.","Enemies recover 20% less posture when they parry your attacks.","Grants 5% Mantra chip.","Instantly restores 15% of your maximum Ether as flat health at the cost of all of your Ether and the inability to cast Mantras for a short duration.","Acts similarly to Shield Breaker, though this does not require the Mantra to deal blunt damage.","Deals 10 true damage.","Adds a +20% damage modifier to your Strength Mantras, should they guardbreak while you have a Wrath Gem equipped onto them.","Applies a 50% slow for 5.5 seconds on proc.","10 second cooldown.","Negates up to 255 fall damage before going on a 2 minute cooldown.","The fall damage negated, before this goes on cooldown, does not reset and saves between servers.","Doubles the Ether gained from landed M1 attacks.","After using a Lightning or Gale dash, all dashes within the next 3 seconds will become enhanced. These enhanced dashes have the same effectiveness as Lightning and Gale dashes.","While similar to Lightning/Gale dashes, this is its own thing and ignores their cooldowns.","45 second cooldown.","The speed boost lasts 15 seconds despite what the description states.","This does not allow you to parry all unparryable monster attacks.","The armor durability lost is based on the amount of damage you would have taken normally.","When parrying attacks that are slide, jump, or slide only, the armor loss penalty will be greatly increased.","Reduces Burn damage by 50%","If you are utilizing Flame Within, the DoT damage reduction will be reduced down to 25%.","Reduces Bleed damage by 25%","Does not work on all Damage over Time effects.","Does not work on: Poison (hp drain) Corrupt Resonance Downside, Deep Widow Poison, Bladeharper''s Reveal, Viscosity, or Rush Hour from Bloodrend.","Replaces your aerial attack with a swooshing attack that applies wither and has innate bleed.","You cannot use Silentheart''s Relentless Hunt unless this Talent is on cooldown.","Heartwing Beat has 25 base damage, and mirrors the scaling stat from your equipped weapon. Tangentially, this Talent uses the weapon scaling formula.","For example, using Heartwing Beat on the Sword will give it 2.5 Medium scaling, while using it on the Repeater will give it 15 Light Weapon scaling.","Heartwing Beat has a 10 second cooldown.","Your dodge window is increased by 0.05s.","Grants a Talent tool that applies buffs to yourself and allies.","Hyperbody lasts 30 seconds, but the duration is reduced by 3 seconds per person affected, including yourself.","Hyperbody has a 2 minute cooldown.","Increases your movement speed by 7.5 studs/s. This speed boost will halve in effectiveness for each ally buffed.","For example, at one ally you''ll only gain +3.75 studs/s movement speed, at two allies this''ll be reduced further to +1.875 studs per second, and so on.","This counts as a speed boost for Talent effects.","Increases your passive health regeneration by 2.37x. Every ally buffed will reduce the health regeneration bonus by 10%.","Grants a 35.5% damage reduction buff. This is increased by 20% multiplicatively for every ally buffed.","For example at one ally, this will grant +42.6% damage reduction, at two allies this will grant 51.12% damage reduction, and so on.","Hyperbody can stack if one of your allies uses it, though the total effectiveness will only be 90% of the base effectiveness.","Increases the effectiveness of Blue Gems by 20%, additively.","With I''m Blue, Blue Gems reduce the total Ether cost of Mantras by 45%.","Grants one instance of knock prevention, leaving you at 1% HP on proc.","The Viscosity enchantment will be disabled while wearing this equipment.","Turns your Vent black and makes it drain 47.5 Ether on hit.","Increases your Vent''s Ether cost on successful hit from 22.5 to 47.5.","Your Vent can proc Shadowcast Talents on hit such as Twisted Puppet''s Shadowcast flames and Sightless Still.","Halves the maximum duration of any Burn that is applied to you.","Does not work on Flame Within.","Visionshaper''s Cheap Trick visual effect plays on proc.","This can proc if an attack is blocked, dodged, or parried. When this happens, the visual effect will play, but nothing will happen.","Increases the boat repair speed.","Reduces damage taken by a flat 2 (3 in Vow of Iron), not 66%.","This is applied after all other calculations, allowing you to reduce an attack''s damage to 0, however it cannot reduce an attack''s damage below 0.","Eligible summons include:","Monsters summoned from the Parasol''s Blight enchantment","Spiderlings summoned from The Weaving Web''s critical attack","Visionshaper clones from Illusory Servants and Illusory Counter","Lightning Clones","Flame Sentinel","Ineligible summons include:","Metal Turret","Visionshaper clones from Mirror Illusion","You''ll Need to Get Past Me Talent","Twisted Puppets'' puppets","This affects:","Turning in Artifacts at a banker,","Turning in the Strange Egg to the banker at Greathive Aratel,","Turning in Sacks to Mercille at the summer company outpost across from Meteor Isle,","Handing in pure ore to a Blacksmith,","Trading in Explosive Crates at Summer Isle.","Increases the posture damage bonus Might Gems innately grant, scaling on the amount of Might Gems you have equipped in your arsenal.","Grants your Might Gems an additional 2.25% posture damage multiplier per Mantra with a Might Gem equipped. This caps at +39.25% posture damage dealt on a Might Gem-equipped Mantra, assuming you have Saintsworn, Neuroplasticity, and Will o'' Wisp with all 13 of your equipped Mantras using a Might Gem.","This Talent does NOT allow you to use the Antiquarian in the First Layer if you are not Deepbound or Ignition Delver.","Your burn damage is increased based on how low your Sanity is.","Grants +0.0205 flat damage to each burn tick, for every 1% Sanity you''ve lost, capping at +2.05 damage at 0% Sanity.","Grants a random buff or affliction whenever you spit or use an emote.","List of buffs being:","Visionshaper invisibility from the Cheap Trick Talent for a short duration.","Grants you ~18% Tempo. Indicated by a light blue effect, somewhat similar to Reinforce''s vfx.","30% Posture restoration. Indicated by a metal clanging sound effect.","A free reroll, granting you an additional buff or affliction.","One 0 cost Mantra, this affects your allies as well. Indicated by a dark blue Reinforce-like vfx.","A percentage of the damage you''ve taken recently will be turned into healing.","Vent cooldown reset, allowing you to Vent again.","List of afflictions being:","Grants a random spit cooldown. This can be anywhere between 5 and 20 seconds.","Suffocation applied to self for a few seconds.","Lowers your Swingspeed. Indicated by black ''x'' marks coming off of your body.","This grants +25% damage reduction against attacks from opponents who are at least 15 studs away from you. This damage reduction is increased by 1% per additional stud of distance.","Grants true hyperarmor against attacks from opponents who are at least 15 studs away from you.","Despite what the description states, this Talent can activate if you have one PvE combat tag and one PvP combat tag.","The Bloodless Gem heal cap is increased from 15 to 30.","You will need a scaled damage of 187 (in Pathfinder) or 125 (in Vow of Iron) to reach this new heal cap.","1 minute cooldown.","Increases Katana damage by 25%.","Increases Shattered Katana, Alloyed Katana and Purple Cloud damage by 5%.","Counts as a damage modifier, so it will build up to and is affected by the damage modifier cap.","Grants a Talent tool that can only be used while under 50% health.","Grants a 25% damage buff for the duration of the buff.","The health highlight on hit effect is very similar to Soulbreaker''s Heart Reverb Talent.","Wrath Gems are active for 9 seconds with no visual indication.","Reduces the cooldown of Dancing Steps and Graceful Steps from 5 seconds to 1.","Combining this Talent with excavator gives you a chance to get 4 ores at a time.","Your boat will take 25% less damage if the person piloting it has this Talent.","Allows you to use Fang and Coil''s running critical. This attack does not work on any Cestus that already has a unique crit.","This applies to attacks used against your opponent''s back, not assassinations.","Pleeksty''s Inferno Basic Attacks now apply burn/eruptions. This has no cooldown.","Due to this equipment Talent, Pleeksty Inferno users can save a few, otherwise necessary, Talents like Flaming Flourish.","Grants a 7.5% damage buff to M1s (15% in Vow of Iron).","Killing a player will give you 2 Runes, and using this Talent''s Talent tool will consume 1 Rune, granting you buffs in exchange.","Increases your weapon damage by 50%, gives ?% damage reduction, and grants infinite Ether for 25 second.","Once the buff wears off, one of your legs will break, removing your ability to sprint for 30 seconds.","Though not stated in the Talent''s description, this also gives a speed boost for the full effect''s duration. You''ll still be at a net negative in terms of movement speed, but you''ll be able to benefit from speed boost reliant Talents such as Speed Demon.","Storm Strikes from other Specialist Equipment Talents now apply the Stormcall Shock status effect, causing your opponent to take damage if they cast Mantras during its duration.","Stormcall Shock deals 15 Gale and Thunder damage, applies Shock for 1 second or 1 Surge Rod, and winded for 2 seconds upon casting any Mantra.","This applies a 5% slow per combat tag you have. This slow lasts 1 second.","Makes you immune to the ragdoll and movement speed debuff of the Wind from the Second Layer and Moon''s Eyrie.","Reduces the damage taken from Acid Rain.","Grants a 20% damage buff to your slide-jump Wind Blade. Also increases its range.","Only grants a 10% damage buff, the Talent was nerfed but the description was never changed.","Counts as a damage modifier, so it will build up to and is affected by the damage modifier cap.","Your Critical attacks will apply Daze on hit.","For the next 4s after landing your Critical attack, if you were to be hit by any Mantra, you''ll automatically dodge the Mantra, voiding its damage. The dodge vfx is similar to Nautilodaunt''s Vent vfx, but it displaces you physically.","13 second cooldown.","Has a 35% chance to proc with a 3 cooldown per proc attempt, going on cooldown even if it fails to proc.","Hunger and thirst steal formula is as follows: 1.95 * ln(D) + 1.075, where D = scaled damage dealt. A calculator is listed [https://www.desmos.com/calculator/yktgme7xnc here].","The hunger and thirst steal are NOT affected by damage modifiers or resistances, rather exclusively being based on scaled damage dealt.","Acts similarly to and stacks additively with the Gluttony enchant.","Procs on: The Long Tong of The Law, The Flippers of Fate, The Pastry Paster, and Fondant Splitter.","Reduces the normal stun duration from 1.05 seconds to 0.7 seconds.","Stacks additively with Action Surge.","Both this and Action Surge are applied before Lightning Cloak''s swing speed multiplier.","This has a proc window of 5 seconds after using Inhale.","Storm Strikes from this Talent deal 0.125 * (Thundercall + Galebreathe investment) Thundercall damage, capping at 25 damage with 100 points invested in both Attunements.","These Storm Strikes proc Grounding Bolt.","Increases the dodge window based on your Thundercall investment.","Increases your dodge cooldown for both dodge types to 2.4 seconds regardless of your Thundercall investment.","On proc, a wind of gale will erupt from your legs, signifying that the effect is active.","The Wither applied is based off your weapon''s scaled damage.","The wind shield grants one (1) autoparry frame and has a cooldown of 10 seconds.","The wind shield lasts a few seconds or until you get hit (in which case, it will automatically parry the attack), cast any mantra, feint any attack, or use your critical attack.","Some mantras, like Mecha Gatling, can build up stacks for this.","If you have the wind shield active and a Talent that allows you to parry unparryable monster attacks, such as Force Your Way or Diver''s Resilience, you will autoparry them.","Grants a 10% speed boost for 8 seconds.","10 second cooldown.","Increases the time it takes for the Second Layer''s parasites to kill you.","Negates damage buffs from weather:","Frostdraw will no longer apply its 5% damage buff during snow.","Thundercall will no longer gain its 5% damage buff during rain. Stratoshock will also no longer apply its additional 5% damage buff.","Makes you entirely immune to the Second Layer''s Parasites, but at a cost of granting you a mobility debuff.","Grants 50% of the Bloodless Gem healing as Temporary Health.","Necrotic Set: Necrotic Cowl, Necrotic Mask","Bloodcurdle Set: Bloodcurdle Cowl, Bloodcurdle Mask","On use, this summons two allied Blacksteel Pirates to assist you. 5 minute cooldown.","Ossified Black Set: Ossified Black Helm, Ossified Black Pauldrons","Blackalloy Set: Blackalloy Helm, Blackalloy Pauldrons","Regenerative Set: Regenerative Pendant, Regenerative Earrings","Trueblood Set: Trueblood Pendant, Trueblood Earrings","Hardened Enforcer Set: Hardened Enforcer Plate, Hardened Enforcer Boots","Reinforced Enforcer Set: Reinforced Enforcer Plate, Reinforced Enforcer Boots","When landing a Mantra with a Warped Blue Gem equipped, gain the Etherguard status effect, granting you damage reduction to Mantras. This damage reduction scales on the Ether cost of the Mantra you got hit by.","In PvE, Etherguard additionally grants elemental damage reduction.","Bluestone Set: Bluestone Pauldrons, Bluestone Boots","This applies the Fearful status effect for 19 seconds.","Wrath gems have a 10 second cooldown, meaning you can potentially disable your opponent''s ability to use their critical indefinitely.","Reinforced War Set: Reinforced War Helmet, Reinforced War Plate, Reinforced War Boots","If all of your Mantras have a Might Gem equipped, hitting your opponent''s block with Mantras will restore your posture.","This functions somewhat similarly to Arcwarder Mantras while in Arc suit.","Ascended Outlaw Set: Ascended Outlaw Hat, Ascended Outlaw Robes, Ascended Outlaw Boots","To proc Shock Trooper Specialist, you must meet the a damage threshold of 600 damage dealt with Thunder and Gale Mantras. Each point in Galebreathe or Thundercall reduces this threshold by 1, capping at 400 damage dealt for a Storm Strike with 100 Gale and Thunder.","The damage threshold does not consider damage multipliers, but it does consider resistances, making it harder to proc the higher Wind/Lightning res your opponent has.","The Storm Strikes deal 40 Thundercall damage.","Shock Trooper Specialist has no cooldown, proccing on almost every hit in PvE due to the PvE damage multipliers. However, this only has 1.08x PvE scaling.","Additionally, this turns your Electro Carve, Grand Javelin, and Thunder Kick green, and your Astral Wind, Champion''s Whirlthrow, and Gale Lunge yellow. These Mantras will gain a 15% damage buff to their base damage (not a damage modifier) as well.","The storm strikes proc Grounding Bolt.","Specialist Set: Specialist Helmet, Specialist Plate, Specialist Boots","Ether Refined Set: Ether Refined Brim, Ether Refined Mantle","Sorcerer Set: Sorcerer''s Brim, Sorcerer''s Mantle"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('ether-blade', 'Ether Blade', '{{anch|Ether Conduit (Vow of Iron)|Ether Conduit}}', 'Common', 'Draw your foes ether into your weapon when you parry ether-based attacks. Gain Ether when you parry mantras.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('pleekstys-wrath', 'Pleeksty''s Wrath', '{{anch|Flame Warden (Vow of Iron)|Flame Warden}}', 'Common', 'After dealing 500 damage with Flame Mantras, call forth a hail of firey swords. (+4 Sanity)', '["Spawns swords from the sky, similarly to First Light''s critical attack."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('hardened-shell', 'Hardened Shell', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Your Natural Armor grows sturdier, being able to take more hits before breaking.', '["Gives a flat amount of armor durability to your Natural Armor."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('steady-mind', 'Steady Mind', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Despite the finality of your mind and body succumbing to the effects of the depths, you manage to ward it off for a little longer.', '["You can spend more time in The Depths before gaining Afflictions."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('glide-mastery', 'Glide Mastery', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Experience using the glider you crafted results in you being able to glide faster in the air. You''ve also trained to quickly pull it out in dire situations, resulting in you no longer taking fall damage.', '["Increases glide speed and grants full fall damage immunity."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('acute-hearing', 'Acute Hearing', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'After years of using Echolocation, you''ve trained your ears to sense danger from even further away. You are also able to sense when someone completes a job.', '["Plays a sound effect whenever Echolocation procs."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('from-the-ashes', 'From The Ashes', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Using an Etris Flask when at 30% health or below now grants you a damage buff and resistance buff for 30 seconds.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('lone-wolf', 'Lone Wolf', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Despite the loyalty of your allies, you recognize that you sometimes need to hunt alone. Deal more damage to targets who are only combat tagged by you.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scales-of-the-edenkite', 'Scales of The Edenkite', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'In order to resolve conflict in Lumen, you need to be able to handle any situation thrown at you. Activate your Scales to reduce all damage taken by 80% and de-aggro enemies briefly.', '["Gives a Talent Tool.","The buff lasts 5 seconds.","3 minute cooldown.","The deaggro effect is extremely ineffective, as enemies are very likely to reaggro as soon as the effect ends. Additionally, it does not work against bosses or in Depths trials.","The Talent tool''s description is very outdated, listing incorrect information."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('scholars-mark', 'Scholar''s Mark', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'You now are able to inflict yourself with a Mark. The duration of this scales with how many people you inflict with the effect as well.', '["Capra Marks will now buff yourself.","The duration of self-applied Capra Marks scale with how many people you''ve buffed."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('largent', 'Largent', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Your diplomatic skills extend into your ability to barter. Gain 300 extra notes per chest when turning in a sack.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('tailor-made', 'Tailor Made', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'These were specifically made for your kind. Etris Flasks now heal you 45% more than usual.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('mothwing-defense', 'Mothwing Defense', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Further refining how sharp your antennae, you can now immediately recognize a sneak attack and brace yourself for it. Reduce all backhit damage by 50%.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('navaes-technique', 'Navae''s Technique', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'A passed down technique from generations ago to refine your Ether control. Reduce how much ether it takes to cast mantras by 30%.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('innate-agility', 'Innate Agility', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'You hinge on your instincts to keep you alive, even in battle. Slightly increase your dodge frames.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('retrograde', 'Retrograde', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Your existence is... questionable. No one understands where you have come from. Your ability reflects this, activate to start your Retrograde timer. Activating the ability again will reverse your actions, with the cooldown scaling with the time.', '["Grants a Talent tool. On use, your current position will be anchored, and you can perform any action. If Retrograde is cast again or if 5 seconds pass, your actions will be done in reverse, returning you to your original location.","This will heal yourself to the amount of health you had when you initially used the ability."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('depths-denizen', 'Depth''s Denizen', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'The city you once called home is now your only way out of the depths, perhaps you can use this to your advantage. Gain extra leeway when attempting to escape the depths.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('weapons-training', 'Weapons Training', '{{anch|Innate (Vow of Iron)|Innate}}', 'Race', 'Training with different weapons taught you how to wield all of them more proficiently. Gain slightly extra weapon scaling on all weapons you use.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('true-mirage-clone', 'True Mirage Clone', '{{anch|The Emperor''s Blade (Vow of Iron)|The Emperor''s Blade}}', 'Rare', 'Successfully dodging leaves behind a heat mirage clone that sets enemies that swung at you on fire.', '["Has a 20s Cooldown"]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('jackpot', 'Jackpot', '{{anch|Toxic Personality (Vow of Iron)|Toxic Personality}}', 'Common', 'Charmed enemies now have a chance to be hit critically, multiplying the damage.', '["There is a ?% chance that your hits against a Charmed target will be a critical hit, dealing significantly more damage."]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('taunting-tongue', 'Taunting Tongue', '{{anch|Toxic Personality (Vow of Iron)|Toxic Personality}}', 'Common', 'Your taunt now applies Madness.', '[]');
INSERT INTO talents (id, name, tree, rarity, description, notes) VALUES ('voice-of-the-mad-god', 'Voice of the Mad God', '{{anch|Toxic Personality (Vow of Iron)|Toxic Personality}}', 'Common', 'Any time you apply charm it now applies "Madness" to enemies directly.', '[]');

